fn handle_task_inspect(id: Value, params: Option<Value>) -> JsonRpcResponse<Value> {
    let params: TaskInspectParams = match parse_params(params) {
        Ok(params) => params,
        Err(message) => return error_response(id, -32602, &message),
    };
    if params.task_id.trim().is_empty() {
        return error_response(id, -32602, "invalid params: task_id must not be empty");
    }
    let store = match BrownieStore::from_env_or_cwd() {
        Ok(store) => store,
        Err(error) => return error_response(id, -32603, &format!("internal error: {error}")),
    };
    let task = match store.tasks().get_task(&params.task_id) {
        Ok(Some(record)) => record,
        Ok(None) => return error_response(id, -32602, "invalid params: task not found"),
        Err(error) => return error_response(id, -32603, &format!("internal error: {error}")),
    };
    let parent_join_readiness_summary =
        match parent_join_readiness_summary_for_child_inspection(&store, &task) {
            Ok(summary) => summary,
            Err(message) => {
                return error_response(id, -32603, &format!("internal error: {message}"))
            }
        };
    let consumed_parent_join_recovery_summary =
        match consumed_parent_join_recovery_summary_for_child_inspection(&store, &task) {
            Ok(summary) => summary,
            Err(message) => {
                return error_response(id, -32603, &format!("internal error: {message}"))
            }
        };
    match inspect_run(&store, &task.run_id) {
        Ok(run) => result_response(
            id,
            json!(TaskInspectResult {
                task,
                run,
                parent_join_readiness_summary,
                consumed_parent_join_recovery_summary
            }),
        ),
        Err(message) => error_response(id, -32602, &message),
    }
}

fn handle_task_list(id: Value, params: Option<Value>) -> JsonRpcResponse<Value> {
    let params = match params {
        Some(params) => match serde_json::from_value::<TaskListParams>(params) {
            Ok(params) => Some(params),
            Err(error) => return error_response(id, -32602, &format!("invalid params: {error}")),
        },
        None => None,
    };
    let store = match BrownieStore::from_env_or_cwd() {
        Ok(store) => store,
        Err(error) => return error_response(id, -32603, &format!("internal error: {error}")),
    };

    match store.tasks().list_tasks() {
        Ok(tasks) => {
            let progress_overview = match task_list_progress_overview(&store, &tasks) {
                Ok(progress_overview) => progress_overview,
                Err(message) => {
                    return error_response(id, -32603, &format!("internal error: {message}"))
                }
            };
            let mut result = TaskListResult {
                tasks,
                progress_overview,
            };
            apply_task_list_transport_bounds(
                &mut result,
                params.as_ref().and_then(|p| p.bounds.as_ref()),
            );
            result_response(id, json!(result))
        }
        Err(error) => error_response(id, -32603, &format!("internal error: {error}")),
    }
}

fn apply_task_list_transport_bounds(result: &mut TaskListResult, bounds: Option<&TaskListBounds>) {
    let Some(bounds) = bounds else {
        return;
    };

    truncate_to_bound(
        &mut result.progress_overview.headless_route_candidates,
        bounds.max_headless_route_candidates,
        MAX_TASK_LIST_TRANSPORT_ROUTE_CANDIDATES,
    );
    truncate_task_rows_preserving_route_candidates(
        &mut result.tasks,
        &result.progress_overview.headless_route_candidates,
        bounds.max_tasks,
        MAX_TASK_LIST_TRANSPORT_TASKS,
    );
    truncate_task_goal_fields(
        &mut result.tasks,
        bounds.max_task_goal_chars,
        MAX_TASK_LIST_TRANSPORT_GOAL_CHARS,
    );
    truncate_to_bound(
        &mut result.progress_overview.root_task_ids,
        bounds.max_task_ids,
        MAX_TASK_LIST_TRANSPORT_IDS,
    );
    truncate_to_bound(
        &mut result.progress_overview.runnable_task_ids,
        bounds.max_task_ids,
        MAX_TASK_LIST_TRANSPORT_IDS,
    );
    truncate_to_bound(
        &mut result.progress_overview.blocked_task_ids,
        bounds.max_task_ids,
        MAX_TASK_LIST_TRANSPORT_IDS,
    );
    truncate_to_bound(
        &mut result.progress_overview.terminal_task_ids,
        bounds.max_task_ids,
        MAX_TASK_LIST_TRANSPORT_IDS,
    );
    truncate_to_bound(
        &mut result.progress_overview.parent_join_ready_task_ids,
        bounds.max_task_ids,
        MAX_TASK_LIST_TRANSPORT_IDS,
    );
    truncate_to_bound(
        &mut result.progress_overview.stage_counts,
        bounds.max_groups,
        MAX_TASK_LIST_TRANSPORT_GROUPS,
    );
    truncate_to_bound(
        &mut result.progress_overview.next_action_sets,
        bounds.max_groups,
        MAX_TASK_LIST_TRANSPORT_GROUPS,
    );
    for set in &mut result.progress_overview.next_action_sets {
        truncate_to_bound(
            &mut set.task_ids,
            bounds.max_group_task_ids,
            MAX_TASK_LIST_TRANSPORT_GROUP_IDS,
        );
    }
    truncate_to_bound(
        &mut result.progress_overview.blocked_sets,
        bounds.max_groups,
        MAX_TASK_LIST_TRANSPORT_GROUPS,
    );
    for set in &mut result.progress_overview.blocked_sets {
        truncate_to_bound(
            &mut set.task_ids,
            bounds.max_group_task_ids,
            MAX_TASK_LIST_TRANSPORT_GROUP_IDS,
        );
    }
    truncate_to_bound(
        &mut result.progress_overview.nodes,
        bounds.max_nodes,
        MAX_TASK_LIST_TRANSPORT_NODES,
    );
    truncate_to_bound(
        &mut result.progress_overview.edges,
        bounds.max_edges,
        MAX_TASK_LIST_TRANSPORT_EDGES,
    );
}

fn truncate_to_bound<T>(items: &mut Vec<T>, requested: Option<usize>, ceiling: usize) {
    if let Some(requested) = requested {
        items.truncate(requested.min(ceiling));
    }
}

fn truncate_task_goal_fields(tasks: &mut [TaskRecord], requested: Option<usize>, ceiling: usize) {
    let Some(requested) = requested else {
        return;
    };
    let limit = requested.min(ceiling);
    for task in tasks {
        task.goal = task.goal.chars().take(limit).collect();
    }
}

fn truncate_task_rows_preserving_route_candidates(
    tasks: &mut Vec<TaskRecord>,
    route_candidates: &[TaskListHeadlessRouteCandidate],
    requested: Option<usize>,
    ceiling: usize,
) {
    let Some(requested) = requested else {
        return;
    };
    let limit = requested.min(ceiling);
    if tasks.len() <= limit {
        return;
    }

    let mut candidate_keys = std::collections::BTreeSet::new();
    for candidate in route_candidates {
        if let (Some(task_id), Some(run_id)) = (&candidate.task_id, &candidate.run_id) {
            candidate_keys.insert((task_id.clone(), run_id.clone()));
        }
    }
    if candidate_keys.is_empty() {
        tasks.truncate(limit);
        return;
    }

    let mut selected = Vec::new();
    let mut remaining = Vec::new();
    for task in std::mem::take(tasks) {
        if candidate_keys.contains(&(task.task_id.clone(), task.run_id.clone())) {
            selected.push(task);
        } else {
            remaining.push(task);
        }
    }
    selected.extend(remaining);
    selected.truncate(limit);
    *tasks = selected;
}

fn append_headless_run_completion_finalized_event(
    store: &BrownieStore,
    finalization: &HeadlessRunCompletionFinalization,
    owner: &HeadlessRunCompletionFinalizationOwner,
) -> anyhow::Result<()> {
    let Some(record) = store.tasks().get_task(&owner.task_id)? else {
        anyhow::bail!("completion finalization owner task disappeared");
    };
    if record.run_id != owner.run_id {
        anyhow::bail!("completion finalization owner run changed");
    }
    let already_recorded = store
        .tasks()
        .read_ledger_events(&owner.run_id)?
        .iter()
        .any(|event| {
            event.kind == LedgerEventKind::HeadlessRunCompletionFinalized
                && event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("finalization_fingerprint"))
                    .and_then(Value::as_str)
                    == Some(finalization.finalization_fingerprint.as_str())
        });
    if already_recorded {
        return Ok(());
    }
    store.tasks().append_task_event_with_payload(
        &record,
        LedgerEventKind::HeadlessRunCompletionFinalized,
        Some(json!({
            "session_id": finalization.session_id,
            "drive_id": finalization.drive_id,
            "start_session_sequence": finalization.start_session_sequence,
            "end_session_sequence": finalization.end_session_sequence,
            "closure_fingerprint": finalization.closure_fingerprint,
            "progress_fingerprint": finalization.progress_fingerprint,
            "aggregate_sequence": finalization.aggregate_sequence,
            "owner_task_id": owner.task_id,
            "owner_run_id": owner.run_id,
            "terminal_completion_fingerprint": owner.terminal_completion_fingerprint,
            "terminal_task_count": finalization.terminal_task_count,
            "total_task_count": finalization.total_task_count,
            "finalization_fingerprint": finalization.finalization_fingerprint,
            "next_action": finalization.next_action,
            "reason": "Headless run completion closure finalized through bounded runtime-owned finalization routing."
        })),
    )
}

fn handle_mode_list(id: Value) -> JsonRpcResponse<Value> {
    let store = match BrownieStore::from_env_or_cwd() {
        Ok(store) => store,
        Err(error) => return error_response(id, -32603, &format!("internal error: {error}")),
    };
    let modes = match workspace_mode_policies(&store) {
        Ok(policies) => policies.into_iter().map(mode_summary).collect(),
        Err(message) => return error_response(id, -32603, &format!("internal error: {message}")),
    };
    result_response(id, json!(ModeListResult { modes }))
}

fn handle_permission_check(id: Value, params: Option<Value>) -> JsonRpcResponse<Value> {
    let params: PermissionCheckParams = match parse_params(params) {
        Ok(params) => params,
        Err(message) => return error_response(id, -32602, &message),
    };

    let store = match BrownieStore::from_env_or_cwd() {
        Ok(store) => store,
        Err(error) => return error_response(id, -32603, &format!("internal error: {error}")),
    };
    let policy = match resolve_workspace_mode_policy(&store, &params.mode_id) {
        Ok(Some(policy)) => policy,
        Ok(None) => return error_response(id, -32602, "invalid params: unknown mode_id"),
        Err(message) => return error_response(id, -32603, &format!("internal error: {message}")),
    };
    let action = runtime_action_from_name(&params.action);
    let decision = RuntimePermissionGate::check(&policy, action);

    result_response(
        id,
        json!(PermissionCheckResult {
            mode_id: policy.mode_id,
            action: params.action,
            allowed: decision.allowed,
            reason: decision.reason,
        }),
    )
}

fn handle_mode_get(id: Value, params: Option<Value>) -> JsonRpcResponse<Value> {
    let params: ModeGetParams = match parse_params(params) {
        Ok(params) => params,
        Err(message) => return error_response(id, -32602, &message),
    };

    let store = match BrownieStore::from_env_or_cwd() {
        Ok(store) => store,
        Err(error) => return error_response(id, -32603, &format!("internal error: {error}")),
    };

    match resolve_workspace_mode_policy(&store, &params.mode_id) {
        Ok(Some(policy)) => result_response(id, json!(mode_summary(policy))),
        Ok(None) => error_response(id, -32602, "invalid params: unknown mode_id"),
        Err(message) => error_response(id, -32603, &format!("internal error: {message}")),
    }
}

fn read_existing_run_events(
    store: &BrownieStore,
    run_id: &str,
) -> Result<Vec<LedgerEvent>, String> {
    match store.tasks().get_task_by_run_id(run_id) {
        Ok(Some(_)) => {}
        Ok(None) => return Err("invalid params: run not found".to_string()),
        Err(error) => return Err(format!("invalid params: {error}")),
    }
    store
        .tasks()
        .read_ledger_events(run_id)
        .map_err(|error| format!("invalid params: {error}"))
}

fn list_proposals(
    store: &BrownieStore,
    run_id: &str,
) -> Result<Vec<WorkspacePatchProposalSummary>, String> {
    let events = read_existing_run_events(store, run_id)?;
    let all_events = events.clone();
    Ok(events
        .into_iter()
        .filter(|event| event.kind == LedgerEventKind::WorkspacePatchProposed)
        .filter_map(|event| {
            let payload = sanitize_ledger_payload(event.payload)?;
            let proposal_id = payload.get("proposal_id")?.as_str()?.to_string();
            let approval = approval_state(&all_events, &proposal_id);
            Some(WorkspacePatchProposalSummary {
                proposal_id,
                path: payload.get("path")?.as_str()?.to_string(),
                operation: payload.get("operation")?.as_str()?.to_string(),
                content_preview: payload.get("content_preview")?.as_str()?.to_string(),
                content_chars: payload.get("content_chars")?.as_u64()? as usize,
                truncated: payload.get("truncated")?.as_bool()?,
                validation_status: payload.get("validation_status")?.as_str()?.to_string(),
                validation_reason: payload
                    .get("validation_reason")
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
                diff_preview: payload
                    .get("diff_preview")
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
                diff_truncated: payload.get("diff_truncated")?.as_bool()?,
                diff_redacted: payload.get("diff_redacted")?.as_bool()?,
                hunk_count: payload
                    .get("hunk_count")
                    .and_then(Value::as_u64)
                    .and_then(|value| usize::try_from(value).ok()),
                hunk_fingerprint: payload
                    .get("hunk_fingerprint")
                    .and_then(Value::as_str)
                    .map(ToString::to_string),
                approval_status: approval.approval_status,
                approval_reason: approval.approval_reason,
                approval_reason_redacted: approval.approval_reason_redacted,
                approved_at: approval.approved_at,
                rejected_at: approval.rejected_at,
                latest_apply_plan: latest_apply_plan(
                    &all_events,
                    payload.get("proposal_id")?.as_str()?,
                ),
                latest_snapshot: latest_snapshot(
                    &all_events,
                    payload.get("proposal_id")?.as_str()?,
                ),
            })
        })
        .collect())
}

struct ApprovalState {
    approval_status: String,
    approval_reason: Option<String>,
    approval_reason_redacted: bool,
    approved_at: Option<String>,
    rejected_at: Option<String>,
}

fn approval_state(events: &[LedgerEvent], proposal_id: &str) -> ApprovalState {
    let mut state = ApprovalState {
        approval_status: "Pending".to_string(),
        approval_reason: None,
        approval_reason_redacted: false,
        approved_at: None,
        rejected_at: None,
    };
    for event in events {
        if !matches!(
            event.kind,
            LedgerEventKind::WorkspacePatchApproved | LedgerEventKind::WorkspacePatchRejected
        ) {
            continue;
        }
        let Some(payload) = sanitize_ledger_payload(event.payload.clone()) else {
            continue;
        };
        if payload.get("proposal_id").and_then(Value::as_str) != Some(proposal_id) {
            continue;
        }
        state.approval_status = payload
            .get("approval_status")
            .and_then(Value::as_str)
            .unwrap_or("Pending")
            .to_string();
        state.approval_reason = payload
            .get("approval_reason")
            .and_then(Value::as_str)
            .map(ToString::to_string);
        state.approval_reason_redacted = payload
            .get("approval_reason_redacted")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        state.approved_at = payload
            .get("approved_at")
            .and_then(Value::as_str)
            .map(ToString::to_string);
        state.rejected_at = payload
            .get("rejected_at")
            .and_then(Value::as_str)
            .map(ToString::to_string);
    }
    state
}

fn latest_apply_plan(
    events: &[LedgerEvent],
    proposal_id: &str,
) -> Option<WorkspacePatchApplyPlanSummary> {
    events.iter().rev().find_map(|event| {
        if event.kind != LedgerEventKind::WorkspacePatchApplyPlanCreated {
            return None;
        }
        let payload = sanitize_ledger_payload(event.payload.clone())?;
        if payload.get("proposal_id").and_then(Value::as_str) != Some(proposal_id) {
            return None;
        }
        Some(build_apply_plan_summary(
            proposal_id,
            payload.get("plan_id")?.as_str()?,
            payload.get("status")?.as_str()?,
            payload
                .get("operation")
                .and_then(Value::as_str)
                .unwrap_or(WorkspacePatchOperation::ReplaceFile.as_str()),
        ))
    })
}

fn latest_snapshot(
    events: &[LedgerEvent],
    proposal_id: &str,
) -> Option<WorkspacePatchPreflightSnapshotSummary> {
    events.iter().rev().find_map(|event| {
        if event.kind != LedgerEventKind::WorkspacePatchPreflightSnapshotCreated {
            return None;
        }
        let payload = sanitize_ledger_payload(event.payload.clone())?;
        if payload.get("proposal_id").and_then(Value::as_str) != Some(proposal_id) {
            return None;
        }
        Some(WorkspacePatchPreflightSnapshotSummary {
            proposal_id: proposal_id.to_string(),
            snapshot_id: payload.get("snapshot_id")?.as_str()?.to_string(),
            path: payload.get("path")?.as_str()?.to_string(),
            canonical_path_hash: payload.get("canonical_path_hash")?.as_str()?.to_string(),
            file_exists: payload.get("file_exists")?.as_bool()?,
            file_kind: payload.get("file_kind")?.as_str()?.to_string(),
            file_size_bytes: payload.get("file_size_bytes").and_then(Value::as_u64),
            file_modified_unix_ms: payload.get("file_modified_unix_ms").and_then(Value::as_i64),
            file_sha256: payload
                .get("file_sha256")
                .and_then(Value::as_str)
                .map(ToString::to_string),
            captured_at: payload.get("captured_at")?.as_str()?.to_string(),
            stale: payload.get("stale")?.as_bool()?,
            stale_reason: payload
                .get("stale_reason")
                .and_then(Value::as_str)
                .map(ToString::to_string),
        })
    })
}

fn build_apply_plan_summary(
    proposal_id: &str,
    plan_id: &str,
    status: &str,
    operation: &str,
) -> WorkspacePatchApplyPlanSummary {
    let pass = |name: &str| WorkspacePatchApplyCheckSummary {
        name: name.to_string(),
        status: "Pass".to_string(),
        reason: None,
    };
    let mut checklist = vec![
        pass("proposal_exists"),
        pass("proposal_is_valid"),
        pass("proposal_is_approved"),
        pass("target_path_safe"),
    ];
    if operation == WorkspacePatchOperation::CreateFile.as_str() {
        checklist.extend([
            pass("target_parent_exists"),
            pass("target_parent_directory"),
            pass("target_parent_not_symlink"),
            pass("target_absent"),
        ]);
    } else if operation == WorkspacePatchOperation::DeleteFile.as_str() {
        checklist.extend([
            pass("target_file_exists"),
            pass("target_file_regular"),
            pass("target_file_not_symlink"),
            pass("target_file_hash_captured"),
        ]);
    } else {
        checklist.extend([
            pass("target_file_exists"),
            pass("target_file_regular"),
            pass("target_file_utf8"),
            pass("target_file_hash_captured"),
        ]);
    }
    checklist.extend([
        pass("proposal_not_stale"),
        pass("diff_preview_available"),
        pass("sensitive_content_not_detected"),
    ]);
    checklist.push(WorkspacePatchApplyCheckSummary {
        name: "apply_execution_available".to_string(),
        status: "Pass".to_string(),
        reason: Some("Patch apply is available through proposal.apply.".to_string()),
    });
    WorkspacePatchApplyPlanSummary {
        proposal_id: proposal_id.to_string(),
        plan_id: plan_id.to_string(),
        status: status.to_string(),
        checklist,
    }
}

fn now_rfc3339() -> String {
    time::OffsetDateTime::now_utc()
        .format(&time::format_description::well_known::Rfc3339)
        .unwrap_or_else(|_| "1970-01-01T00:00:00Z".to_string())
}

fn sanitize_approval_reason(reason: Option<String>) -> (Option<String>, bool) {
    let Some(reason) = reason else {
        return (None, false);
    };
    let bounded = preview_with_limit(&reason, 1000);
    if scan_text_for_sensitive_content(&bounded) || bounded.contains("sk-") {
        (Some("[redacted]".to_string()), true)
    } else {
        (Some(bounded), false)
    }
}

fn approve_proposal(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
    reason: Option<String>,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchApplyPlanSummary,
    ),
    String,
> {
    let task = store
        .tasks()
        .get_task_by_run_id(run_id)
        .map_err(|e| format!("invalid params: {e}"))?
        .ok_or_else(|| "invalid params: run not found".to_string())?;
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    if proposal.validation_status != "Valid" {
        return Err("invalid params: only valid proposals can be approved".to_string());
    }
    if proposal.approval_status != "Pending" {
        return Err("invalid params: proposal is not pending".to_string());
    }
    let approved_at = now_rfc3339();
    let (reason, reason_redacted) = sanitize_approval_reason(reason);
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchApproved,
            Some(json!({
                "proposal_id": proposal_id,
                "approval_status": "Approved",
                "approval_reason": reason,
                "approval_reason_redacted": reason_redacted,
                "approved_at": approved_at,
            })),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    let plan_id = format!("plan_{}", uuid::Uuid::new_v4().simple());
    let apply_plan = build_apply_plan_summary(
        proposal_id,
        &plan_id,
        "PendingPreflight",
        &proposal.operation,
    );
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchApplyPlanCreated,
            Some(json!({
                "proposal_id": proposal_id,
                "plan_id": plan_id,
                "operation": &proposal.operation,
                "status": "PendingPreflight",
                "check_count": apply_plan.checklist.len(),
                "failed_checks": [],
            })),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    Ok((inspect_proposal(store, run_id, proposal_id)?, apply_plan))
}

fn reject_proposal(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
    reason: Option<String>,
) -> Result<WorkspacePatchProposalSummary, String> {
    let task = store
        .tasks()
        .get_task_by_run_id(run_id)
        .map_err(|e| format!("invalid params: {e}"))?
        .ok_or_else(|| "invalid params: run not found".to_string())?;
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    if proposal.approval_status != "Pending" {
        return Err("invalid params: proposal is not pending".to_string());
    }
    let rejected_at = now_rfc3339();
    let (reason, reason_redacted) = sanitize_approval_reason(reason);
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchRejected,
            Some(json!({
                "proposal_id": proposal_id,
                "approval_status": "Rejected",
                "approval_reason": reason,
                "approval_reason_redacted": reason_redacted,
                "rejected_at": rejected_at,
            })),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    inspect_proposal(store, run_id, proposal_id)
}

