fn inspect_apply_capability(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchApplyCapabilitySummary,
    ),
    String,
> {
    let task = store
        .tasks()
        .get_task_by_run_id(run_id)
        .map_err(|e| format!("invalid params: {e}"))?
        .ok_or_else(|| "invalid params: run not found".to_string())?;
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    let snapshot = proposal.latest_snapshot.as_ref();
    let mut checklist = vec![apply_capability_check("proposal_exists", "Pass", None)];

    if proposal.validation_status == "Blocked" {
        checklist.push(apply_capability_check(
            "proposal_is_valid",
            "Blocked",
            proposal.validation_reason.as_deref(),
        ));
    } else if proposal.validation_status == "Valid" {
        checklist.push(apply_capability_check("proposal_is_valid", "Pass", None));
    } else {
        checklist.push(apply_capability_check(
            "proposal_is_valid",
            "Fail",
            proposal
                .validation_reason
                .as_deref()
                .or(Some("Proposal validation status is not Valid.")),
        ));
    }

    checklist.push(if proposal.approval_status == "Approved" {
        apply_capability_check("proposal_is_approved", "Pass", None)
    } else {
        apply_capability_check(
            "proposal_is_approved",
            "Fail",
            Some("Proposal is not approved."),
        )
    });
    checklist.push(if snapshot.is_some() {
        apply_capability_check("proposal_has_preflight_snapshot", "Pass", None)
    } else {
        apply_capability_check(
            "proposal_has_preflight_snapshot",
            "Fail",
            Some("Run proposal.preflight before final review."),
        )
    });
    checklist.push(match snapshot {
        Some(snapshot) if !snapshot.stale => {
            apply_capability_check("proposal_not_stale", "Pass", None)
        }
        Some(snapshot) => apply_capability_check(
            "proposal_not_stale",
            "Fail",
            snapshot
                .stale_reason
                .as_deref()
                .or(Some("Latest preflight snapshot is stale.")),
        ),
        None => apply_capability_check(
            "proposal_not_stale",
            "Skipped",
            Some("No preflight snapshot is available."),
        ),
    });
    checklist.push(if proposal.diff_preview.is_some() {
        apply_capability_check("sanitized_diff_preview_available", "Pass", None)
    } else {
        apply_capability_check(
            "sanitized_diff_preview_available",
            "Fail",
            Some("Sanitized diff preview is unavailable."),
        )
    });
    checklist.push(
        if proposal.diff_redacted || proposal.content_preview == "[redacted]" {
            apply_capability_check(
                "sensitive_content_not_detected",
                "Blocked",
                Some("Sensitive-like content was detected or redacted."),
            )
        } else {
            apply_capability_check("sensitive_content_not_detected", "Pass", None)
        },
    );
    checklist.push(apply_capability_check(
        "no_raw_content_exposed",
        "Pass",
        None,
    ));
    checklist.push(apply_capability_check(
        "apply_execution_supported",
        "Pass",
        Some("Patch apply execution is available through proposal.apply."),
    ));

    let blocked_checks: Vec<String> = checklist
        .iter()
        .filter(|c| c.status == "Blocked")
        .map(|c| c.name.clone())
        .collect();
    let failed_checks: Vec<String> = checklist
        .iter()
        .filter(|c| c.status == "Fail")
        .map(|c| c.name.clone())
        .collect();
    let checked_at = now_rfc3339();
    let capability_id = format!("apply_capability_{}", uuid::Uuid::new_v4().simple());
    let can_apply_now = failed_checks.is_empty() && blocked_checks.is_empty();
    let reason = if can_apply_now {
        "proposal.apply can execute after explicit one-time authorization and expected target hash verification."
    } else {
        "Proposal is missing required apply gates."
    }
    .to_string();
    let required_gates = vec![
        "proposal_valid".to_string(),
        "proposal_approved".to_string(),
        "preflight_snapshot_exists".to_string(),
        "proposal_not_stale".to_string(),
        "readiness_ready".to_string(),
        "operator_apply_authorization".to_string(),
        "expected_target_hash".to_string(),
        "runtime_apply_supported".to_string(),
    ];
    let capability = WorkspacePatchApplyCapabilitySummary {
        proposal_id: proposal_id.to_string(),
        capability_id: capability_id.clone(),
        apply_supported: true,
        apply_enabled: can_apply_now,
        mode: "controlled_apply".to_string(),
        reason,
        required_gates,
        can_apply_now,
        checked_at: checked_at.clone(),
        check_count: checklist.len(),
        failed_checks,
        blocked_checks,
        checklist,
    };
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchApplyCapabilityChecked,
            Some(json!({
                "proposal_id": proposal_id,
                "capability_id": capability_id,
                "apply_supported": capability.apply_supported,
                "apply_enabled": capability.apply_enabled,
                "mode": &capability.mode,
                "reason": &capability.reason,
                "required_gates": &capability.required_gates,
                "can_apply_now": capability.can_apply_now,
                "checked_at": checked_at,
                "check_count": capability.check_count,
                "failed_checks": &capability.failed_checks,
                "blocked_checks": &capability.blocked_checks,
            })),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    Ok((inspect_proposal(store, run_id, proposal_id)?, capability))
}

struct LatestReadinessEvidence {
    status: String,
    reason: Option<String>,
    fingerprint: Option<String>,
}

fn latest_readiness_evidence(
    events: &[LedgerEvent],
    proposal_id: &str,
) -> Option<LatestReadinessEvidence> {
    events.iter().rev().find_map(|event| {
        if event.kind != LedgerEventKind::WorkspacePatchReadinessReportCreated {
            return None;
        }
        let payload = sanitize_ledger_payload(event.payload.clone())?;
        if payload.get("proposal_id").and_then(Value::as_str) != Some(proposal_id) {
            return None;
        }
        Some(LatestReadinessEvidence {
            status: payload.get("readiness_status")?.as_str()?.to_string(),
            reason: payload
                .get("readiness_reason")
                .and_then(Value::as_str)
                .map(ToString::to_string),
            fingerprint: payload
                .get("readiness_fingerprint")
                .and_then(Value::as_str)
                .map(ToString::to_string),
        })
    })
}

fn inspect_apply_dry_run(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchApplyDryRunSummary,
    ),
    String,
> {
    let task = store
        .tasks()
        .get_task_by_run_id(run_id)
        .map_err(|e| format!("invalid params: {e}"))?
        .ok_or_else(|| "invalid params: run not found".to_string())?;
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    let events = read_existing_run_events(store, run_id)?;
    let latest_readiness = latest_readiness_evidence(&events, proposal_id);
    let current_readiness_checklist = build_readiness_checklist(&proposal);
    let (current_readiness_fingerprint, _) =
        readiness_fingerprint(&proposal, &current_readiness_checklist);
    let snapshot = proposal.latest_snapshot.as_ref();
    let mut checklist = vec![apply_dry_run_check("proposal_exists", "Pass", None)];

    if proposal.validation_status == "Blocked" {
        checklist.push(apply_dry_run_check(
            "proposal_is_valid",
            "Blocked",
            proposal.validation_reason.as_deref(),
        ));
    } else if proposal.validation_status == "Valid" {
        checklist.push(apply_dry_run_check("proposal_is_valid", "Pass", None));
    } else {
        checklist.push(apply_dry_run_check(
            "proposal_is_valid",
            "Fail",
            proposal
                .validation_reason
                .as_deref()
                .or(Some("Proposal validation status is not Valid.")),
        ));
    }

    checklist.push(if proposal.approval_status == "Approved" {
        apply_dry_run_check("proposal_is_approved", "Pass", None)
    } else {
        apply_dry_run_check(
            "proposal_is_approved",
            "Fail",
            Some("Proposal is not approved."),
        )
    });
    checklist.push(if snapshot.is_some() {
        apply_dry_run_check("proposal_has_preflight_snapshot", "Pass", None)
    } else {
        apply_dry_run_check(
            "proposal_has_preflight_snapshot",
            "Fail",
            Some("Run proposal.preflight before dry-run inspection."),
        )
    });
    checklist.push(match snapshot {
        Some(snapshot) if !snapshot.stale => {
            apply_dry_run_check("proposal_not_stale", "Pass", None)
        }
        Some(snapshot) => apply_dry_run_check(
            "proposal_not_stale",
            "Fail",
            snapshot
                .stale_reason
                .as_deref()
                .or(Some("Latest preflight snapshot is stale.")),
        ),
        None => apply_dry_run_check(
            "proposal_not_stale",
            "Skipped",
            Some("No preflight snapshot is available."),
        ),
    });
    checklist.push(if proposal.diff_preview.is_some() {
        apply_dry_run_check("sanitized_diff_preview_available", "Pass", None)
    } else {
        apply_dry_run_check(
            "sanitized_diff_preview_available",
            "Fail",
            Some("Sanitized diff preview is unavailable."),
        )
    });
    checklist.push(match latest_readiness.as_ref() {
        Some(evidence) if evidence.status == "Ready" => {
            apply_dry_run_check("readiness_ready", "Pass", None)
        }
        Some(evidence) if evidence.status == "Blocked" => apply_dry_run_check(
            "readiness_ready",
            "Blocked",
            evidence
                .reason
                .as_deref()
                .or(Some("Latest readiness report is blocked.")),
        ),
        Some(evidence) => apply_dry_run_check(
            "readiness_ready",
            "Fail",
            evidence
                .reason
                .as_deref()
                .or(Some("Latest readiness report is not ready.")),
        ),
        None => apply_dry_run_check(
            "readiness_ready",
            "Fail",
            Some("Run proposal.readiness before apply dry-run inspection."),
        ),
    });
    checklist.push(match latest_readiness.as_ref() {
        Some(evidence)
            if evidence.fingerprint.as_deref() == Some(current_readiness_fingerprint.as_str()) =>
        {
            apply_dry_run_check("readiness_fingerprint_current", "Pass", None)
        }
        Some(evidence) if evidence.fingerprint.is_some() => apply_dry_run_check(
            "readiness_fingerprint_current",
            "Fail",
            Some("Latest readiness report does not match current proposal evidence."),
        ),
        Some(_) => apply_dry_run_check(
            "readiness_fingerprint_current",
            "Fail",
            Some("Latest readiness report has no machine-checkable fingerprint."),
        ),
        None => apply_dry_run_check(
            "readiness_fingerprint_current",
            "Fail",
            Some("Run proposal.readiness before apply dry-run inspection."),
        ),
    });
    checklist.push(apply_dry_run_check("no_raw_content_exposed", "Pass", None));
    checklist.push(apply_dry_run_check(
        "apply_execution_supported",
        "Pass",
        Some("Patch apply execution is available through proposal.apply; dry-run does not invoke it."),
    ));
    checklist.push(apply_dry_run_check(
        "workspace_files_unchanged",
        "Pass",
        Some("Dry-run inspection does not write workspace files."),
    ));

    let blocked_checks: Vec<String> = checklist
        .iter()
        .filter(|c| c.status == "Blocked")
        .map(|c| c.name.clone())
        .collect();
    let failed_checks: Vec<String> = checklist
        .iter()
        .filter(|c| c.status == "Fail")
        .map(|c| c.name.clone())
        .collect();
    let checked_at = now_rfc3339();
    let dry_run_id = format!("apply_dry_run_{}", uuid::Uuid::new_v4().simple());
    let required_gates = vec![
        "proposal_valid".to_string(),
        "proposal_approved".to_string(),
        "preflight_snapshot_exists".to_string(),
        "proposal_not_stale".to_string(),
        "readiness_ready".to_string(),
        "readiness_fingerprint_current".to_string(),
        "operator_dry_run_requested".to_string(),
        "runtime_apply_supported".to_string(),
    ];
    let dry_run = WorkspacePatchApplyDryRunSummary {
        proposal_id: proposal_id.to_string(),
        dry_run_id: dry_run_id.clone(),
        dry_run_status: "Completed".to_string(),
        dry_run_reason: "Dry run completed without applying a patch or changing workspace files."
            .to_string(),
        checked_at: checked_at.clone(),
        required_gates,
        check_count: checklist.len(),
        failed_checks,
        blocked_checks,
        no_patch_applied: true,
        apply_executed: false,
        workspace_files_changed: false,
        checklist,
    };
    store
        .tasks()
        .append_task_event_with_payload(
            &task,
            LedgerEventKind::WorkspacePatchApplyDryRunChecked,
            Some(json!({
                "proposal_id": proposal_id,
                "dry_run_id": dry_run_id,
                "dry_run_status": &dry_run.dry_run_status,
                "dry_run_reason": &dry_run.dry_run_reason,
                "checked_at": checked_at,
                "required_gates": &dry_run.required_gates,
                "check_count": dry_run.check_count,
                "failed_checks": &dry_run.failed_checks,
                "blocked_checks": &dry_run.blocked_checks,
                "no_patch_applied": dry_run.no_patch_applied,
                "apply_executed": dry_run.apply_executed,
                "workspace_files_changed": dry_run.workspace_files_changed,
            })),
        )
        .map_err(|e| format!("invalid params: {e}"))?;
    Ok((inspect_proposal(store, run_id, proposal_id)?, dry_run))
}

fn inspect_apply_dry_run_history(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchApplyDryRunHistorySummary,
    ),
    String,
> {
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    let events = read_existing_run_events(store, run_id)?;
    let entries: Vec<WorkspacePatchApplyDryRunHistoryEntry> = events
        .iter()
        .filter(|event| event.kind == LedgerEventKind::WorkspacePatchApplyDryRunChecked)
        .filter_map(|event| sanitize_ledger_payload(event.payload.clone()))
        .filter_map(|payload| dry_run_history_entry_from_payload(&payload))
        .filter(|entry| entry.proposal_id == proposal_id)
        .collect();
    let dry_run_count = entries.len();
    let latest_dry_run = entries.last().cloned();
    let dry_runs = entries
        .iter()
        .rev()
        .take(MAX_DRY_RUN_HISTORY_ENTRIES)
        .cloned()
        .collect();
    let history = WorkspacePatchApplyDryRunHistorySummary {
        proposal_id: proposal_id.to_string(),
        dry_run_count,
        latest_dry_run,
        dry_runs,
        generated_at: now_rfc3339(),
    };
    Ok((proposal, history))
}

fn inspect_proposal_audit_trail(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchAuditTrailSummary,
    ),
    String,
> {
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    let events = read_existing_run_events(store, run_id)?;
    let entries: Vec<WorkspacePatchAuditTrailEntry> = events
        .iter()
        .filter_map(|event| proposal_audit_entry(event, proposal_id))
        .collect();
    let event_count = entries.len();
    let latest_event = entries.last().cloned();
    let mut bounded: Vec<_> = entries
        .iter()
        .rev()
        .take(MAX_PROPOSAL_AUDIT_TRAIL_ENTRIES)
        .cloned()
        .collect();
    bounded.reverse();
    let audit_trail = WorkspacePatchAuditTrailSummary {
        proposal_id: proposal_id.to_string(),
        event_count,
        latest_event,
        events: bounded,
        generated_at: now_rfc3339(),
    };
    Ok((proposal, audit_trail))
}

fn inspect_proposal_review_bundle(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchReviewBundleSummary,
    ),
    String,
> {
    let proposal = inspect_proposal(store, run_id, proposal_id)?;
    let events = read_existing_run_events(store, run_id)?;
    let audit_entries: Vec<WorkspacePatchAuditTrailEntry> = events
        .iter()
        .filter_map(|event| proposal_audit_entry(event, proposal_id))
        .collect();
    let latest_readiness = latest_review_signal(
        &events,
        proposal_id,
        LedgerEventKind::WorkspacePatchReadinessReportCreated,
        "readiness_status",
        "readiness_reason",
        "generated_at",
        "report_id",
    );
    let latest_apply_capability = latest_review_signal(
        &events,
        proposal_id,
        LedgerEventKind::WorkspacePatchApplyCapabilityChecked,
        "can_apply_now",
        "reason",
        "checked_at",
        "capability_id",
    );
    let latest_apply_dry_run = latest_review_signal(
        &events,
        proposal_id,
        LedgerEventKind::WorkspacePatchApplyDryRunChecked,
        "dry_run_status",
        "dry_run_reason",
        "checked_at",
        "dry_run_id",
    );
    let mut required_next_actions = Vec::new();
    if latest_readiness.is_none() {
        required_next_actions.push("proposal.readiness".to_string());
    }
    if latest_apply_capability.is_none() {
        required_next_actions.push("proposal.applyCapability".to_string());
    }
    if latest_apply_dry_run.is_none() {
        required_next_actions.push("proposal.applyDryRun".to_string());
    }

    let (review_status, review_reason) = if required_next_actions.is_empty() {
        (
            "Complete".to_string(),
            "All proposal review signals are available for final human review.".to_string(),
        )
    } else {
        (
            "NeedsAction".to_string(),
            format!(
                "Missing proposal review signals: {}.",
                required_next_actions.join(", ")
            ),
        )
    };

    let review_bundle = WorkspacePatchReviewBundleSummary {
        proposal_id: proposal_id.to_string(),
        review_status,
        review_reason,
        latest_readiness,
        latest_apply_capability,
        latest_apply_dry_run,
        audit_event_count: audit_entries.len(),
        latest_audit_event: audit_entries.last().cloned(),
        required_next_actions,
        generated_at: now_rfc3339(),
    };
    Ok((proposal, review_bundle))
}

fn inspect_proposal_review_verdict(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchReviewVerdictSummary,
    ),
    String,
> {
    let (proposal, review_bundle) = inspect_proposal_review_bundle(store, run_id, proposal_id)?;
    let events = read_existing_run_events(store, run_id)?;
    let missing_signals = review_bundle.required_next_actions.clone();
    let mut blocking_reasons = Vec::new();

    if proposal.validation_status == "Blocked" {
        blocking_reasons.push(
            proposal
                .validation_reason
                .clone()
                .unwrap_or_else(|| "Proposal validation is blocked.".to_string()),
        );
    }
    if proposal.diff_redacted || proposal.content_preview == "[redacted]" {
        blocking_reasons
            .push("Proposal review evidence is redacted or sensitive-like.".to_string());
    }

    if let Some(readiness) = &review_bundle.latest_readiness {
        if readiness.status != "Ready" {
            blocking_reasons.push(format!(
                "Latest readiness is {}{}",
                readiness.status,
                reason_suffix(readiness.reason.as_deref())
            ));
        }
    }

    if let Some(dry_run) = &review_bundle.latest_apply_dry_run {
        if dry_run.status != "Completed" {
            blocking_reasons.push(format!(
                "Latest apply dry-run is {}{}",
                dry_run.status,
                reason_suffix(dry_run.reason.as_deref())
            ));
        }
        match latest_apply_dry_run_safety(&events, proposal_id, dry_run.source_id.as_deref()) {
            Some(safety) => {
                if !safety.no_patch_applied {
                    blocking_reasons.push(
                        "Latest apply dry-run does not prove no patch was applied.".to_string(),
                    );
                }
                if safety.apply_executed {
                    blocking_reasons.push(
                        "Latest apply dry-run indicates apply execution occurred.".to_string(),
                    );
                }
                if safety.workspace_files_changed {
                    blocking_reasons.push(
                        "Latest apply dry-run indicates workspace files changed.".to_string(),
                    );
                }
            }
            None => blocking_reasons
                .push("Latest apply dry-run safety evidence is incomplete.".to_string()),
        }
    }

    let (verdict_status, evidence_status, verdict_reason) = if !blocking_reasons.is_empty() {
        (
            "BlockedForReview".to_string(),
            "Blocked".to_string(),
            "Recorded review evidence blocks final human review.".to_string(),
        )
    } else if !missing_signals.is_empty() {
        (
            "NeedsSignals".to_string(),
            "Incomplete".to_string(),
            format!(
                "Missing proposal review signals: {}.",
                missing_signals.join(", ")
            ),
        )
    } else {
        (
            "ReadyForHumanReview".to_string(),
            "Complete".to_string(),
            "Recorded review evidence supports final human review; patch apply still requires explicit proposal.apply authorization.".to_string(),
        )
    };

    let review_verdict = WorkspacePatchReviewVerdictSummary {
        proposal_id: proposal_id.to_string(),
        verdict_status,
        verdict_reason,
        evidence_status,
        blocking_reasons,
        missing_signals,
        latest_review_bundle_status: review_bundle.review_status,
        apply_authorized: false,
        generated_at: now_rfc3339(),
    };
    Ok((proposal, review_verdict))
}

fn inspect_proposal_review_report(
    store: &BrownieStore,
    run_id: &str,
    proposal_id: &str,
) -> Result<
    (
        WorkspacePatchProposalSummary,
        WorkspacePatchReviewReportSummary,
    ),
    String,
> {
    let (proposal, review_bundle) = inspect_proposal_review_bundle(store, run_id, proposal_id)?;
    let (_proposal, review_verdict) = inspect_proposal_review_verdict(store, run_id, proposal_id)?;
    let events = read_existing_run_events(store, run_id)?;
    let audit_entries: Vec<WorkspacePatchAuditTrailEntry> = events
        .iter()
        .filter_map(|event| proposal_audit_entry(event, proposal_id))
        .collect();
    let recent_audit_events = audit_entries
        .iter()
        .rev()
        .take(MAX_PROPOSAL_REVIEW_REPORT_AUDIT_EVENTS)
        .cloned()
        .collect();

    let (report_status, report_reason) = match review_verdict.verdict_status.as_str() {
        "BlockedForReview" => (
            "Blocked".to_string(),
            "Recorded review evidence blocks final human review.".to_string(),
        ),
        "ReadyForHumanReview" if review_bundle.review_status == "Complete" => (
            "Complete".to_string(),
            "Review bundle and verdict are complete for final human review; patch apply remains unauthorized.".to_string(),
        ),
        _ => (
            "NeedsAction".to_string(),
            "Additional proposal review signals are required before final human review.".to_string(),
        ),
    };

    let mut required_next_actions = review_bundle.required_next_actions.clone();
    for signal in &review_verdict.missing_signals {
        if !required_next_actions.contains(signal) {
            required_next_actions.push(signal.clone());
        }
    }

    let review_report = WorkspacePatchReviewReportSummary {
        proposal_id: proposal_id.to_string(),
        report_status,
        report_reason,
        review_bundle,
        review_verdict,
        audit_event_count: audit_entries.len(),
        recent_audit_events,
        required_next_actions,
        apply_authorized: false,
        generated_at: now_rfc3339(),
    };
    Ok((proposal, review_report))
}

fn inspect_proposal_review_queue(
    store: &BrownieStore,
    run_id: &str,
) -> Result<WorkspacePatchReviewQueueSummary, String> {
    let proposals = list_proposals(store, run_id)?;
    let mut items = Vec::with_capacity(proposals.len());
    let mut required_next_actions = Vec::new();
    let mut complete_count = 0;
    let mut needs_action_count = 0;
    let mut blocked_count = 0;

    for proposal in proposals {
        let (_proposal, review_report) =
            inspect_proposal_review_report(store, run_id, &proposal.proposal_id)?;
        match review_report.report_status.as_str() {
            "Complete" => complete_count += 1,
            "Blocked" => blocked_count += 1,
            _ => needs_action_count += 1,
        }
        for action in &review_report.required_next_actions {
            if !required_next_actions.contains(action) {
                required_next_actions.push(action.clone());
            }
        }
        items.push(WorkspacePatchReviewQueueItemSummary {
            proposal_id: proposal.proposal_id,
            path: proposal.path,
            validation_status: proposal.validation_status,
            approval_status: proposal.approval_status,
            report_status: review_report.report_status,
            report_reason: review_report.report_reason,
            verdict_status: review_report.review_verdict.verdict_status,
            review_status: review_report.review_bundle.review_status,
            audit_event_count: review_report.audit_event_count,
            latest_audit_event: review_report.review_bundle.latest_audit_event,
            required_next_actions: review_report.required_next_actions,
            apply_authorized: false,
            generated_at: review_report.generated_at,
        });
    }

    let (queue_status, queue_reason) = if blocked_count > 0 {
        (
            "Blocked".to_string(),
            format!("{blocked_count} proposal review item(s) are blocked."),
        )
    } else if needs_action_count > 0 {
        (
            "NeedsAction".to_string(),
            format!("{needs_action_count} proposal review item(s) need additional signals."),
        )
    } else {
        (
            "Complete".to_string(),
            "All proposal review queue items are complete for final human review; patch apply remains unauthorized.".to_string(),
        )
    };

    Ok(WorkspacePatchReviewQueueSummary {
        run_id: run_id.to_string(),
        queue_status,
        queue_reason,
        proposal_count: items.len(),
        complete_count,
        needs_action_count,
        blocked_count,
        items,
        required_next_actions,
        generated_at: now_rfc3339(),
    })
}

