fn resolve_task_start_policy(
    mode_id: Option<&str>,
    store: &BrownieStore,
) -> Result<CompiledModePolicy, String> {
    match mode_id {
        Some(mode_id) if !mode_id.trim().is_empty() => {
            resolve_workspace_mode_policy(store, mode_id)?
                .ok_or_else(|| "invalid params: unknown mode_id".to_string())
        }
        _ => Ok(BuiltinModeRegistry::default_policy()),
    }
}

enum HeadlessJourneyEntrypointResolution {
    BuiltinBootstrapFallback,
    ModePackDefault(String),
}

fn resolve_headless_journey_entrypoint_mode_id(
    store: &BrownieStore,
) -> Result<HeadlessJourneyEntrypointResolution, String> {
    if let Some(snapshot) = store
        .read_active_modepack_snapshot()
        .map_err(|error| format!("active modepack snapshot load failed: {error}"))?
    {
        let Some(mode_id) = snapshot
            .summary
            .default_entrypoint
            .map(|mode_id| mode_id.trim().to_string())
            .filter(|mode_id| !mode_id.is_empty())
        else {
            return Err(
                "invalid params: configured active modepack has no usable default entrypoint"
                    .to_string(),
            );
        };
        return Ok(HeadlessJourneyEntrypointResolution::ModePackDefault(
            mode_id,
        ));
    }
    if store.has_active_modepack_state() {
        return Err("invalid params: configured active modepack snapshot is missing".to_string());
    }

    let Some(snapshot) = load_workspace_modepack(store.workspace_root())
        .map_err(|error| format!("modepack load failed: {error}"))?
    else {
        return Ok(HeadlessJourneyEntrypointResolution::BuiltinBootstrapFallback);
    };
    let Some(mode_id) = snapshot
        .entrypoints
        .default
        .map(|mode_id| mode_id.trim().to_string())
        .filter(|mode_id| !mode_id.is_empty())
    else {
        return Err(
            "invalid params: configured workspace modepack has no usable default entrypoint"
                .to_string(),
        );
    };
    Ok(HeadlessJourneyEntrypointResolution::ModePackDefault(
        mode_id,
    ))
}

fn workspace_mode_policies(store: &BrownieStore) -> Result<Vec<CompiledModePolicy>, String> {
    let mut policies = BuiltinModeRegistry::list();
    if let Some(snapshot) = store
        .read_active_modepack_snapshot()
        .map_err(|error| format!("active modepack snapshot load failed: {error}"))?
    {
        for policy in snapshot.policies {
            let compiled = compiled_mode_policy_from_active_snapshot(&policy)?;
            policies.retain(|existing| existing.mode_id != compiled.mode_id);
            policies.push(compiled);
        }
        return Ok(policies);
    }

    let Some(snapshot) = load_workspace_modepack(store.workspace_root())
        .map_err(|error| format!("modepack load failed: {error}"))?
    else {
        return Ok(policies);
    };
    for policy in snapshot.modes {
        policies.retain(|existing| existing.mode_id != policy.mode_id);
        policies.push(policy);
    }
    Ok(policies)
}

fn compiled_mode_policy_from_active_snapshot(
    policy: &ActiveModePackPolicySnapshot,
) -> Result<CompiledModePolicy, String> {
    compiled_mode_policy_from_payload(&json!({
        "mode_id": policy.mode_id,
        "display_name": policy.display_name,
        "role_definition": policy.role_definition,
        "when_to_use": policy.when_to_use,
        "description": policy.description,
        "prompt_sections": policy.prompt_sections,
        "verification_responsibility": policy.verification_responsibility,
        "instruction_fingerprint": policy.instruction_fingerprint,
        "permissions": policy.permissions,
        "workspace_write_scopes": policy.workspace_write_scopes,
        "allowed_handoff_targets": policy.allowed_handoff_targets,
        "mcp_access": policy.mcp_access,
        "completion_rules": policy.completion_rules,
    }))
    .ok_or_else(|| {
        format!(
            "active modepack policy snapshot is invalid: {}",
            policy.mode_id
        )
    })
}

fn resolve_workspace_mode_policy(
    store: &BrownieStore,
    mode_id: &str,
) -> Result<Option<CompiledModePolicy>, String> {
    Ok(workspace_mode_policies(store)?
        .into_iter()
        .find(|policy| policy.mode_id == mode_id))
}

fn agent_loop_state_name(state: AgentLoopState) -> &'static str {
    match state {
        AgentLoopState::Created => "Created",
        AgentLoopState::LoadingMode => "LoadingMode",
        AgentLoopState::BuildingContext => "BuildingContext",
        AgentLoopState::CallingLlm => "CallingLlm",
        AgentLoopState::ParsingResponse => "ParsingResponse",
        AgentLoopState::ExecutingTool => "ExecutingTool",
        AgentLoopState::ApplyingPatch => "ApplyingPatch",
        AgentLoopState::SpawningSubtask => "SpawningSubtask",
        AgentLoopState::Waiting => "Waiting",
        AgentLoopState::Verifying => "Verifying",
        AgentLoopState::Completed => "Completed",
        AgentLoopState::Failed => "Failed",
        AgentLoopState::Cancelled => "Cancelled",
    }
}

fn mode_summary(policy: CompiledModePolicy) -> ModeSummary {
    ModeSummary {
        mode_id: policy.mode_id,
        display_name: policy.display_name,
        role_definition: policy.role_definition,
        permissions: ModePermissionsSummary {
            read_only: policy.permissions.read_only,
            workspace_write: policy.permissions.workspace_write,
            process_exec: policy.permissions.process_exec,
            network_access: policy.permissions.network_access,
            service_control: policy.permissions.service_control,
            destructive: policy.permissions.destructive,
            can_spawn_subtasks: policy.permissions.can_spawn_subtasks,
            codebase_index: policy.permissions.codebase_index,
            mcp_tool_access: policy.permissions.mcp_tool_access,
        },
    }
}

fn mode_resolved_payload(policy: &CompiledModePolicy) -> Value {
    json!({
        "mode_id": policy.mode_id,
        "display_name": policy.display_name,
        "role_definition": policy.role_definition,
        "when_to_use": policy.when_to_use,
        "description": policy.description,
        "prompt_sections": policy.prompt_sections,
        "verification_responsibility": policy.verification_responsibility,
        "instruction_fingerprint": policy.instruction_fingerprint,
        "workspace_write_scopes": policy.workspace_write_scopes,
        "allowed_handoff_targets": policy.allowed_handoff_targets,
        "mcp_access": policy.mcp_access,
        "completion_rules": policy.completion_rules,
        "permissions": {
            "read_only": policy.permissions.read_only,
            "workspace_write": policy.permissions.workspace_write,
            "process_exec": policy.permissions.process_exec,
            "network_access": policy.permissions.network_access,
            "service_control": policy.permissions.service_control,
            "destructive": policy.permissions.destructive,
            "can_spawn_subtasks": policy.permissions.can_spawn_subtasks,
            "codebase_index": policy.permissions.codebase_index,
            "mcp_tool_access": policy.permissions.mcp_tool_access,
        }
    })
}

fn append_mode_resolved_event(
    store: &BrownieStore,
    record: &TaskRecord,
    policy: &CompiledModePolicy,
) -> anyhow::Result<()> {
    let mut payload = mode_resolved_payload(policy);
    if policy.permissions.mcp_tool_access {
        payload["mcp_tool_catalogs"] = mcp_tool_catalogs_payload(store, policy)?;
    }
    if let Some(provenance) = external_modepack_task_provenance_payload(store, &policy.mode_id)
        .map_err(anyhow::Error::msg)?
    {
        payload["external_modepack_task_provenance"] = provenance;
    }
    store.tasks().append_task_event_with_payload(
        record,
        LedgerEventKind::ModeResolved,
        Some(payload),
    )
}

fn mcp_tool_catalogs_payload(
    store: &BrownieStore,
    policy: &CompiledModePolicy,
) -> anyhow::Result<Value> {
    let configs = active_modepack_mcp_server_configs(store)?;
    let mut catalogs = Vec::new();
    for access in &policy.mcp_access {
        let Some(config) = configs
            .iter()
            .find(|server| server.server_id == access.server_id)
        else {
            anyhow::bail!("MCP policy references missing server configuration");
        };
        let catalog = mcp_client::list_tools(config)?;
        let tools = catalog
            .tools
            .into_iter()
            .filter(|tool| {
                access
                    .tools
                    .iter()
                    .any(|allowed| allowed == &tool.tool_name)
            })
            .collect::<Vec<_>>();
        if tools.len() != access.tools.len() {
            anyhow::bail!("MCP allow-list references a tool missing from server catalog");
        }
        catalogs.push(json!({
            "server_id": catalog.server_id,
            "server_config_identity_fingerprint": catalog.server_config_identity_fingerprint,
            "protocol_version": catalog.protocol_version,
            "catalog_fingerprint": catalog.catalog_fingerprint,
            "tools": tools,
        }));
    }
    Ok(Value::Array(catalogs))
}

fn active_modepack_mcp_server_configs(
    store: &BrownieStore,
) -> anyhow::Result<Vec<brownie_modepack::ModePackMcpServerConfig>> {
    let Some(snapshot) = store.read_active_modepack_snapshot()? else {
        anyhow::bail!("MCP policy requires active structured Mode Pack server configuration");
    };
    snapshot
        .mcp_servers
        .into_iter()
        .map(|server| {
            serde_json::from_value(server).map_err(|error| {
                anyhow::anyhow!("active Mode Pack MCP server configuration is invalid: {error}")
            })
        })
        .collect()
}

fn modepack_mcp_servers_payload(snapshot: &brownie_modepack::ModePackSnapshot) -> Vec<Value> {
    snapshot
        .mcp_servers
        .iter()
        .filter_map(|server| serde_json::to_value(server).ok())
        .collect()
}

fn resolve_policy_for_task_run(
    record: &brownie_protocol::TaskRecord,
    store: &BrownieStore,
) -> Result<CompiledModePolicy, String> {
    let events = store
        .tasks()
        .read_ledger_events(&record.run_id)
        .map_err(|error| error.to_string())?;
    if let Some(policy) = events
        .iter()
        .rev()
        .find(|event| event.kind == LedgerEventKind::ModeResolved)
        .and_then(|event| event.payload.as_ref())
        .and_then(compiled_mode_policy_from_payload)
    {
        return Ok(policy);
    }

    if let Some(mode_id) = record.mode_id.as_deref() {
        return resolve_workspace_mode_policy(store, mode_id)?
            .ok_or_else(|| format!("stored task has unknown mode_id: {mode_id}"));
    }

    let mode_id = events
        .iter()
        .rev()
        .find(|event| event.kind == LedgerEventKind::ModeResolved)
        .and_then(|event| event.payload.as_ref())
        .and_then(|payload| payload.get("mode_id"))
        .and_then(|value| value.as_str())
        .unwrap_or(DEFAULT_MODE_ID_FOR_RUN);
    resolve_workspace_mode_policy(store, mode_id)?
        .ok_or_else(|| format!("ledger has unknown mode_id: {mode_id}"))
}

fn compiled_mode_policy_from_payload(payload: &Value) -> Option<CompiledModePolicy> {
    let permissions = payload.get("permissions")?;
    let completion_rules = payload
        .get("completion_rules")
        .and_then(Value::as_array)
        .map(|rules| {
            rules
                .iter()
                .filter_map(|rule| rule.as_str().map(ToString::to_string))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    Some(CompiledModePolicy {
        mode_id: payload.get("mode_id")?.as_str()?.to_string(),
        display_name: payload.get("display_name")?.as_str()?.to_string(),
        role_definition: payload.get("role_definition")?.as_str()?.to_string(),
        when_to_use: payload
            .get("when_to_use")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        description: payload
            .get("description")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        prompt_sections: serde_json::from_value(
            payload
                .get("prompt_sections")
                .cloned()
                .unwrap_or_else(|| json!([])),
        )
        .ok()?,
        verification_responsibility: payload
            .get("verification_responsibility")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        instruction_fingerprint: payload
            .get("instruction_fingerprint")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        permissions: brownie_agentmodes::ModePermissions {
            read_only: permissions.get("read_only")?.as_bool()?,
            workspace_write: permissions.get("workspace_write")?.as_bool()?,
            process_exec: permissions.get("process_exec")?.as_bool()?,
            network_access: permissions.get("network_access")?.as_bool()?,
            service_control: permissions.get("service_control")?.as_bool()?,
            destructive: permissions.get("destructive")?.as_bool()?,
            can_spawn_subtasks: permissions.get("can_spawn_subtasks")?.as_bool()?,
            codebase_index: permissions
                .get("codebase_index")
                .and_then(Value::as_bool)
                .unwrap_or(false),
            mcp_tool_access: permissions
                .get("mcp_tool_access")
                .and_then(Value::as_bool)
                .unwrap_or(false),
        },
        workspace_write_scopes: serde_json::from_value(
            payload
                .get("workspace_write_scopes")
                .cloned()
                .unwrap_or_else(|| json!([])),
        )
        .ok()?,
        allowed_handoff_targets: payload
            .get("allowed_handoff_targets")
            .and_then(Value::as_array)
            .map(|targets| {
                targets
                    .iter()
                    .filter_map(|target| target.as_str().map(ToString::to_string))
                    .collect::<Vec<_>>()
            })
            .filter(|targets| !targets.is_empty()),
        mcp_access: serde_json::from_value(
            payload
                .get("mcp_access")
                .cloned()
                .unwrap_or_else(|| json!([])),
        )
        .ok()?,
        completion_rules,
    })
}

fn external_modepack_policy_fingerprint(
    modepack_name: &str,
    schema_version: u64,
    policy: &CompiledModePolicy,
) -> String {
    let canonical = json!({
        "version": EXTERNAL_MODEPACK_POLICY_FINGERPRINT_VERSION,
        "modepack_name": modepack_name,
        "schema_version": schema_version,
        "source_path": WORKSPACE_MODEPACK_PATH,
        "mode_id": policy.mode_id,
        "display_name": policy.display_name,
        "role_definition": policy.role_definition,
        "when_to_use": policy.when_to_use,
        "description": policy.description,
        "prompt_sections": policy.prompt_sections,
        "verification_responsibility": policy.verification_responsibility,
        "instruction_fingerprint": policy.instruction_fingerprint,
        "workspace_write_scopes": policy.workspace_write_scopes,
        "allowed_handoff_targets": policy.allowed_handoff_targets,
        "mcp_access": policy.mcp_access,
        "completion_rules": policy.completion_rules,
        "permissions": {
            "read_only": policy.permissions.read_only,
            "workspace_write": policy.permissions.workspace_write,
            "process_exec": policy.permissions.process_exec,
            "network_access": policy.permissions.network_access,
            "service_control": policy.permissions.service_control,
            "destructive": policy.permissions.destructive,
            "can_spawn_subtasks": policy.permissions.can_spawn_subtasks,
            "codebase_index": policy.permissions.codebase_index,
            "mcp_tool_access": policy.permissions.mcp_tool_access,
        }
    });
    format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()))
}

fn external_modepack_task_provenance_payload(
    store: &BrownieStore,
    mode_id: &str,
) -> Result<Option<Value>, String> {
    if let Some(snapshot) = store
        .read_active_modepack_snapshot()
        .map_err(|error| format!("active modepack snapshot load failed: {error}"))?
    {
        let Some(policy) = snapshot
            .policies
            .iter()
            .find(|policy| policy.mode_id == mode_id)
        else {
            return Ok(None);
        };
        return Ok(Some(json!({
            "version": EXTERNAL_MODEPACK_TASK_PROVENANCE_VERSION,
            "source_kind": snapshot.summary.source_kind,
            "modepack_name": snapshot.summary.modepack_name,
            "schema_version": snapshot.summary.schema_version,
            "source_path": snapshot.summary.source_path,
            "global_policy_artifacts": snapshot.global_policy_artifacts,
            "mode_id": policy.mode_id,
            "policy_fingerprint": policy.policy_fingerprint,
            "activation_fingerprint": snapshot.summary.activation_fingerprint,
        })));
    }

    let Some(snapshot) = load_workspace_modepack(store.workspace_root())
        .map_err(|error| format!("modepack load failed: {error}"))?
    else {
        return Ok(None);
    };
    let Some(policy) = snapshot
        .modes
        .iter()
        .find(|policy| policy.mode_id == mode_id)
    else {
        return Ok(None);
    };
    let policy_fingerprint =
        external_modepack_policy_fingerprint(&snapshot.name, snapshot.schema_version, policy);
    Ok(Some(json!({
        "version": EXTERNAL_MODEPACK_TASK_PROVENANCE_VERSION,
        "source_kind": "workspace_modepack",
        "modepack_name": snapshot.name,
        "schema_version": snapshot.schema_version,
        "source_path": WORKSPACE_MODEPACK_PATH,
        "global_policy_artifacts": modepack_global_policy_artifacts_payload(&snapshot),
        "mode_id": policy.mode_id,
        "policy_fingerprint": policy_fingerprint,
    })))
}

