fn append_workspace_patch_proposal(
    store: &BrownieStore,
    record: &brownie_protocol::TaskRecord,
    policy: &CompiledModePolicy,
    decision: &ToolIntentDecision,
) -> anyhow::Result<()> {
    let path = decision
        .input
        .get("path")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let content = decision
        .input
        .get("content")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let operation = decision
        .input
        .get("operation")
        .and_then(Value::as_str)
        .unwrap_or(WorkspacePatchOperation::ReplaceFile.as_str());
    let scope_decision = RuntimePermissionGate::check_workspace_write_path(policy, path);
    let permission_payload = json!({
        "scope": "workspace.write",
        "tool_id": WORKSPACE_WRITE_TOOL_ID,
        "path": path,
        "operation": operation,
        "mode_id": policy.mode_id,
        "required_action": "WriteWorkspace",
        "workspace_write_scope_count": policy.workspace_write_scopes.len(),
        "allowed": scope_decision.allowed,
        "reason": scope_decision.reason,
    });
    store.tasks().append_task_event_with_payload(
        record,
        LedgerEventKind::PermissionChecked,
        Some(permission_payload.clone()),
    )?;
    if !scope_decision.allowed {
        store.tasks().append_task_event_with_payload(
            record,
            LedgerEventKind::PermissionDenied,
            Some(permission_payload),
        )?;
        return Ok(());
    }
    let proposal =
        build_workspace_patch_proposal_from_input(store, path, operation, content, &decision.input);
    let proposal_id = format!("proposal_{}", uuid::Uuid::new_v4().simple());
    let mut payload = json!({
        "proposal_id": proposal_id,
        "tool_id": WORKSPACE_WRITE_TOOL_ID,
        "path": path,
        "operation": operation,
        "content_preview": proposal.content_preview,
        "content_chars": proposal.content_chars,
        "truncated": proposal.truncated,
        "validation_status": proposal.validation_status,
        "validation_reason": proposal.validation_reason,
        "diff_preview": proposal.diff_preview,
        "diff_truncated": proposal.diff_truncated,
        "diff_redacted": proposal.diff_redacted,
    });
    if let Some(hunk_count) = proposal.hunk_count {
        payload["hunk_count"] = json!(hunk_count);
    }
    if let Some(hunk_fingerprint) = proposal.hunk_fingerprint.as_ref() {
        payload["hunk_fingerprint"] = json!(hunk_fingerprint);
    }
    if let Some(provenance) = record.verification_recovery_provenance.as_ref() {
        payload["verification_recovery_repair"] = json!(true);
        payload["source_task_id"] = json!(provenance.source_task_id.clone());
        payload["source_run_id"] = json!(provenance.source_run_id.clone());
        payload["recovery_task_id"] = json!(record.task_id.clone());
        payload["recovery_run_id"] = json!(record.run_id.clone());
        payload["failure_fingerprint"] = json!(provenance.failure_fingerprint.clone());
        payload["failed_verifier_tool_ids"] = json!(provenance.failed_verifier_tool_ids.clone());
    }
    if operation == WorkspacePatchOperation::PatchFile.as_str() {
        if let Some(provenance) = record.patch_apply_recovery_provenance.as_ref() {
            if patch_apply_recovery_normalized_path(path).as_deref()
                == Some(provenance.path.as_str())
            {
                payload["patch_apply_recovery_repair"] = json!(true);
                payload["source_run_id"] = json!(provenance.source_run_id.clone());
                payload["source_proposal_id"] = json!(provenance.source_proposal_id.clone());
                payload["source_apply_id"] = json!(provenance.source_apply_id.clone());
                payload["recovery_task_id"] = json!(record.task_id.clone());
                payload["recovery_run_id"] = json!(record.run_id.clone());
                payload["source_apply_fingerprint"] =
                    json!(provenance.source_apply_fingerprint.clone());
                payload["failure_fingerprint"] = json!(provenance.failure_fingerprint.clone());
                payload["failure_class"] = json!(provenance.failure_class.clone());
                payload["source_operation"] = json!(provenance.operation.clone());
                payload["source_path"] = json!(provenance.path.clone());
                payload["source_hunk_count"] = json!(provenance.hunk_count);
                payload["source_hunk_fingerprint"] = json!(provenance.hunk_fingerprint.clone());
            }
        }
    }
    store.tasks().append_task_event_with_payload(
        record,
        LedgerEventKind::WorkspacePatchProposed,
        Some(payload),
    )?;
    Ok(())
}

