fn patch_hunk_fingerprint(old_text: &str, new_text: &str) -> String {
    let canonical = json!({
        "version": "patch_file_single_hunk_v1",
        "old_text_chars": old_text.chars().count(),
        "old_text_sha256": format!("sha256:{}", hex_sha256(old_text.as_bytes())),
        "new_text_chars": new_text.chars().count(),
        "new_text_sha256": format!("sha256:{}", hex_sha256(new_text.as_bytes())),
    });
    format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()))
}

#[derive(Debug, Clone)]
struct PatchTextHunk {
    old_text: String,
    new_text: String,
}

fn patch_hunks_fingerprint(hunks: &[PatchTextHunk]) -> String {
    if hunks.len() == 1 {
        return patch_hunk_fingerprint(&hunks[0].old_text, &hunks[0].new_text);
    }
    let canonical_hunks = hunks
        .iter()
        .map(|hunk| {
            json!({
                "old_text_chars": hunk.old_text.chars().count(),
                "old_text_sha256": format!("sha256:{}", hex_sha256(hunk.old_text.as_bytes())),
                "new_text_chars": hunk.new_text.chars().count(),
                "new_text_sha256": format!("sha256:{}", hex_sha256(hunk.new_text.as_bytes())),
            })
        })
        .collect::<Vec<_>>();
    let canonical = json!({
        "version": "patch_file_multi_hunk_v1",
        "hunks": canonical_hunks,
    });
    format!("sha256:{}", hex_sha256(canonical.to_string().as_bytes()))
}

fn patch_hunks_from_input(input: &Value) -> Result<Vec<PatchTextHunk>, &'static str> {
    if let Some(hunks_value) = input.get("hunks") {
        if input.get("old_text").is_some() || input.get("new_text").is_some() {
            return Err("patch_file hunks cannot be combined with old_text or new_text");
        }
        let Some(hunks) = hunks_value.as_array() else {
            return Err("patch_file hunks must be an array");
        };
        if !(2..=5).contains(&hunks.len()) {
            return Err("patch_file hunks must contain 2 to 5 entries");
        }
        return hunks
            .iter()
            .map(|hunk| {
                let Some(hunk) = hunk.as_object() else {
                    return Err("patch_file hunk must be an object");
                };
                let Some(old_text) = hunk.get("old_text").and_then(Value::as_str) else {
                    return Err("patch_file hunk old_text is required");
                };
                let Some(new_text) = hunk.get("new_text").and_then(Value::as_str) else {
                    return Err("patch_file hunk new_text is required");
                };
                if old_text.is_empty() {
                    return Err("patch_file hunk old_text must not be empty");
                }
                Ok(PatchTextHunk {
                    old_text: old_text.to_string(),
                    new_text: new_text.to_string(),
                })
            })
            .collect();
    }
    let Some(old_text) = input.get("old_text").and_then(Value::as_str) else {
        return Err("patch_file old_text is required");
    };
    let Some(new_text) = input.get("new_text").and_then(Value::as_str) else {
        return Err("patch_file new_text is required");
    };
    if old_text.is_empty() {
        return Err("patch_file old_text must not be empty");
    }
    Ok(vec![PatchTextHunk {
        old_text: old_text.to_string(),
        new_text: new_text.to_string(),
    }])
}

fn patch_hunks_from_apply_params(
    params: &ProposalApplyParams,
) -> Result<Vec<PatchTextHunk>, &'static str> {
    if let Some(hunks) = params.patch_hunks.as_ref() {
        if params.patch_old_text.is_some() || params.patch_new_text.is_some() {
            return Err("Patch-file apply patch_hunks cannot be combined with patch_old_text or patch_new_text.");
        }
        if !(2..=5).contains(&hunks.len()) {
            return Err("Patch-file apply patch_hunks must contain 2 to 5 hunks.");
        }
        return hunks
            .iter()
            .map(|hunk: &ProposalPatchHunk| {
                if hunk.old_text.is_empty() {
                    return Err("Patch-file apply hunk old text must not be empty.");
                }
                Ok(PatchTextHunk {
                    old_text: hunk.old_text.clone(),
                    new_text: hunk.new_text.clone(),
                })
            })
            .collect();
    }
    let Some(patch_old_text) = params.patch_old_text.as_deref() else {
        return Err("Patch-file apply requires patch_old_text or patch_hunks.");
    };
    let Some(patch_new_text) = params.patch_new_text.as_deref() else {
        return Err("Patch-file apply requires patch_new_text when patch_old_text is used.");
    };
    if patch_old_text.is_empty() {
        return Err("Patch-file old text must not be empty.");
    }
    Ok(vec![PatchTextHunk {
        old_text: patch_old_text.to_string(),
        new_text: patch_new_text.to_string(),
    }])
}

fn apply_text_hunks(
    current_content: &str,
    hunks: &[PatchTextHunk],
) -> Result<String, &'static str> {
    if hunks.is_empty() {
        return Err("Patch hunks must not be empty.");
    }
    let mut ranges = Vec::with_capacity(hunks.len());
    for (index, hunk) in hunks.iter().enumerate() {
        if hunk.old_text.is_empty() {
            return Err("Patch old_text must not be empty.");
        }
        let mut matches = current_content.match_indices(&hunk.old_text);
        let Some((start, _)) = matches.next() else {
            return Err("Patch old_text was not found in the current target.");
        };
        if matches.next().is_some() {
            return Err("Patch old_text appears more than once in the current target.");
        }
        ranges.push((start, start + hunk.old_text.len(), index));
    }
    ranges.sort_by_key(|(start, _, _)| *start);
    let mut cursor = 0usize;
    let mut replacement = String::with_capacity(
        current_content.len()
            + hunks
                .iter()
                .map(|hunk| hunk.new_text.len().saturating_sub(hunk.old_text.len()))
                .sum::<usize>(),
    );
    for (start, end, index) in ranges {
        if start < cursor {
            return Err("Patch hunks overlap in the current target.");
        }
        replacement.push_str(&current_content[cursor..start]);
        replacement.push_str(&hunks[index].new_text);
        cursor = end;
    }
    replacement.push_str(&current_content[cursor..]);
    Ok(replacement)
}

fn build_workspace_patch_proposal_from_input(
    store: &BrownieStore,
    path: &str,
    operation: &str,
    content: &str,
    input: &Value,
) -> ProposalBuildResult {
    let content_chars = content.chars().count();
    let mut result = ProposalBuildResult {
        content_preview: preview_with_limit(content, DEFAULT_PROPOSAL_PREVIEW_CHARS),
        content_chars,
        truncated: content_chars
            > preview_with_limit(content, DEFAULT_PROPOSAL_PREVIEW_CHARS)
                .chars()
                .count(),
        validation_status: "Valid",
        validation_reason: None,
        diff_preview: None,
        diff_truncated: false,
        diff_redacted: false,
        hunk_count: None,
        hunk_fingerprint: None,
    };
    if scan_text_for_sensitive_content(content) {
        result.content_preview = "[redacted]".to_string();
        result.validation_status = "Blocked";
        result.validation_reason = Some("proposal content contains sensitive-like data");
        result.diff_preview = None;
        result.diff_redacted = true;
        return result;
    }
    if brownie_tools::preflight_workspace_write_path(path).is_err() {
        result.validation_status = "Invalid";
        result.validation_reason = Some("path is not a safe workspace-relative path");
        return result;
    }
    if operation != WorkspacePatchOperation::ReplaceFile.as_str()
        && operation != WorkspacePatchOperation::CreateFile.as_str()
        && operation != WorkspacePatchOperation::DeleteFile.as_str()
        && operation != WorkspacePatchOperation::PatchFile.as_str()
    {
        result.validation_status = "Invalid";
        result.validation_reason = Some("workspace write operation is unsupported");
        return result;
    }
    let Ok(root) = store.workspace_root().canonicalize() else {
        result.validation_status = "Invalid";
        result.validation_reason = Some("workspace root is not accessible");
        return result;
    };
    if operation == WorkspacePatchOperation::PatchFile.as_str() {
        if !content.is_empty() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("patch_file operation must not include content");
            return result;
        }
        let hunks = match patch_hunks_from_input(input) {
            Ok(hunks) => hunks,
            Err(reason) => {
                result.validation_status = "Invalid";
                result.validation_reason = Some(reason);
                return result;
            }
        };
        result.content_chars = hunks
            .iter()
            .map(|hunk| hunk.old_text.chars().count() + hunk.new_text.chars().count())
            .sum();
        result.truncated = false;
        if hunks.len() == 1 {
            result.content_preview = format!(
                "[patch_file single_hunk old_chars={} new_chars={}]",
                hunks[0].old_text.chars().count(),
                hunks[0].new_text.chars().count()
            );
        } else {
            result.content_preview = format!(
                "[patch_file multi_hunk count={} total_chars={}]",
                hunks.len(),
                result.content_chars
            );
        }
        result.hunk_count = Some(hunks.len());
        result.hunk_fingerprint = Some(patch_hunks_fingerprint(&hunks));
        if result.content_chars > DEFAULT_MAX_WORKSPACE_WRITE_CONTENT_CHARS {
            result.validation_status = "Invalid";
            result.validation_reason = Some("patch_file hunks exceed runtime write limit");
            return result;
        }
        if hunks.iter().any(|hunk| {
            scan_text_for_sensitive_content(&hunk.old_text)
                || scan_text_for_sensitive_content(&hunk.new_text)
        }) {
            result.content_preview = "[redacted]".to_string();
            result.validation_status = "Blocked";
            result.validation_reason = Some("patch_file hunks contain sensitive-like data");
            result.diff_redacted = true;
            return result;
        }
        let target = root.join(path);
        let Ok(symlink_metadata) = std::fs::symlink_metadata(&target) else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target file does not exist");
            return result;
        };
        if symlink_metadata.file_type().is_symlink() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target path is a symlink");
            return result;
        }
        if !symlink_metadata.is_file() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target path is not a file");
            return result;
        }
        let Ok(canonical_target) = target.canonicalize() else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target file does not exist");
            return result;
        };
        if !canonical_target.starts_with(&root) {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target path escapes workspace root");
            return result;
        }
        let Ok(existing) = std::fs::read_to_string(&canonical_target) else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target file is not UTF-8");
            return result;
        };
        if scan_text_for_sensitive_content(&existing) {
            result.validation_status = "Blocked";
            result.validation_reason = Some("target file contains sensitive-like data");
            result.diff_redacted = true;
            return result;
        }
        if let Err(reason) = apply_text_hunks(&existing, &hunks) {
            result.validation_status = "Invalid";
            result.validation_reason = Some(reason);
            return result;
        }
        let diff = if hunks.len() == 1 {
            format!(
                "--- a/{path}\n+++ b/{path}\n@@ patch_file single_hunk old_chars={} new_chars={} @@\n[patch hunk elided]\n",
                hunks[0].old_text.chars().count(),
                hunks[0].new_text.chars().count()
            )
        } else {
            format!(
                "--- a/{path}\n+++ b/{path}\n@@ patch_file multi_hunk count={} total_chars={} @@\n[patch hunks elided]\n",
                hunks.len(),
                result.content_chars
            )
        };
        result.diff_truncated =
            diff.chars().count() > DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS);
        result.diff_preview = Some(preview_with_limit(
            &diff,
            DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS),
        ));
        return result;
    }
    if operation == WorkspacePatchOperation::CreateFile.as_str() {
        let relative_path = Path::new(path);
        let Some(file_name) = relative_path.file_name() else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target file name is missing");
            return result;
        };
        let parent_relative = relative_path.parent().unwrap_or_else(|| Path::new(""));
        let parent = root.join(parent_relative);
        let Ok(parent_metadata) = std::fs::symlink_metadata(&parent) else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target parent directory does not exist");
            return result;
        };
        if parent_metadata.file_type().is_symlink() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target parent directory is a symlink");
            return result;
        }
        if !parent_metadata.is_dir() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target parent path is not a directory");
            return result;
        }
        let Ok(canonical_parent) = parent.canonicalize() else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target parent directory is not accessible");
            return result;
        };
        if !canonical_parent.starts_with(&root) {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target parent escapes workspace root");
            return result;
        }
        let target = canonical_parent.join(file_name);
        match std::fs::symlink_metadata(&target) {
            Ok(_) => {
                result.validation_status = "Invalid";
                result.validation_reason = Some("target path already exists");
                return result;
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(_) => {
                result.validation_status = "Invalid";
                result.validation_reason = Some("target path is not accessible");
                return result;
            }
        }
        let diff = synthetic_unified_diff(path, "", content);
        result.diff_truncated =
            diff.chars().count() > DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS);
        result.diff_preview = Some(preview_with_limit(
            &diff,
            DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS),
        ));
        return result;
    }
    if operation == WorkspacePatchOperation::DeleteFile.as_str() {
        if !content.is_empty() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("delete_file operation must not include content");
            return result;
        }
        let target = root.join(path);
        let Ok(symlink_metadata) = std::fs::symlink_metadata(&target) else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target file does not exist");
            return result;
        };
        if symlink_metadata.file_type().is_symlink() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target path is a symlink");
            return result;
        }
        if !symlink_metadata.is_file() {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target path is not a file");
            return result;
        }
        let Ok(canonical_target) = target.canonicalize() else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target file does not exist");
            return result;
        };
        if !canonical_target.starts_with(&root) {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target path escapes workspace root");
            return result;
        }
        let Ok(existing) = std::fs::read_to_string(&canonical_target) else {
            result.validation_status = "Invalid";
            result.validation_reason = Some("target file is not UTF-8");
            return result;
        };
        if scan_text_for_sensitive_content(&existing) {
            result.validation_status = "Blocked";
            result.validation_reason = Some("target file contains sensitive-like data");
            result.diff_redacted = true;
            return result;
        }
        let diff = synthetic_unified_diff(path, &existing, "");
        result.diff_truncated =
            diff.chars().count() > DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS);
        result.diff_preview = Some(preview_with_limit(
            &diff,
            DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS),
        ));
        return result;
    }
    let target = root.join(path);
    let Ok(canonical_target) = target.canonicalize() else {
        result.validation_status = "Invalid";
        result.validation_reason = Some("target file does not exist");
        return result;
    };
    if !canonical_target.starts_with(&root) {
        result.validation_status = "Invalid";
        result.validation_reason = Some("target path escapes workspace root");
        return result;
    }
    let Ok(metadata) = std::fs::metadata(&canonical_target) else {
        result.validation_status = "Invalid";
        result.validation_reason = Some("target file does not exist");
        return result;
    };
    if !metadata.is_file() {
        result.validation_status = "Invalid";
        result.validation_reason = Some("target path is not a file");
        return result;
    }
    let Ok(existing) = std::fs::read_to_string(&canonical_target) else {
        result.validation_status = "Invalid";
        result.validation_reason = Some("target file is not UTF-8");
        return result;
    };
    if scan_text_for_sensitive_content(&existing) {
        result.validation_status = "Blocked";
        result.validation_reason = Some("target file contains sensitive-like data");
        result.diff_redacted = true;
        return result;
    }
    let diff = synthetic_unified_diff(path, &existing, content);
    result.diff_truncated =
        diff.chars().count() > DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS);
    result.diff_preview = Some(preview_with_limit(
        &diff,
        DEFAULT_DIFF_PREVIEW_CHARS.min(MAX_DIFF_PREVIEW_CHARS),
    ));
    result
}

fn scan_text_for_sensitive_content(content: &str) -> bool {
    !scan_prompt_for_sensitive_content(&[LlmMessage {
        role: "user".to_string(),
        content: content.to_string(),
    }])
    .findings
    .is_empty()
}

fn synthetic_unified_diff(path: &str, old: &str, new: &str) -> String {
    let old_lines: Vec<&str> = old.lines().collect();
    let new_lines: Vec<&str> = new.lines().collect();
    let mut diff = format!(
        "--- a/{path}\n+++ b/{path}\n@@ -1,{} +1,{} @@\n",
        old_lines.len(),
        new_lines.len()
    );
    for line in old_lines {
        diff.push('-');
        diff.push_str(line);
        diff.push('\n');
    }
    for line in new_lines {
        diff.push('+');
        diff.push_str(line);
        diff.push('\n');
    }
    diff
}

fn append_permission_checks(
    store: &BrownieStore,
    record: &brownie_protocol::TaskRecord,
    policy: &CompiledModePolicy,
) -> anyhow::Result<()> {
    for action in [
        RuntimeAction::ReadWorkspace,
        RuntimeAction::SpawnSubtask,
        RuntimeAction::WriteWorkspace,
        RuntimeAction::ExecuteProcess,
    ] {
        let decision = RuntimePermissionGate::check(policy, action);
        debug_assert!(
            decision.allowed || decision.action != RuntimeAction::ReadWorkspace,
            "ReadWorkspace is a required runtime permission and must always be allowed"
        );
        let payload = permission_payload(policy, &decision);
        store.tasks().append_task_event_with_payload(
            record,
            LedgerEventKind::PermissionChecked,
            Some(payload.clone()),
        )?;
        if !decision.allowed {
            store.tasks().append_task_event_with_payload(
                record,
                LedgerEventKind::PermissionDenied,
                Some(payload),
            )?;
        }
    }
    Ok(())
}

fn permission_payload(
    policy: &CompiledModePolicy,
    decision: &brownie_agentmodes::PermissionDecision,
) -> Value {
    json!({
        "mode_id": policy.mode_id,
        "action": runtime_action_name(&decision.action),
        "allowed": decision.allowed,
        "reason": decision.reason,
    })
}

fn runtime_action_from_name(action: &RuntimeActionName) -> RuntimeAction {
    match action {
        RuntimeActionName::ReadWorkspace => RuntimeAction::ReadWorkspace,
        RuntimeActionName::WriteWorkspace => RuntimeAction::WriteWorkspace,
        RuntimeActionName::ExecuteProcess => RuntimeAction::ExecuteProcess,
        RuntimeActionName::AccessNetwork => RuntimeAction::AccessNetwork,
        RuntimeActionName::ControlService => RuntimeAction::ControlService,
        RuntimeActionName::DestructiveOperation => RuntimeAction::DestructiveOperation,
        RuntimeActionName::SpawnSubtask => RuntimeAction::SpawnSubtask,
        RuntimeActionName::IndexCodebase => RuntimeAction::IndexCodebase,
        RuntimeActionName::UseMcpTool => RuntimeAction::UseMcpTool,
        RuntimeActionName::UseGitCapability => RuntimeAction::UseGitCapability,
    }
}

fn runtime_action_name(action: &RuntimeAction) -> RuntimeActionName {
    match action {
        RuntimeAction::ReadWorkspace => RuntimeActionName::ReadWorkspace,
        RuntimeAction::WriteWorkspace => RuntimeActionName::WriteWorkspace,
        RuntimeAction::ExecuteProcess => RuntimeActionName::ExecuteProcess,
        RuntimeAction::AccessNetwork => RuntimeActionName::AccessNetwork,
        RuntimeAction::ControlService => RuntimeActionName::ControlService,
        RuntimeAction::DestructiveOperation => RuntimeActionName::DestructiveOperation,
        RuntimeAction::SpawnSubtask => RuntimeActionName::SpawnSubtask,
        RuntimeAction::IndexCodebase => RuntimeActionName::IndexCodebase,
        RuntimeAction::UseMcpTool => RuntimeActionName::UseMcpTool,
        RuntimeAction::UseGitCapability => RuntimeActionName::UseGitCapability,
    }
}

fn prompt_built_payload(
    message_count: usize,
    prompt: &brownie_context::PromptView,
    response_preview_chars: usize,
    max_prompt_chars: usize,
    sensitive_scan: &PromptSensitiveScanResult,
    context_window: &ContextWindowSummary,
    context_budget: &ContextBudgetSummary,
    selected_index_context_present: bool,
) -> Value {
    let mut payload = serde_json::Map::new();
    payload.insert("message_count".to_string(), json!(message_count));
    payload.insert("max_prompt_chars".to_string(), json!(max_prompt_chars));
    payload.insert(
        "context_total_events".to_string(),
        json!(context_window.total_events),
    );
    payload.insert(
        "context_included_events".to_string(),
        json!(context_window.included_events),
    );
    payload.insert(
        "context_omitted_events".to_string(),
        json!(context_window.omitted_events),
    );
    payload.insert(
        "context_max_events".to_string(),
        json!(context_window.max_events),
    );
    payload.insert(
        "context_window_bounded".to_string(),
        json!(context_window.omitted_events > 0),
    );
    if let Some(first) = context_window.first_included_event.as_deref() {
        payload.insert("context_first_included_event".to_string(), json!(first));
    }
    if let Some(last) = context_window.last_included_event.as_deref() {
        payload.insert("context_last_included_event".to_string(), json!(last));
    }
    if context_budget.requested {
        payload.insert("context_budget_requested".to_string(), json!(true));
        payload.insert(
            "context_budget_max_prompt_chars".to_string(),
            json!(context_budget.max_prompt_chars),
        );
        payload.insert(
            "context_budget_max_ledger_events".to_string(),
            json!(context_budget.max_ledger_events),
        );
        payload.insert(
            "context_budget_max_selected_index_chars".to_string(),
            json!(context_budget.max_selected_index_chars),
        );
        payload.insert(
            "context_budget_prompt_chars".to_string(),
            json!(context_budget.prompt_chars),
        );
        payload.insert(
            "context_budget_protected_context_chars".to_string(),
            json!(context_budget.protected_context_chars),
        );
        payload.insert(
            "context_budget_prompt_within_budget".to_string(),
            json!(context_budget.prompt_within_budget),
        );
        payload.insert(
            "context_budget_selected_index_context_present".to_string(),
            json!(context_budget.selected_index_context_present),
        );
        payload.insert(
            "context_budget_selected_index_content_chars".to_string(),
            json!(context_budget.selected_index_content_chars),
        );
        payload.insert(
            "context_budget_selected_index_materialized_chars".to_string(),
            json!(context_budget.selected_index_materialized_chars),
        );
        payload.insert(
            "context_budget_selected_index_truncated".to_string(),
            json!(context_budget.selected_index_truncated),
        );
    }
    if selected_index_context_present {
        payload.insert("prompt_preview_redacted".to_string(), json!(true));
        payload.insert(
            "prompt_preview_redaction_reason".to_string(),
            json!("selected_index_context_present"),
        );
    } else if sensitive_scan.findings.is_empty() {
        payload.insert(
            "prompt_preview".to_string(),
            json!(preview_prompt(prompt, response_preview_chars)),
        );
    } else {
        payload.insert("prompt_preview_redacted".to_string(), json!(true));
    }
    Value::Object(payload)
}

fn llm_response_received_payload(
    provider_status: &brownie_llm::LlmProviderStatus,
    response_content: &str,
    response_preview_chars: usize,
    selected_index_context_present: bool,
) -> Value {
    let mut payload = serde_json::Map::new();
    payload.insert(
        "provider".to_string(),
        json!(provider_kind_name(&provider_status.provider)),
    );
    payload.insert(
        "response_preview_chars".to_string(),
        json!(response_preview_chars),
    );
    if selected_index_context_present {
        payload.insert("content_preview_redacted".to_string(), json!(true));
        payload.insert(
            "content_preview_redaction_reason".to_string(),
            json!("selected_index_context_present"),
        );
    } else {
        payload.insert(
            "content_preview".to_string(),
            json!(preview_with_limit(response_content, response_preview_chars)),
        );
    }
    Value::Object(payload)
}

fn preview_prompt(prompt: &brownie_context::PromptView, max_chars: usize) -> String {
    if prompt.messages.len() > 1 {
        let system_limit = max_chars.min(160);
        let system_preview = preview_with_limit(&prompt.messages[0].content, system_limit);
        let separator = "\n---\n";
        let used = system_preview.chars().count() + separator.chars().count();
        let remaining = max_chars.saturating_sub(used);
        let rest = prompt
            .messages
            .iter()
            .skip(1)
            .map(|message| message.content.as_str())
            .collect::<Vec<_>>()
            .join(separator);
        let joined = format!(
            "{}{}{}",
            system_preview,
            separator,
            preview_with_limit(&rest, remaining)
        );
        return preview_with_limit(&joined, max_chars);
    }

    let joined = prompt
        .messages
        .iter()
        .map(|message| message.content.as_str())
        .collect::<Vec<_>>()
        .join("\n---\n");
    preview_with_limit(&joined, max_chars)
}

fn preview_with_limit(content: &str, max_chars: usize) -> String {
    content.chars().take(max_chars).collect()
}

fn preview_tool_output(content: &str) -> String {
    const MAX_TOOL_OUTPUT_PREVIEW_CHARS: usize = 24;
    content
        .chars()
        .take(MAX_TOOL_OUTPUT_PREVIEW_CHARS)
        .collect()
}

fn parse_params<T: serde::de::DeserializeOwned>(params: Option<Value>) -> Result<T, String> {
    let params = params.ok_or_else(|| "invalid params: missing params".to_string())?;
    serde_json::from_value(params).map_err(|error| format!("invalid params: {error}"))
}

fn parse_error_response(error: serde_json::Error) -> JsonRpcResponse<Value> {
    JsonRpcResponse {
        jsonrpc: JSONRPC_VERSION.to_string(),
        id: Value::Null,
        result: None,
        error: Some(JsonRpcError {
            code: -32700,
            message: format!("parse error: {error}"),
        }),
    }
}

fn result_response(id: Value, result: Value) -> JsonRpcResponse<Value> {
    JsonRpcResponse {
        jsonrpc: JSONRPC_VERSION.to_string(),
        id,
        result: Some(result),
        error: None,
    }
}

fn headless_continue_once_result_response(
    id: Value,
    result: &HeadlessContinueOnceResult,
) -> JsonRpcResponse<Value> {
    let mut value = json!(result);
    insert_execution_outcome(&mut value, headless_continue_once_execution_outcome(result));
    result_response(id, value)
}

fn headless_run_advance_result_response(
    id: Value,
    result: &HeadlessRunAdvanceResult,
) -> JsonRpcResponse<Value> {
    let mut value = json!(result);
    insert_execution_outcome(&mut value, headless_run_advance_execution_outcome(result));
    result_response(id, value)
}

fn headless_run_drive_result_response(
    id: Value,
    result: &HeadlessRunDriveResult,
) -> JsonRpcResponse<Value> {
    let mut value = json!(result);
    insert_execution_outcome(&mut value, headless_run_drive_execution_outcome(result));
    result_response(id, value)
}

fn insert_execution_outcome(result: &mut Value, outcome: Value) {
    if let Some(object) = result.as_object_mut() {
        object.insert("execution_outcome".to_string(), outcome);
    }
}

fn headless_continue_once_execution_outcome(result: &HeadlessContinueOnceResult) -> Value {
    let stop_reason = result
        .stop_reason
        .clone()
        .unwrap_or_else(|| match result.status {
            HeadlessContinueOnceStatus::StaleProgress => "stale_progress".to_string(),
            HeadlessContinueOnceStatus::NoEligibleTask => "no_eligible_task".to_string(),
            HeadlessContinueOnceStatus::TaskInProgress => "task_in_progress".to_string(),
            HeadlessContinueOnceStatus::TaskExecuted => "bounded_progress".to_string(),
        });
    match result.status {
        HeadlessContinueOnceStatus::StaleProgress => execution_outcome_value(
            "stale_retry",
            "resume",
            true,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
        HeadlessContinueOnceStatus::NoEligibleTask => execution_outcome_value(
            "no_actionable_work",
            "stop",
            false,
            false,
            false,
            false,
            false,
            &stop_reason,
        ),
        HeadlessContinueOnceStatus::TaskInProgress => execution_outcome_value(
            "waiting",
            "wait",
            false,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
        HeadlessContinueOnceStatus::TaskExecuted => execution_outcome_value(
            "continuation_required",
            "resume",
            true,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
    }
}

fn headless_run_advance_execution_outcome(result: &HeadlessRunAdvanceResult) -> Value {
    let stop_reason = result.stop_reason.clone();
    match result.status {
        HeadlessContinueOnceStatus::StaleProgress => execution_outcome_value(
            "stale_retry",
            "resume",
            true,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
        HeadlessContinueOnceStatus::NoEligibleTask => execution_outcome_value(
            "no_actionable_work",
            "stop",
            false,
            false,
            false,
            false,
            false,
            &stop_reason,
        ),
        HeadlessContinueOnceStatus::TaskInProgress => execution_outcome_value(
            "waiting",
            "wait",
            false,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
        HeadlessContinueOnceStatus::TaskExecuted => execution_outcome_value(
            "continuation_required",
            "resume",
            true,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
    }
}

fn headless_run_drive_execution_outcome(result: &HeadlessRunDriveResult) -> Value {
    let stop_reason = result.stop_reason.clone();
    if result
        .completion_finalization
        .as_ref()
        .map(|finalization| finalization.status == "finalized")
        .unwrap_or(false)
    {
        return execution_outcome_value(
            "completed",
            "stop",
            false,
            true,
            false,
            false,
            false,
            &stop_reason,
        );
    }
    if result.completion_closure.status == HeadlessRunCompletionClosureStatus::Complete
        && result
            .accepted_completion
            .as_ref()
            .map(|accepted| accepted.status == "AcceptedComplete")
            .unwrap_or(false)
    {
        return execution_outcome_value(
            "completed",
            "stop",
            false,
            true,
            false,
            false,
            false,
            &stop_reason,
        );
    }

    match result.completion_closure.status {
        HeadlessRunCompletionClosureStatus::StaleNoProgress => execution_outcome_value(
            "stale_retry",
            "resume",
            true,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
        HeadlessRunCompletionClosureStatus::TaskInProgress => execution_outcome_value(
            "waiting",
            "wait",
            false,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
        HeadlessRunCompletionClosureStatus::NoEligibleTask => execution_outcome_value(
            "no_actionable_work",
            "stop",
            false,
            false,
            false,
            false,
            false,
            &stop_reason,
        ),
        HeadlessRunCompletionClosureStatus::Complete
        | HeadlessRunCompletionClosureStatus::RoutedExplicitAction
        | HeadlessRunCompletionClosureStatus::BudgetExhausted
        | HeadlessRunCompletionClosureStatus::UnknownNonterminal => execution_outcome_value(
            "continuation_required",
            "resume",
            true,
            false,
            false,
            true,
            false,
            &stop_reason,
        ),
    }
}

fn execution_outcome_value(
    class_name: &str,
    controller_action: &str,
    continuation_required: bool,
    completed: bool,
    blocked: bool,
    retryable: bool,
    terminal_failure: bool,
    stop_reason: &str,
) -> Value {
    let next_invocation = if controller_action == "resume" {
        json!({
            "command": "resume",
            "arguments": []
        })
    } else {
        Value::Null
    };
    json!({
        "schema_version": 1,
        "outcome_scope": "objective",
        "class": class_name,
        "status": class_name,
        "controller_action": controller_action,
        "continuation_required": continuation_required,
        "completed": completed,
        "blocked": blocked,
        "retryable": retryable,
        "terminal_failure": terminal_failure,
        "stop_reason": stop_reason,
        "next_invocation": next_invocation
    })
}

fn error_response(id: Value, code: i64, message: &str) -> JsonRpcResponse<Value> {
    JsonRpcResponse {
        jsonrpc: JSONRPC_VERSION.to_string(),
        id,
        result: None,
        error: Some(JsonRpcError {
            code,
            message: message.to_string(),
        }),
    }
}

