    #[test]
    fn project_completion_policy_commits_all_closed_required_gap_evidence() {
        let first_gap = product_gap_for_test("m63-gap-a", "m63_gap_a", 10);
        let second_gap = product_gap_for_test("m63-gap-b", "m63_gap_b", 20);
        let first_closure = selected_gap_closure_for_test("m63-closure-a", first_gap.clone());
        let second_closure = selected_gap_closure_for_test("m63-closure-b", second_gap.clone());
        let mut closures = BTreeMap::new();
        closures.insert(
            second_gap.selection_fingerprint.clone(),
            second_closure.clone(),
        );
        closures.insert(
            first_gap.selection_fingerprint.clone(),
            first_closure.clone(),
        );
        let policy_gaps = json!([
            {
                "gap_id": first_gap.gap_id,
                "capability": first_gap.capability,
                "transition": first_gap.transition,
                "status": first_gap.status,
                "required": first_gap.required,
                "priority": first_gap.priority,
                "next_action": first_gap.next_action,
            },
            {
                "gap_id": second_gap.gap_id,
                "capability": second_gap.capability,
                "transition": second_gap.transition,
                "status": second_gap.status,
                "required": second_gap.required,
                "priority": second_gap.priority,
                "next_action": second_gap.next_action,
            }
        ]);

        let (
            selected_remaining_gap,
            selected_gap_closure_evidence,
            selected_gap_closure_evidence_set,
            selected_gap_closure_set_fingerprint,
            product_completion_claim,
        ) = project_completion_policy_remaining_gap_selection(Some(&policy_gaps), false, &closures)
            .expect("closed required gaps are consumed");

        assert!(selected_remaining_gap.is_none());
        assert_eq!(selected_gap_closure_evidence_set.len(), 2);
        assert_eq!(
            selected_gap_closure_evidence
                .as_ref()
                .expect("compat selected closure")
                .closure_evidence_fingerprint,
            selected_gap_closure_evidence_set[0].closure_evidence_fingerprint
        );
        assert!(selected_gap_closure_set_fingerprint
            .as_deref()
            .expect("closure set fingerprint")
            .starts_with("sha256:"));
        assert!(product_completion_claim);

        let mut partial_closures = BTreeMap::new();
        partial_closures.insert(first_gap.selection_fingerprint.clone(), first_closure);
        let (
            selected_remaining_gap,
            _selected_gap_closure_evidence,
            selected_gap_closure_evidence_set,
            selected_gap_closure_set_fingerprint,
            product_completion_claim,
        ) = project_completion_policy_remaining_gap_selection(
            Some(&policy_gaps),
            false,
            &partial_closures,
        )
        .expect("remaining open gap is still selected");

        assert_eq!(
            selected_remaining_gap.expect("second gap selected").gap_id,
            "m63-gap-b"
        );
        assert_eq!(selected_gap_closure_evidence_set.len(), 1);
        assert!(selected_gap_closure_set_fingerprint.is_some());
        assert!(!product_completion_claim);
    }

    #[test]
    fn verification_recovery_context_excerpt_is_bounded_and_hashed() {
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join("src")).expect("src dir");
        std::fs::write(
            temp.path().join("src/lib.rs"),
            "line1\nline2\nline3\nline4 target\nline5\nline6\nline7\n",
        )
        .expect("source");

        let excerpt =
            read_verification_recovery_context_excerpt(temp.path(), "src/lib.rs", Some(4), 64)
                .expect("excerpt");

        assert_eq!(excerpt.start_line, 1);
        assert_eq!(excerpt.end_line, 6);
        assert!(excerpt.content.contains("line4 target"));
        assert!(excerpt.bytes <= 64);
        assert_eq!(
            excerpt.sha256,
            format!("sha256:{}", hex_sha256(excerpt.content.as_bytes()))
        );
    }

    #[test]
    fn verification_recovery_context_excerpt_rejects_parent_traversal() {
        let temp = tempfile::tempdir().expect("tempdir");
        let error =
            read_verification_recovery_context_excerpt(temp.path(), "../outside.rs", Some(1), 128)
                .expect_err("parent traversal denied");

        match error {
            TaskRunAdmissionRejection::InvalidParams(message) => {
                assert!(
                    message.contains("target is missing") || message.contains("target is unsafe")
                );
            }
            TaskRunAdmissionRejection::Internal(message) => {
                panic!("unexpected internal error: {message}")
            }
        }
    }

    #[test]
    fn verification_recovery_context_read_rejects_non_recovery_task_before_running() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"plain task","mode_id":"orchestrator"}}"#,
        )
        .result
        .expect("task started");
        let task_id = start["task_id"].as_str().expect("task id");
        let run_id = start["run_id"].as_str().expect("run id");

        let run = parse_line(&format!(
            r#"{{
  "jsonrpc": "2.0",
  "id": 2,
  "method": "task.run",
  "params": {{
    "task_id": "{task_id}",
    "verification_recovery_context_read": {{
      "authorize": true,
      "source_task_id": "task_source",
      "source_run_id": "run_source",
      "expected_failure_fingerprint": "sha256:{hash}",
      "diagnostic_index": 0,
      "max_excerpt_bytes": 128
    }}
  }}
}}"#,
            hash = "a".repeat(64)
        ));
        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");

        assert!(run
            .error
            .expect("rejected")
            .message
            .contains("verification_recovery_context_read"));
        let events = store_events(temp.path(), run_id);
        assert!(!events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));
        assert!(!events.iter().any(|event| {
            event.kind == LedgerEventKind::VerificationRecoveryContextReadMaterialized
        }));
    }

    #[cfg(unix)]
    #[test]
    fn codebase_index_build_persists_snapshot_and_bounded_ledger_event() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir(temp.path().join(".brownie")).expect("brownie dir");
        std::fs::create_dir(temp.path().join("src")).expect("src dir");
        std::fs::write(
            temp.path().join("src/lib.rs"),
            "pub fn ok() -> u8 {\n    1\n}\n",
        )
        .expect("src");
        std::fs::write(
            temp.path().join("Cargo.toml"),
            "[package]\nname = \"idx\"\n",
        )
        .expect("manifest");
        std::fs::write(temp.path().join("README.md"), "# Index\n").expect("readme");
        std::fs::write(
            temp.path().join(".gitignore"),
            "ignored.log\nignored-dir/\n",
        )
        .expect("ignore policy");
        std::fs::write(temp.path().join("ignored.log"), "ignore me\n").expect("ignored file");
        std::fs::create_dir(temp.path().join("ignored-dir")).expect("ignored dir");
        std::fs::write(
            temp.path().join("ignored-dir/hidden.rs"),
            "pub fn hidden() {}\n",
        )
        .expect("ignored dir file");
        std::fs::write(temp.path().join(".env"), "TOKEN=secret\n").expect("env");
        std::fs::write(temp.path().join("notes.txt"), "api_key: sk-runtime-test\n")
            .expect("sensitive content");
        std::fs::create_dir_all(temp.path().join("node_modules/pkg")).expect("node_modules");
        std::fs::write(
            temp.path().join("node_modules/pkg/index.js"),
            "module.exports = 1;",
        )
        .expect("dependency");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let first = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"codebase.index.build","params":{"mode_id":"orchestrator"}}"#,
        );
        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        let result = first.result.expect("index build result");
        assert_eq!(result["persisted"], true);
        assert_eq!(result["ledger_event_kind"], "CodebaseIndexSnapshotBuilt");
        assert_eq!(
            result["next_action"],
            "build_bounded_index_query_file_selection"
        );
        assert_eq!(result["snapshot"]["root"], ".");
        assert_eq!(result["snapshot"]["counts"]["indexed_files"], 3);
        assert_eq!(result["snapshot"]["counts"]["skipped_protected"], 2);
        assert_eq!(result["snapshot"]["counts"]["skipped_ignored"], 3);
        assert_eq!(result["snapshot"]["counts"]["skipped_sensitive"], 2);
        assert_eq!(result["snapshot"]["counts"]["ignore_rule_files_loaded"], 1);
        assert_eq!(result["snapshot"]["counts"]["ignore_rule_count"], 2);
        assert!(
            result["snapshot"]["counts"]["sensitive_finding_count"]
                .as_u64()
                .expect("sensitive finding count")
                >= 1
        );
        assert!(
            result["snapshot"]["counts"]["visited_entries"]
                .as_u64()
                .expect("visited entries")
                > 0
        );
        assert!(
            result["snapshot"]["limits"]["max_visited_entries"]
                .as_u64()
                .expect("max visited")
                > 0
        );
        assert!(result["snapshot"]["snapshot_fingerprint"]
            .as_str()
            .expect("snapshot fingerprint")
            .starts_with("sha256:"));

        let store = BrownieStore::new(temp.path());
        let current = store
            .codebase_index()
            .read_current_snapshot()
            .expect("read current")
            .expect("current snapshot");
        assert_eq!(current.entries.len(), 3);
        assert!(current.entries.iter().all(|entry| {
            !entry.path.contains(".brownie")
                && !entry.path.contains("node_modules")
                && !entry.path.contains("ignored")
                && !entry.path.ends_with(".env")
                && !entry.path.starts_with('/')
        }));
        assert!(current
            .entries
            .iter()
            .any(|entry| entry.path == "src/lib.rs" && entry.file_kind == "Rust"));

        let events = store.codebase_index().read_events().expect("index events");
        assert_eq!(events.len(), 2);
        assert_eq!(
            events[0].kind,
            LedgerEventKind::CodebaseIndexPermissionChecked
        );
        assert_eq!(events[0].payload["action"], "IndexCodebase");
        assert_eq!(events[0].payload["allowed"], true);
        assert_eq!(events[1].kind, LedgerEventKind::CodebaseIndexSnapshotBuilt);
        let payload = &events[1].payload;
        assert_eq!(payload["requested_force_refresh"], false);
        assert_eq!(
            payload["next_action"],
            "build_bounded_index_query_file_selection"
        );
        assert_eq!(payload["skipped_ignored"], 3);
        assert_eq!(payload["skipped_sensitive"], 2);
        assert_eq!(payload["ignore_rule_files_loaded"], 1);
        assert_eq!(payload["ignore_rule_count"], 2);
        assert!(
            payload["sensitive_finding_count"]
                .as_u64()
                .expect("payload sensitive finding count")
                >= 1
        );
        for forbidden in [
            "content",
            "file_content",
            "full_content",
            "absolute_path",
            "canonical_path",
            "raw_ignore_patterns",
            "raw_sensitive_matches",
            "stdout",
            "stderr",
            "env",
            "raw_input",
        ] {
            assert!(
                payload.get(forbidden).is_none(),
                "forbidden payload field {forbidden}"
            );
        }

        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        let second = parse_line(
            r#"{"jsonrpc":"2.0","id":2,"method":"codebase.index.build","params":{"mode_id":"orchestrator"}}"#,
        );
        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        let second_result = second.result.expect("second result");
        assert_eq!(
            result["snapshot"]["snapshot_fingerprint"],
            second_result["snapshot"]["snapshot_fingerprint"]
        );

        std::fs::write(
            temp.path().join("src/lib.rs"),
            "pub fn ok() -> u8 {\n    2\n}\n",
        )
        .expect("change src");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        let changed = parse_line(
            r#"{"jsonrpc":"2.0","id":3,"method":"codebase.index.build","params":{"mode_id":"orchestrator"}}"#,
        );
        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        let changed_result = changed.result.expect("changed result");
        assert_ne!(
            result["snapshot"]["snapshot_fingerprint"],
            changed_result["snapshot"]["snapshot_fingerprint"]
        );
    }

