    #[test]
    fn codebase_index_selection_read_returns_bounded_content_and_summary_event() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::fs::create_dir_all(temp.path().join("src/runtime")).expect("src dir");
        let selected_content = "pub fn selected() {}\n";
        std::fs::write(temp.path().join("src/runtime/query.rs"), selected_content)
            .expect("selected file");
        std::fs::write(temp.path().join("src/lib.rs"), "pub fn other() {}\n").expect("other");
        let store = BrownieStore::new(temp.path());
        store
            .codebase_index()
            .write_current_snapshot(&query_test_manifest(vec![
                selected_read_test_entry("src/runtime/query.rs", "Rust", selected_content),
                selected_read_test_entry("src/lib.rs", "Rust", "pub fn other() {}\n"),
            ]))
            .expect("write current");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let query = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"codebase.index.query","params":{"mode_id":"orchestrator","query":"runtime rs","max_results":2,"file_kind":"Rust"}}"#,
        )
        .result
        .expect("query result");
        let selected_read = handle_tool_execute(
            json!(2),
            Some(json!({
                "mode_id": "orchestrator",
                "tool_id": CODEBASE_INDEX_SELECTION_READ_TOOL_ID,
                "input": selected_read_input_from_query(&query, "src/runtime/query.rs", Some("Rust")),
            })),
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        assert!(selected_read.error.is_none());
        let result = selected_read.result.expect("selected read result");
        assert_eq!(result["tool_id"], CODEBASE_INDEX_SELECTION_READ_TOOL_ID);
        assert_eq!(result["status"], "Completed");
        assert_eq!(result["output"]["path"], "src/runtime/query.rs");
        assert_eq!(result["output"]["content"], selected_content);
        assert_eq!(result["output"]["truncated"], false);
        assert_eq!(result["output"]["content_hash_verified"], true);
        assert_eq!(
            result["output"]["ledger_event_kind"],
            "CodebaseIndexSelectionReadCompleted"
        );
        assert_eq!(
            result["output"]["next_action"],
            "use_selected_file_context_for_prompt_materialization"
        );

        let events = store.codebase_index().read_events().expect("events");
        let read_event = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::CodebaseIndexSelectionReadCompleted)
            .expect("read event");
        assert_eq!(
            read_event.payload["tool_id"],
            CODEBASE_INDEX_SELECTION_READ_TOOL_ID
        );
        assert_eq!(
            read_event.payload["content_hash_verified"],
            serde_json::Value::Bool(true)
        );
        assert!(read_event.payload["read_path_fingerprint"]
            .as_str()
            .expect("path fingerprint")
            .starts_with("sha256:"));
        for forbidden in [
            "query",
            "raw_query",
            "path",
            "read_path",
            "content",
            "file_content",
            "full_content",
            "raw_input",
            "stdout",
            "stderr",
            "env",
            "command",
            "absolute_path",
            "canonical_path",
        ] {
            assert!(
                read_event.payload.get(forbidden).is_none(),
                "forbidden event field {forbidden}"
            );
        }
        let ledger =
            std::fs::read_to_string(temp.path().join(".brownie/codebase-index/ledger.jsonl"))
                .expect("ledger");
        assert!(!ledger.contains(selected_content));
        assert!(!ledger.contains("src/runtime/query.rs"));
    }

    #[test]
    fn task_run_materializes_selected_index_context_from_prior_read() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let selected_content = "pub fn selected_context() {}\n";
        let (store, selected_context) =
            prepared_selected_index_context(temp.path(), selected_content);
        let start = handle_task_start(
            json!(3),
            Some(json!({
                "goal": "Use selected runtime context",
                "mode_id": "orchestrator"
            })),
        )
        .result
        .expect("task start result");
        let task_id = start["task_id"].as_str().expect("task id");
        let run_id = start["run_id"].as_str().expect("run id");

        let run = handle_task_run(
            json!(4),
            Some(json!({
                "task_id": task_id,
                "selected_index_context": selected_context.clone(),
            })),
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        assert!(run.error.is_none());
        let result = run.result.expect("task run result");
        assert_eq!(result["status"], "Completed");
        let summary = &result["selected_index_prompt_context"];
        assert_eq!(
            summary["source_event_id"],
            selected_context["ledger_event_id"]
        );
        assert_eq!(
            summary["source_event_kind"],
            "CodebaseIndexSelectionReadCompleted"
        );
        assert_eq!(
            summary["content_sha256"],
            selected_context["content_sha256"]
        );
        assert_eq!(summary["prompt_preview_redacted"], true);
        assert_eq!(
            summary["next_action"],
            "continue_task_execution_with_materialized_context"
        );
        assert!(summary["read_path_fingerprint"]
            .as_str()
            .expect("read path fingerprint")
            .starts_with("sha256:"));
        let result_json = serde_json::to_string(&result).expect("result json");
        assert!(!result_json.contains(selected_content));
        assert!(!result_json.contains("src/runtime/query.rs"));

        let events = store
            .tasks()
            .read_ledger_events(run_id)
            .expect("task events");
        let materialized = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::CodebaseIndexPromptContextMaterialized)
            .expect("materialized event");
        let materialized_payload = materialized.payload.as_ref().expect("payload");
        assert_eq!(
            materialized_payload["source_event_id"],
            summary["source_event_id"]
        );
        assert_eq!(materialized_payload["prompt_preview_redacted"], true);
        for forbidden in [
            "path",
            "read_path",
            "content",
            "file_content",
            "full_content",
            "raw_input",
            "stdout",
            "stderr",
            "env",
            "command",
            "absolute_path",
            "canonical_path",
        ] {
            assert!(
                materialized_payload.get(forbidden).is_none(),
                "forbidden materialized payload field {forbidden}"
            );
        }
        let prompt_built = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::PromptBuilt)
            .expect("prompt built event");
        let prompt_payload = prompt_built.payload.as_ref().expect("prompt payload");
        assert_eq!(prompt_payload["prompt_preview_redacted"], true);
        assert_eq!(
            prompt_payload["prompt_preview_redaction_reason"],
            "selected_index_context_present"
        );
        assert!(prompt_payload.get("prompt_preview").is_none());
        let response_event = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::LlmResponseReceived)
            .expect("llm response event");
        let response_payload = response_event.payload.as_ref().expect("response payload");
        assert_eq!(response_payload["content_preview_redacted"], true);
        assert_eq!(
            response_payload["content_preview_redaction_reason"],
            "selected_index_context_present"
        );
        assert!(response_payload.get("content_preview").is_none());
        if let Some(second_pass_response_event) = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::SecondPassLlmResponseReceived)
        {
            let second_pass_response_payload = second_pass_response_event
                .payload
                .as_ref()
                .expect("second-pass response payload");
            assert_eq!(
                second_pass_response_payload["content_preview_redacted"],
                true
            );
            assert_eq!(
                second_pass_response_payload["content_preview_redaction_reason"],
                "selected_index_context_present"
            );
            assert!(second_pass_response_payload
                .get("content_preview")
                .is_none());
        }
        let ledger_json = serde_json::to_string(&events).expect("ledger json");
        assert!(!ledger_json.contains(selected_content));
        assert!(!ledger_json.contains("src/runtime/query.rs"));
    }

    #[test]
    fn task_run_applies_explicit_context_budget_to_materialized_context() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let selected_content = "pub fn selected_context_budget() { let marker = 42; }\n";
        let (store, selected_context) =
            prepared_selected_index_context(temp.path(), selected_content);
        let start = handle_task_start(
            json!(3),
            Some(json!({
                "goal": "Use a bounded selected runtime context",
                "mode_id": "orchestrator"
            })),
        )
        .result
        .expect("task start result");
        let task_id = start["task_id"].as_str().expect("task id");
        let run_id = start["run_id"].as_str().expect("run id");

        let run = handle_task_run(
            json!(4),
            Some(json!({
                "task_id": task_id,
                "selected_index_context": selected_context.clone(),
                "context_budget": {
                    "max_prompt_chars": 20000,
                    "max_ledger_events": 1,
                    "max_selected_index_chars": 12
                }
            })),
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        assert!(run.error.is_none());
        let result = run.result.expect("task run result");
        assert_eq!(result["status"], "Completed");
        let context_budget = &result["context_budget"];
        assert_eq!(context_budget["requested"], true);
        assert_eq!(context_budget["max_ledger_events"], 1);
        assert_eq!(context_budget["included_events"], 1);
        assert_eq!(context_budget["selected_index_context_present"], true);
        assert_eq!(context_budget["selected_index_content_chars"], 54);
        assert_eq!(context_budget["selected_index_materialized_chars"], 12);
        assert_eq!(context_budget["selected_index_truncated"], true);
        assert_eq!(context_budget["prompt_within_budget"], true);
        let summary = &result["selected_index_prompt_context"];
        assert_eq!(summary["content_char_count"], 54);
        assert_eq!(summary["materialized_content_char_count"], 12);
        assert_eq!(summary["content_truncated_for_prompt"], true);
        let result_json = serde_json::to_string(&result).expect("result json");
        assert!(!result_json.contains(selected_content));

        let events = store
            .tasks()
            .read_ledger_events(run_id)
            .expect("task events");
        let prompt_built = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::PromptBuilt)
            .expect("prompt built event");
        let prompt_payload = prompt_built.payload.as_ref().expect("prompt payload");
        assert_eq!(prompt_payload["context_budget_requested"], true);
        assert_eq!(prompt_payload["context_budget_max_ledger_events"], 1);
        assert_eq!(
            prompt_payload["context_budget_selected_index_context_present"],
            true
        );
        assert_eq!(
            prompt_payload["context_budget_selected_index_content_chars"],
            54
        );
        assert_eq!(
            prompt_payload["context_budget_selected_index_materialized_chars"],
            12
        );
        assert_eq!(
            prompt_payload["context_budget_selected_index_truncated"],
            true
        );
        assert!(prompt_payload.get("prompt_preview").is_none());

        let record = store
            .tasks()
            .get_task(task_id)
            .expect("get task")
            .expect("task record");
        let replay = task_run_result_for_headless_replay(&store, &record)
            .expect("replay result")
            .expect("terminal replay");
        let replay_budget = replay.context_budget.expect("replay context budget");
        assert_eq!(replay_budget.max_ledger_events, 1);
        assert_eq!(replay_budget.selected_index_content_chars, 54);
        assert_eq!(replay_budget.selected_index_materialized_chars, 12);
        assert_eq!(replay_budget.selected_index_truncated, true);
    }

