    #[test]
    fn headless_run_drive_journey_execution_admits_checkpoints_and_replays_without_new_task() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let request = r#"{"jsonrpc":"2.0","id":1,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m50.exec","drive_id":"m50.exec.drive","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_execution":{"journey_id":"m50.exec.1","authorize_journey_execution":true,"task_start":{"goal":"Run a runtime-owned execution journey","mode_id":"implementer"}}}}"#;
        let response = parse_line(request);
        let result = response
            .result
            .unwrap_or_else(|| panic!("journey execution result: {:?}", response.error));
        assert_eq!(result["status"], "task_executed");
        assert_eq!(result["session_id"], "m50.exec");
        assert_eq!(result["journey_execution"]["journey_id"], "m50.exec.1");
        assert_eq!(result["journey_execution"]["complete"], false);
        assert_eq!(
            result["journey_execution"]["completed_boundaries"][0]["boundary"],
            "admit_journey"
        );
        assert_eq!(
            result["journey_execution"]["completed_boundaries"][0]["drive_id"],
            "m50.exec.drive.admit"
        );
        assert!(
            result["journey_execution"]["execution_checkpoint_fingerprint"]
                .as_str()
                .expect("execution checkpoint fingerprint")
                .starts_with("sha256:")
        );
        assert!(result["journey_execution"].get("raw_prompt").is_none());
        assert!(result["journey_execution"]
            .get("provider_response")
            .is_none());
        assert!(result["journey_execution"].get("absolute_path").is_none());

        let task_count_after_first_drive = store.tasks().list_tasks().expect("tasks").len();
        assert_eq!(task_count_after_first_drive, 1);
        let replay_response = parse_line(request);
        let replay = replay_response.result.unwrap_or_else(|| {
            panic!(
                "journey execution replay result: {:?}",
                replay_response.error
            )
        });
        assert_eq!(replay["replayed"], true);
        assert_eq!(replay["journey_execution"]["replayed"], true);
        assert_eq!(
            replay["journey_execution"]["execution_checkpoint_fingerprint"],
            result["journey_execution"]["execution_checkpoint_fingerprint"]
        );
        assert_eq!(
            store.tasks().list_tasks().expect("tasks").len(),
            task_count_after_first_drive
        );
        let restart_request = json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "headless.run.drive",
            "params": {
                "authorize": true,
                "session_id": "m50.exec",
                "drive_id": "m50.exec.drive",
                "expected_start_session_sequence": result["end_session_sequence"]
                    .as_u64()
                    .expect("end session sequence"),
                "max_advances": 2,
                "max_steps_per_advance": 1,
                "journey_execution": {
                    "journey_id": "m50.exec.1",
                    "authorize_journey_execution": true,
                    "expected_journey_fingerprint": result["journey_execution"]["journey_fingerprint"]
                        .as_str()
                        .expect("journey fingerprint"),
                    "expected_execution_checkpoint_fingerprint": result["journey_execution"]["execution_checkpoint_fingerprint"]
                        .as_str()
                        .expect("execution checkpoint fingerprint")
                }
            }
        })
        .to_string();
        let restart_response = parse_line(&restart_request);
        let restart = restart_response.result.unwrap_or_else(|| {
            panic!(
                "journey execution restart result: {:?}",
                restart_response.error
            )
        });
        assert_eq!(restart["replayed"], true);
        assert_eq!(restart["journey_execution"]["replayed"], true);
        assert_eq!(
            restart["journey_execution"]["execution_checkpoint_fingerprint"],
            result["journey_execution"]["execution_checkpoint_fingerprint"]
        );
        assert_eq!(
            store.tasks().list_tasks().expect("tasks").len(),
            task_count_after_first_drive
        );
        let run_id = result["journey_execution"]["run_id"]
            .as_str()
            .expect("run id");
        let events = store.tasks().read_ledger_events(run_id).expect("events");
        assert_eq!(
            events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskStarted)
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessJourneyStarted)
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessJourneyExecuted)
                .count(),
            0
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_drive_journey_execution_recovers_committed_admission_without_execution_checkpoint(
    ) {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let admission_request = r#"{"jsonrpc":"2.0","id":1,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m50.recover","drive_id":"m50.recover.drive.admit","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_admission":{"journey_id":"m50.recover.1","authorize_journey_start":true,"task_start":{"goal":"Recover committed admission","mode_id":"implementer"}}}}"#;
        let admission_response = parse_line(admission_request);
        let admission = admission_response
            .result
            .unwrap_or_else(|| panic!("admission result: {:?}", admission_response.error));
        assert_eq!(admission["status"], "task_executed");
        assert!(store
            .tasks()
            .read_headless_journey_execution_checkpoint("m50.recover.1")
            .expect("execution checkpoint before recovery")
            .is_none());
        let task_count_after_admission = store.tasks().list_tasks().expect("tasks").len();
        assert_eq!(task_count_after_admission, 1);

        let execution_request = r#"{"jsonrpc":"2.0","id":2,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m50.recover","drive_id":"m50.recover.drive","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_execution":{"journey_id":"m50.recover.1","authorize_journey_execution":true,"task_start":{"goal":"Recover committed admission","mode_id":"implementer"}}}}"#;
        let execution_response = parse_line(execution_request);
        let execution = execution_response
            .result
            .unwrap_or_else(|| panic!("execution recovery result: {:?}", execution_response.error));
        assert_eq!(execution["replayed"], true);
        assert_eq!(execution["journey_execution"]["replayed"], true);
        assert_eq!(
            execution["journey_execution"]["completed_boundaries"][0]["boundary"],
            "admit_journey"
        );
        assert_eq!(
            execution["journey_execution"]["completed_boundaries"][0]["drive_id"],
            "m50.recover.drive.admit"
        );
        assert!(store
            .tasks()
            .read_headless_journey_execution_checkpoint("m50.recover.1")
            .expect("execution checkpoint after recovery")
            .is_some());
        assert_eq!(
            store.tasks().list_tasks().expect("tasks").len(),
            task_count_after_admission
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_recovery_probe_distinguishes_not_persisted_and_persisted_identity() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        let objective = "Recover exact failed run identity";
        let objective_fingerprint = format!(
            "sha256:{}",
            hex_sha256(
                [
                    b"brownie-cli-objective-fingerprint-v1\0".as_slice(),
                    objective.as_bytes()
                ]
                .concat()
                .as_slice()
            )
        );

        let missing_probe = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "headless.run.recovery_probe",
            "params": {
                "authorize_recovery_probe": true,
                "session_id": "cli.run.recover",
                "drive_id": "cli.run.recover.drive",
                "journey_id": "cli.run.recover.journey",
                "objective_fingerprint": objective_fingerprint
            }
        })
        .to_string();
        let missing = parse_line(&missing_probe)
            .result
            .expect("missing recovery probe result");
        assert_eq!(missing["admission_state"], "not_persisted");
        assert_eq!(
            missing["recovery_recommendation"],
            "retry_original_run_with_same_objective_allowed"
        );
        assert!(missing.get("task_id").is_none());
        assert!(missing.get("next_runtime_invocation").is_none());

        let admission_request = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "headless.run.drive",
            "params": {
                "authorize": true,
                "session_id": "cli.run.recover",
                "drive_id": "cli.run.recover.drive",
                "expected_start_session_sequence": 0,
                "max_advances": 1,
                "max_steps_per_advance": 1,
                "journey_admission": {
                    "journey_id": "cli.run.recover.journey",
                    "authorize_journey_start": true,
                    "task_start": {
                        "goal": objective,
                        "mode_id": "implementer"
                    }
                }
            }
        })
        .to_string();
        let admitted = parse_line(&admission_request)
            .result
            .expect("admission result");
        assert_eq!(admitted["status"], "task_executed");

        let persisted = parse_line(&missing_probe)
            .result
            .expect("persisted recovery probe result");
        assert_eq!(persisted["admission_state"], "persisted");
        assert!(persisted["task_id"].as_str().is_some());
        assert!(persisted["run_id"].as_str().is_some());
        assert_eq!(
            persisted["recovery_recommendation"],
            "continue_with_scoped_resume_after_persisted_identity_confirmation"
        );
        assert!(persisted.get("next_runtime_invocation").is_none());
        assert!(
            persisted
                .to_string()
                .contains("Recover exact failed run identity")
                == false
        );

        let conflicting_probe = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 3,
            "method": "headless.run.recovery_probe",
            "params": {
                "authorize_recovery_probe": true,
                "session_id": "cli.run.recover.other",
                "drive_id": "cli.run.recover.drive",
                "journey_id": "cli.run.recover.journey",
                "objective_fingerprint": objective_fingerprint
            }
        })
        .to_string();
        let conflict = parse_line(&conflicting_probe)
            .result
            .expect("conflicting recovery probe result");
        assert_eq!(conflict["admission_state"], "unknown");
        assert_eq!(
            conflict["recovery_recommendation"],
            "supervisor_reconcile_or_probe_runtime_state"
        );
        assert!(conflict.get("task_id").is_none());
        assert!(conflict.get("run_id").is_none());
        assert!(conflict.get("next_runtime_invocation").is_none());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_recovery_probe_reconciles_task_only_crash_window_idempotently() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        std::env::set_var(
            "BROWNIE_TEST_CRASH_AFTER_HEADLESS_TASK_PERSIST_BEFORE_JOURNEY_CHECKPOINT",
            "1",
        );
        let objective = "Recover admission after task-only crash window";
        let objective_fingerprint = format!(
            "sha256:{}",
            hex_sha256(
                [
                    b"brownie-cli-objective-fingerprint-v1\0".as_slice(),
                    objective.as_bytes()
                ]
                .concat()
                .as_slice()
            )
        );
        let admission_request = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "headless.run.drive",
            "params": {
                "authorize": true,
                "session_id": "cli.run.crash",
                "drive_id": "cli.run.crash.drive",
                "expected_start_session_sequence": 0,
                "max_advances": 1,
                "max_steps_per_advance": 1,
                "journey_admission": {
                    "journey_id": "cli.run.crash.journey",
                    "authorize_journey_start": true,
                    "task_start": {
                        "goal": objective,
                        "mode_id": "implementer"
                    }
                }
            }
        })
        .to_string();

        let crash = parse_line(&admission_request);
        assert!(crash.result.is_none());
        std::env::remove_var(
            "BROWNIE_TEST_CRASH_AFTER_HEADLESS_TASK_PERSIST_BEFORE_JOURNEY_CHECKPOINT",
        );

        let store = BrownieStore::new(temp.path());
        let tasks = store.tasks().list_tasks().expect("task-only crash state");
        assert_eq!(tasks.len(), 1);
        assert!(tasks[0].headless_run_recovery_identity.is_some());
        assert!(store
            .tasks()
            .read_headless_journey_start_checkpoint("cli.run.crash.journey")
            .expect("journey checkpoint lookup")
            .is_none());

        let probe_request = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "headless.run.recovery_probe",
            "params": {
                "authorize_recovery_probe": true,
                "session_id": "cli.run.crash",
                "drive_id": "cli.run.crash.drive",
                "journey_id": "cli.run.crash.journey",
                "objective_fingerprint": objective_fingerprint
            }
        })
        .to_string();
        let first_probe = parse_line(&probe_request)
            .result
            .expect("first recovery probe");
        assert_eq!(first_probe["admission_state"], "persisted");
        assert_ne!(first_probe["admission_state"], "not_persisted");
        assert_eq!(first_probe["task_id"], tasks[0].task_id);
        assert_eq!(first_probe["run_id"], tasks[0].run_id);
        assert!(first_probe.get("journey_fingerprint").is_none());
        assert!(
            first_probe
                .to_string()
                .contains("Recover admission after task-only crash window")
                == false
        );

        let second_probe = parse_line(&probe_request)
            .result
            .expect("second recovery probe");
        assert_eq!(second_probe, first_probe);

        let conflicting_probe = serde_json::json!({
            "jsonrpc": "2.0",
            "id": 3,
            "method": "headless.run.recovery_probe",
            "params": {
                "authorize_recovery_probe": true,
                "session_id": "cli.run.crash",
                "drive_id": "cli.run.crash.drive",
                "journey_id": "cli.run.crash.journey",
                "objective_fingerprint": format!("sha256:{}", "f".repeat(64))
            }
        })
        .to_string();
        let conflict = parse_line(&conflicting_probe)
            .result
            .expect("conflicting recovery probe");
        assert_eq!(conflict["admission_state"], "unknown");
        assert!(conflict.get("task_id").is_none());
        assert!(conflict.get("run_id").is_none());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_drive_journey_execution_recovers_committed_route_and_closure_checkpoints() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        fn test_sha(seed: char) -> String {
            format!("sha256:{}", seed.to_string().repeat(64))
        }

        fn write_route_drive(
            store: &BrownieStore,
            base: &HeadlessRunDriveResult,
            journey: &HeadlessJourneyStartCheckpoint,
            drive_id: &str,
            route_kind: HeadlessContinueRouteKind,
            start_sequence: u64,
            end_sequence: u64,
            source_fingerprint: &str,
            resume_fingerprint: &str,
        ) {
            let mut result = base.clone();
            result.drive_id = drive_id.to_string();
            result.start_session_sequence = start_sequence;
            result.end_session_sequence = end_sequence;
            result.replayed = false;
            result.drive_fingerprint = test_sha(char::from_digit(end_sequence as u32, 16).unwrap());
            result.journey = None;
            result.journey_execution = None;
            result.journey_closure = None;
            result.journey_route_resume = Some(HeadlessRunJourneyRouteResumeMetadata {
                journey_id: journey.journey_id.clone(),
                task_id: journey.task_id.clone(),
                run_id: journey.run_id.clone(),
                session_id: journey.session_id.clone(),
                drive_id: drive_id.to_string(),
                route_kind,
                source_continuation_id: format!("source.{end_sequence}"),
                source_decision_id: format!("decision.{end_sequence}"),
                source_checkpoint_fingerprint: source_fingerprint.to_string(),
                derived_target_class: "synthetic_test_target".to_string(),
                result_advance_id: Some(format!("advance.{end_sequence}")),
                result_continuation_id: Some(format!("continuation.{end_sequence}")),
                post_route_progress_fingerprint: Some(test_sha('b')),
                post_route_aggregate_sequence: Some(end_sequence),
                next_action: "continue_headless_journey".to_string(),
                replayed: false,
                resume_fingerprint: resume_fingerprint.to_string(),
            });
            store
                .tasks()
                .write_headless_run_session_drive_checkpoint(&HeadlessRunSessionDriveCheckpoint {
                    session_id: journey.session_id.clone(),
                    drive_id: drive_id.to_string(),
                    start_session_sequence: start_sequence,
                    result,
                })
                .expect("write route checkpoint");
        }

        let admission_request = r#"{"jsonrpc":"2.0","id":1,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m50.route.recover","drive_id":"m50.route.recover.drive.admit","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_admission":{"journey_id":"m50.route.recover.1","authorize_journey_start":true,"task_start":{"goal":"Recover committed route checkpoints","mode_id":"implementer"}}}}"#;
        let admission_response = parse_line(admission_request);
        let admission_value = admission_response
            .result
            .unwrap_or_else(|| panic!("admission result: {:?}", admission_response.error));
        let admission: HeadlessRunDriveResult =
            serde_json::from_value(admission_value).expect("admission drive result");
        let journey = store
            .tasks()
            .read_headless_journey_start_checkpoint("m50.route.recover.1")
            .expect("journey read")
            .expect("journey checkpoint");

        let fetch_resume = test_sha('f');
        let provenance_resume = test_sha('e');
        let approval_resume = test_sha('a');
        let replacement_resume = test_sha('c');
        write_route_drive(
            &store,
            &admission,
            &journey,
            "m50.route.recover.drive.fetch",
            HeadlessContinueRouteKind::FetchSelectedModePackCandidateExplicitly,
            1,
            2,
            &test_sha('1'),
            &fetch_resume,
        );
        write_route_drive(
            &store,
            &admission,
            &journey,
            "m50.route.recover.drive.provenance",
            HeadlessContinueRouteKind::VerifySelectedModePackCandidateProvenanceExplicitly,
            2,
            3,
            &fetch_resume,
            &provenance_resume,
        );
        write_route_drive(
            &store,
            &admission,
            &journey,
            "m50.route.recover.drive.approval",
            HeadlessContinueRouteKind::ApproveVerifiedModePackCandidateExplicitly,
            3,
            4,
            &provenance_resume,
            &approval_resume,
        );
        write_route_drive(
            &store,
            &admission,
            &journey,
            "m50.route.recover.drive.replacement",
            HeadlessContinueRouteKind::ReplaceActiveWithApprovedModePackCandidateExplicitly,
            4,
            5,
            &approval_resume,
            &replacement_resume,
        );

        let mut closure_result = admission.clone();
        closure_result.status = HeadlessContinueOnceStatus::NoEligibleTask;
        closure_result.drive_id = "m50.route.recover.drive.closure".to_string();
        closure_result.start_session_sequence = 5;
        closure_result.end_session_sequence = 5;
        closure_result.replayed = false;
        closure_result.drive_fingerprint = test_sha('d');
        closure_result.advance_count = 0;
        closure_result.executed_count = 0;
        closure_result.replayed_count = 0;
        closure_result.stop_reason = "journey_closure".to_string();
        closure_result.journey = None;
        closure_result.journey_execution = None;
        closure_result.journey_route_resume = None;
        closure_result.next_route = None;
        closure_result.advances.clear();
        closure_result.next_action = "complete_headless_journey".to_string();
        closure_result.journey_closure = Some(HeadlessRunJourneyClosureMetadata {
            journey_id: journey.journey_id.clone(),
            task_id: journey.task_id.clone(),
            run_id: journey.run_id.clone(),
            session_id: journey.session_id.clone(),
            drive_id: "m50.route.recover.drive.closure".to_string(),
            source_replacement_drive_id: "m50.route.recover.drive.replacement".to_string(),
            source_replacement_resume_fingerprint: replacement_resume.clone(),
            replacement_route_kind:
                HeadlessContinueRouteKind::ReplaceActiveWithApprovedModePackCandidateExplicitly,
            replacement_continuation_id: "replacement.continuation".to_string(),
            replacement_checkpoint_fingerprint: test_sha('9'),
            active_modepack_activation_fingerprint: test_sha('8'),
            closure_fingerprint: closure_result
                .completion_closure
                .closure_fingerprint
                .clone(),
            finalization_fingerprint: None,
            terminal_completion_fingerprint: None,
            progress_fingerprint: closure_result.start_progress.progress_fingerprint.clone(),
            aggregate_sequence: 5,
            next_action: "complete_headless_journey".to_string(),
            replayed: false,
            journey_closure_fingerprint: test_sha('7'),
        });
        store
            .tasks()
            .write_headless_run_session_drive_checkpoint(&HeadlessRunSessionDriveCheckpoint {
                session_id: journey.session_id.clone(),
                drive_id: "m50.route.recover.drive.closure".to_string(),
                start_session_sequence: 5,
                result: closure_result,
            })
            .expect("write closure checkpoint");

        assert!(store
            .tasks()
            .read_headless_journey_execution_checkpoint("m50.route.recover.1")
            .expect("execution checkpoint before recovery")
            .is_none());
        let execution_request = r#"{"jsonrpc":"2.0","id":2,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m50.route.recover","drive_id":"m50.route.recover.drive","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_execution":{"journey_id":"m50.route.recover.1","authorize_journey_execution":true,"task_start":{"goal":"Recover committed route checkpoints","mode_id":"implementer"}}}}"#;
        let execution_response = parse_line(execution_request);
        let execution = execution_response.result.unwrap_or_else(|| {
            panic!(
                "route and closure recovery result: {:?}",
                execution_response.error
            )
        });
        assert_eq!(execution["replayed"], true);
        assert_eq!(execution["journey_closure"]["replayed"], true);
        assert_eq!(execution["journey_execution"]["replayed"], true);
        assert_eq!(execution["journey_execution"]["complete"], true);
        let boundaries = execution["journey_execution"]["completed_boundaries"]
            .as_array()
            .expect("completed boundaries");
        assert_eq!(boundaries.len(), 6);
        assert_eq!(boundaries[0]["boundary"], "admit_journey");
        assert_eq!(boundaries[1]["boundary"], "fetch_selected_candidate");
        assert_eq!(boundaries[2]["boundary"], "verify_candidate_provenance");
        assert_eq!(boundaries[3]["boundary"], "approve_verified_candidate");
        assert_eq!(boundaries[4]["boundary"], "replace_active_modepack");
        assert_eq!(boundaries[5]["boundary"], "close_journey");
        assert_eq!(boundaries[4]["resume_fingerprint"], replacement_resume);
        assert_eq!(
            store
                .tasks()
                .get_task(&journey.task_id)
                .expect("task lookup")
                .expect("task")
                .status,
            TaskStatus::Completed
        );
        let events = store
            .tasks()
            .read_ledger_events(&journey.run_id)
            .expect("events");
        assert_eq!(
            events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessJourneyExecuted)
                .count(),
            1
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_drive_journey_denial_fails_before_task_creation() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let response = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m50.bad","drive_id":"m50.bad.drive","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_admission":{"journey_id":"m50.bad.1","authorize_journey_start":false,"task_start":{"goal":"Should not start","mode_id":"orchestrator"}}}}"#,
        );
        assert!(response.result.is_none());
        assert!(response
            .error
            .expect("error")
            .message
            .contains("authorize_journey_start must be true"));
        assert!(store.tasks().list_tasks().expect("tasks").is_empty());
        assert!(store
            .tasks()
            .read_headless_journey_start_checkpoint("m50.bad.1")
            .expect("journey checkpoint")
            .is_none());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_drive_journey_checkpoint_failure_rolls_back_started_task() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let store = BrownieStore::new(temp.path());
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        std::env::set_var("BROWNIE_TEST_FAIL_HEADLESS_JOURNEY_CHECKPOINT_WRITE", "1");

        let request = r#"{"jsonrpc":"2.0","id":1,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m55.atomic.checkpoint","drive_id":"m55.atomic.checkpoint.drive","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_admission":{"journey_id":"m55.atomic.checkpoint","authorize_journey_start":true,"task_start":{"goal":"Rollback checkpoint failure","mode_id":"implementer"}}}}"#;
        let response = parse_line(request);
        assert!(response.result.is_none());
        assert!(response
            .error
            .expect("checkpoint failure")
            .message
            .contains("simulated journey admission checkpoint commit failure"));
        assert!(store.tasks().list_tasks().expect("tasks").is_empty());
        assert!(store
            .tasks()
            .read_headless_journey_start_checkpoint("m55.atomic.checkpoint")
            .expect("checkpoint read")
            .is_none());

        std::env::remove_var("BROWNIE_TEST_FAIL_HEADLESS_JOURNEY_CHECKPOINT_WRITE");
        let retry = parse_line(request);
        assert!(retry.error.is_none(), "{:?}", retry.error);
        assert_eq!(store.tasks().list_tasks().expect("tasks").len(), 1);
        assert!(store
            .tasks()
            .read_headless_journey_start_checkpoint("m55.atomic.checkpoint")
            .expect("checkpoint read")
            .is_some());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

