        use ed25519_dalek::{Signer, SigningKey};
        let signing_key = SigningKey::from_bytes(&[7u8; 32]);
        let public_key_bytes = signing_key.verifying_key().to_bytes();
        let signer_fingerprint = format!("sha256:{}", hex_sha256(&public_key_bytes));
