    #[test]
    fn agentmodes_new_task_alias_uses_active_handoff_admission() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        write_test_handoff_selector_modepack(temp.path());
        let store = BrownieStore::new(temp.path());
        commit_trusted_workspace_modepack_snapshot(&store);
        let parent = store
            .tasks()
            .start_task(brownie_protocol::TaskStartParams {
                goal: "Parent orchestration".into(),
                mode_id: Some("external-orchestrator".into()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
                product_continuation_source: None,
            })
            .expect("start parent");
        let policy = resolve_workspace_mode_policy(&store, "external-orchestrator")
            .expect("resolve external policy")
            .expect("external policy");

        let allowed = "new_task(\"reviewer-lite\", \"Review SECRET_ALIAS_PACKET and return bounded findings.\")";
        append_tool_intent_events(&store, &parent, &policy, allowed)
            .expect("append allowed alias intent");
        handle_approved_workspace_intents(&store, &parent, &policy, allowed)
            .expect("handle allowed alias intent");

        let denied_self =
            "new_task(mode: external-orchestrator, message: 'Do not recurse into self.')";
        append_tool_intent_events(&store, &parent, &policy, denied_self)
            .expect("append denied self alias intent");
        handle_approved_workspace_intents(&store, &parent, &policy, denied_self)
            .expect("handle denied self alias intent");

        let reviewer = store
            .tasks()
            .start_task(brownie_protocol::TaskStartParams {
                goal: "Reviewer should not dispatch".into(),
                mode_id: Some("reviewer-lite".into()),
                verification_recovery_source: None,
                patch_apply_recovery_source: None,
                verification_recovery_retry_source: None,
                llm_provider_failure_retry_source: None,
                product_continuation_source: None,
            })
            .expect("start reviewer");
        let reviewer_policy = resolve_workspace_mode_policy(&store, "reviewer-lite")
            .expect("resolve reviewer policy")
            .expect("reviewer policy");
        let reviewer_attempt =
            "new_task(\"external-orchestrator\", \"Try to dispatch without permission.\")";
        append_tool_intent_events(&store, &reviewer, &reviewer_policy, reviewer_attempt)
            .expect("append reviewer alias intent");
        handle_approved_workspace_intents(&store, &reviewer, &reviewer_policy, reviewer_attempt)
            .expect("handle reviewer alias intent");

        let parent_events = store
            .tasks()
            .read_ledger_events(&parent.run_id)
            .expect("parent events");
        let queued = parent_events
            .iter()
            .find(|event| event.kind == LedgerEventKind::SubtaskOrchestrationQueued)
            .and_then(|event| event.payload.as_ref())
            .expect("queued payload");
        assert_eq!(queued["tool_id"], "subtask.spawn");
        assert_eq!(queued["requested_mode_id"], "reviewer-lite");
        assert_eq!(
            queued["requested_goal_preview"],
            "Review SECRET_ALIAS_PACKET and return bounded findings."
        );
        assert!(queued.get("input").is_none());
        assert!(parent_events.iter().any(|event| {
            event.kind == LedgerEventKind::ToolIntentDenied
                && event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("requested_mode_id"))
                    .and_then(Value::as_str)
                    == Some("external-orchestrator")
        }));
        let parent_ledger = std::fs::read_to_string(
            temp.path()
                .join(".brownie/runs")
                .join(&parent.run_id)
                .join("ledger.jsonl"),
        )
        .expect("parent ledger");
        assert!(!parent_ledger.contains("new_task("));

        let reviewer_events = store
            .tasks()
            .read_ledger_events(&reviewer.run_id)
            .expect("reviewer events");
        assert!(reviewer_events.iter().any(|event| {
            event.kind == LedgerEventKind::ToolIntentDenied
                && event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("tool_id"))
                    .and_then(Value::as_str)
                    == Some("subtask.spawn")
        }));
        assert!(!reviewer_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::SubtaskOrchestrationQueued));

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn current_agentmodes_pack_activates_with_repository_local_trust_narrowing() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        let Some(fixture) = write_current_agentmodes_modepack_if_available(temp.path()) else {
            return;
        };
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let activated = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"modepack.activate","params":{"authorize":true}}"#,
        );
        assert!(activated.error.is_none());
        let snapshot = &activated.result.expect("activation result")["snapshot"];
        assert_eq!(snapshot["modepack_name"], "current-agentmodes");
        assert_eq!(
            snapshot["mode_count"].as_u64().unwrap_or_default(),
            fixture.mode_count as u64
        );
        let active = BrownieStore::new(temp.path())
            .read_active_modepack_snapshot()
            .expect("active snapshot")
            .expect("active snapshot");
        assert_eq!(
            json_policy_artifact_category_count(&active.global_policy_artifacts, "rule"),
            fixture.rule_count
        );
        assert_eq!(
            json_policy_artifact_category_count(&active.global_policy_artifacts, "skill"),
            fixture.skill_count
        );
        assert_eq!(
            json_policy_artifact_category_count(&active.global_policy_artifacts, "command"),
            fixture.command_count
        );
        assert_eq!(
            json_policy_artifact_category_count(&active.global_policy_artifacts, "contract"),
            fixture.contract_count
        );

        let run = parse_line(
            r#"{"jsonrpc":"2.0","id":2,"method":"task.start","params":{"goal":"exercise current AgentModes selector policy","mode_id":"orchestrator"}}"#,
        );
        assert!(run.error.is_none());
        let task_id = run.result.expect("task start result")["task_id"]
            .as_str()
            .expect("task id")
            .to_string();
        let store = BrownieStore::new(temp.path());
        let task = store
            .tasks()
            .get_task(&task_id)
            .expect("get task")
            .expect("task");
        let events = store
            .tasks()
            .read_ledger_events(&task.run_id)
            .expect("task events");
        let mode_resolved = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::ModeResolved)
            .and_then(|event| event.payload.as_ref())
            .expect("mode resolved payload");
        assert_eq!(mode_resolved["mode_id"], "orchestrator");
        assert_eq!(mode_resolved["allowed_handoff_targets"], Value::Null);
        assert!(mode_resolved["prompt_sections"]
            .as_array()
            .is_some_and(|sections| !sections.is_empty()));
        let artifacts = mode_resolved["external_modepack_task_provenance"]
            ["global_policy_artifacts"]
            .as_array()
            .expect("task-pinned artifact catalog");
        assert!(artifacts
            .iter()
            .any(|artifact| artifact["category"] == "skill"
                && artifact["relative_path"] == "skills/tdd-quality-gate/SKILL.md"
                && artifact["content_fingerprint"]
                    .as_str()
                    .is_some_and(|value| value.starts_with("sha256:"))));
        assert!(artifacts
            .iter()
            .any(|artifact| artifact["category"] == "contract"
                && artifact["relative_path"] == "docs/contracts/task-packet-v1.md"));

        let composer_policy = resolve_workspace_mode_policy(&store, "user-response-composer")
            .expect("resolve composer")
            .expect("composer policy");
        assert!(
            !RuntimePermissionGate::check(&composer_policy, RuntimeAction::SpawnSubtask).allowed
        );
        assert_eq!(composer_policy.allowed_handoff_targets, None);
        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn current_agentmodes_orchestrator_reaches_provider_request_with_omitted_budget() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        clear_llm_env_for_test();
        let temp = tempfile::tempdir().expect("tempdir");
        let Some(fixture) = write_current_agentmodes_modepack_if_available(temp.path()) else {
            return;
        };
        let store = BrownieStore::new(temp.path());
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let activated = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"modepack.activate","params":{"authorize":true}}"#,
        )
        .result
        .expect("activation result");
        assert_eq!(activated["snapshot"]["modepack_name"], "current-agentmodes");
        assert_eq!(
            activated["snapshot"]["mode_count"]
                .as_u64()
                .unwrap_or_default(),
            fixture.mode_count as u64
        );
        let activation_fingerprint = activated["snapshot"]["activation_fingerprint"]
            .as_str()
            .expect("activation fingerprint")
            .to_string();
        std::fs::remove_file(temp.path().join(".brownie/modepack.json"))
            .expect("remove live modepack");

        let result = parse_line(
            r#"{"jsonrpc":"2.0","id":2,"method":"headless.run.drive","params":{"authorize":true,"session_id":"mp32c.agentmodes.prompt","drive_id":"mp32c.agentmodes.prompt.drive","expected_start_session_sequence":0,"max_advances":1,"max_steps_per_advance":1,"journey_admission":{"journey_id":"mp32c.agentmodes.prompt.journey","authorize_journey_start":true,"task_start":{"goal":"Exercise real AgentModes orchestrator prompt budget integration"}}}}"#,
        )
        .result
        .expect("AgentModes prompt journey result");

        assert_eq!(result["status"], "task_executed");
        let task_id = result["journey"]["task_id"].as_str().expect("task id");
        let run_id = result["journey"]["run_id"].as_str().expect("run id");
        let task = store
            .tasks()
            .get_task(task_id)
            .expect("get task")
            .expect("task");
        assert_eq!(task.mode_id.as_deref(), Some("orchestrator"));
        assert!(result["advances"][0]["steps"][0]
            .get("context_budget")
            .is_none());

        let events = store.tasks().read_ledger_events(run_id).expect("events");
        let mode_payload = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::ModeResolved)
            .and_then(|event| event.payload.as_ref())
            .expect("mode resolved payload");
        assert_eq!(mode_payload["mode_id"], "orchestrator");
        assert_eq!(
            mode_payload["external_modepack_task_provenance"]["activation_fingerprint"],
            activation_fingerprint
        );
        assert!(mode_payload["prompt_sections"]
            .as_array()
            .is_some_and(|sections| !sections.is_empty()));
        assert_eq!(mode_payload["allowed_handoff_targets"], Value::Null);
        let artifacts = mode_payload["external_modepack_task_provenance"]
            ["global_policy_artifacts"]
            .as_array()
            .expect("task-pinned artifact catalog");
        assert_eq!(
            artifacts
                .iter()
                .filter(|artifact| artifact["category"] == "rule")
                .count(),
            fixture.rule_count
        );
        assert_eq!(
            artifacts
                .iter()
                .filter(|artifact| artifact["category"] == "skill")
                .count(),
            fixture.skill_count
        );
        assert!(artifacts
            .iter()
            .any(|artifact| artifact["category"] == "command"
                && artifact["relative_path"] == "commands/tdd-quality-gate.md"));

        let prompt_payload = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::PromptBuilt)
            .and_then(|event| event.payload.as_ref())
            .expect("prompt built payload");
        assert_eq!(prompt_payload["max_prompt_chars"], 120000);
        assert!(prompt_payload.get("context_budget_requested").is_none());
        assert!(events
            .iter()
            .any(|event| event.kind == LedgerEventKind::LlmRequestCreated));

        let ledger_json = serde_json::to_string(&events).expect("ledger json");
        assert!(!ledger_json.contains(fixture.source_root.to_string_lossy().as_ref()));
        assert!(!ledger_json.contains("raw_modepack_json"));
        assert!(!ledger_json.contains("raw_prompt"));
        assert!(!ledger_json.contains("provider_response"));
        assert!(!ledger_json.contains("BROWNIE_LLM"));

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
        clear_llm_env_for_test();
    }

