    #[test]
    fn task_run_completed_task_replays_completion_evidence_without_duplicate_events() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Run once","mode_id":"implementer"}}"#,
        );
        let task_id = start.result.expect("start result")["task_id"]
            .as_str()
            .expect("task id")
            .to_string();
        let first = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":2,"method":"task.run","params":{{"task_id":"{task_id}"}}}}"#
        ));
        assert!(first.error.is_none());
        let first_result = first.result.expect("first result");
        let first_evidence = first_result["completion_evidence"].clone();
        let run_id = first_result["run_id"].as_str().expect("run id").to_string();
        let before_events = std::fs::read_to_string(
            temp.path()
                .join(".brownie/runs")
                .join(&run_id)
                .join("ledger.jsonl"),
        )
        .expect("ledger before");

        let second = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"task.run","params":{{"task_id":"{task_id}"}}}}"#
        ));
        assert!(second.error.is_none());
        let second_result = second.result.expect("second result");
        let second_evidence = &second_result["completion_evidence"];
        assert_eq!(
            second_evidence["completion_result_fingerprint"],
            first_evidence["completion_result_fingerprint"]
        );
        assert_eq!(second_evidence["replayed"], true);
        assert_eq!(second_evidence["final_state"], "Completed");
        let after_events = std::fs::read_to_string(
            temp.path()
                .join(".brownie/runs")
                .join(&run_id)
                .join("ledger.jsonl"),
        )
        .expect("ledger after");
        assert_eq!(after_events, before_events);

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn task_run_completed_task_accepts_completion_once_with_bounded_evidence() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Accept completion","mode_id":"implementer"}}"#,
        );
        let task_id = start.result.expect("start result")["task_id"]
            .as_str()
            .expect("task id")
            .to_string();
        let first = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 2,
                "method": "task.run",
                "params": { "task_id": task_id },
            })
            .to_string(),
        );
        assert!(first.error.is_none());
        let first_result = first.result.expect("first result");
        let run_id = first_result["run_id"].as_str().expect("run id").to_string();
        let terminal_fingerprint = first_result["completion_evidence"]
            ["completion_result_fingerprint"]
            .as_str()
            .expect("completion fingerprint")
            .to_string();
        let store = BrownieStore::new(temp.path());
        let before_events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events before acceptance");

        let acceptance_request = json!({
            "jsonrpc": "2.0",
            "id": 3,
            "method": "task.run",
            "params": {
                "task_id": task_id,
                "completion_acceptance": {
                    "authorize_completion_acceptance": true,
                    "source_run_id": run_id,
                    "acceptance_id": "accept-m51-1",
                    "expected_completion_result_fingerprint": terminal_fingerprint,
                }
            }
        });
        let accepted = parse_line(&acceptance_request.to_string());
        assert!(accepted.error.is_none());
        let accepted_result = accepted.result.expect("accepted result");
        let acceptance = accepted_result["completion_acceptance"]
            .as_object()
            .expect("completion acceptance");
        assert_eq!(acceptance["acceptance_id"], "accept-m51-1");
        assert_eq!(acceptance["status"], "AcceptedComplete");
        assert_eq!(
            acceptance["terminal_completion_fingerprint"],
            terminal_fingerprint
        );
        assert_eq!(acceptance["verifier_gate_status"], "NotRequired");
        assert_eq!(acceptance["replayed"], false);
        assert_eq!(acceptance["next_action"], "inspect_accepted_completion");
        assert!(acceptance["acceptance_fingerprint"]
            .as_str()
            .expect("acceptance fingerprint")
            .starts_with("sha256:"));

        let after_events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events after acceptance");
        assert_eq!(
            after_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskCompletionAccepted)
                .count(),
            before_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskCompletionAccepted)
                .count()
                + 1
        );
        let accepted_event_payload = after_events
            .iter()
            .rev()
            .find(|event| event.kind == LedgerEventKind::TaskCompletionAccepted)
            .and_then(|event| event.payload.as_ref())
            .expect("accepted event payload");
        let serialized_acceptance = serde_json::to_string(accepted_event_payload).unwrap();
        let serialized_result =
            serde_json::to_string(&accepted_result["completion_acceptance"]).unwrap();
        for forbidden in [
            "raw_prompt",
            "provider_response",
            "final_response",
            "file_content",
            "stdout",
            "stderr",
            "command",
            "environment",
            "raw_request",
            "raw_ledger_payload",
            "absolute_path",
            "canonical_path",
            "diagnostics",
        ] {
            assert!(!serialized_acceptance.contains(&format!(r#"\"{forbidden}\""#)));
            assert!(!serialized_result.contains(&format!(r#"\"{forbidden}\""#)));
        }

        let replayed = parse_line(&acceptance_request.to_string());
        assert!(replayed.error.is_none());
        let replayed_result = replayed.result.expect("replayed result");
        assert_eq!(
            replayed_result["completion_acceptance"]["acceptance_fingerprint"],
            accepted_result["completion_acceptance"]["acceptance_fingerprint"]
        );
        assert_eq!(replayed_result["completion_acceptance"]["replayed"], true);
        let after_replay_events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events after replay");
        assert_eq!(after_replay_events.len(), after_events.len());
        assert_eq!(
            after_replay_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            after_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count()
        );

        let second_acceptance_id_request = json!({
            "jsonrpc": "2.0",
            "id": 4,
            "method": "task.run",
            "params": {
                "task_id": task_id,
                "completion_acceptance": {
                    "authorize_completion_acceptance": true,
                    "source_run_id": run_id,
                    "acceptance_id": "accept-m51-1b",
                    "expected_completion_result_fingerprint": terminal_fingerprint,
                }
            }
        });
        let replayed_from_terminal_key = parse_line(&second_acceptance_id_request.to_string());
        assert!(replayed_from_terminal_key.error.is_none());
        let replayed_from_terminal_key_result = replayed_from_terminal_key
            .result
            .expect("terminal-key replay result");
        assert_eq!(
            replayed_from_terminal_key_result["completion_acceptance"]["acceptance_id"],
            "accept-m51-1"
        );
        assert_eq!(
            replayed_from_terminal_key_result["completion_acceptance"]["acceptance_fingerprint"],
            accepted_result["completion_acceptance"]["acceptance_fingerprint"]
        );
        assert_eq!(
            replayed_from_terminal_key_result["completion_acceptance"]["replayed"],
            true
        );
        let after_second_acceptance_id_events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events after terminal-key replay");
        assert_eq!(
            after_second_acceptance_id_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskCompletionAccepted)
                .count(),
            after_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskCompletionAccepted)
                .count()
        );
        assert_eq!(after_second_acceptance_id_events.len(), after_events.len());

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_drive_routes_accepted_completion_without_duplicate_mutation() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Accepted headless completion","mode_id":"implementer"}}"#,
        );
        let task_id = start.result.expect("start result")["task_id"]
            .as_str()
            .expect("task id")
            .to_string();
        let progress = parse_line(r#"{"jsonrpc":"2.0","id":2,"method":"task.list"}"#)
            .result
            .expect("progress result")["progress_overview"]
            .clone();
        let seed = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"headless.run.advance","params":{{"authorize":true,"session_id":"m51.accepted","advance_id":"m51.accepted.seed","expected_session_sequence":1,"expected_progress_fingerprint":"{}","expected_aggregate_sequence":{},"max_steps":1}}}}"#,
            progress["source_fingerprint"]
                .as_str()
                .expect("fingerprint"),
            progress["aggregate_sequence"].as_u64().expect("sequence"),
        ));
        assert!(seed.error.is_none());
        let seed_result = seed.result.expect("seed result");
        let run_id = seed_result["steps"][0]["selected_run_id"]
            .as_str()
            .expect("selected run id")
            .to_string();
        let terminal_fingerprint = seed_result["terminal_completion_evidence"]
            ["completion_result_fingerprint"]
            .as_str()
            .expect("terminal fingerprint")
            .to_string();
        let store = BrownieStore::new(temp.path());

        let accepted = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 4,
                "method": "task.run",
                "params": {
                    "task_id": task_id,
                    "completion_acceptance": {
                        "authorize_completion_acceptance": true,
                        "source_run_id": run_id,
                        "acceptance_id": "m51-accepted-route",
                        "expected_completion_result_fingerprint": terminal_fingerprint,
                    }
                }
            })
            .to_string(),
        );
        assert!(accepted.error.is_none());
        let before_drive_events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events before drive");

        let drive_request = r#"{"jsonrpc":"2.0","id":5,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m51.accepted","drive_id":"m51.accepted.route","expected_start_session_sequence":1,"max_advances":1,"max_steps_per_advance":1}}"#;
        let drive = parse_line(drive_request);
        assert!(drive.error.is_none());
        let drive_result = drive.result.expect("drive result");
        let accepted_completion = drive_result["accepted_completion"]
            .as_object()
            .expect("accepted completion route");
        assert_eq!(accepted_completion["task_id"], task_id);
        assert_eq!(accepted_completion["run_id"], run_id);
        assert_eq!(accepted_completion["acceptance_id"], "m51-accepted-route");
        assert_eq!(accepted_completion["status"], "AcceptedComplete");
        assert_eq!(
            accepted_completion["terminal_completion_fingerprint"],
            terminal_fingerprint
        );
        assert_eq!(accepted_completion["replayed"], true);
        assert_eq!(accepted_completion["next_action"], "close_headless_run");
        assert_eq!(
            drive_result["completion_closure"]["terminal_completion_fingerprint"],
            terminal_fingerprint
        );
        let serialized = serde_json::to_string(&drive_result).expect("serialize drive");
        for forbidden in [
            "raw_prompt",
            "provider_response",
            "final_response",
            "file_content",
            "stdout",
            "stderr",
            "command",
            "environment",
            "raw_request",
            "raw_ledger_payload",
            "absolute_path",
            "canonical_path",
            "diagnostics",
        ] {
            assert!(!serialized.contains(&format!(r#"\"{forbidden}\""#)));
        }

        let replay = parse_line(drive_request);
        assert!(replay.error.is_none());
        let replay_result = replay.result.expect("replay result");
        assert_eq!(replay_result["replayed"], true);
        assert_eq!(
            replay_result["accepted_completion"],
            drive_result["accepted_completion"]
        );
        assert_eq!(
            replay_result["drive_fingerprint"],
            drive_result["drive_fingerprint"]
        );
        let after_replay_events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events after replay");
        assert_eq!(
            after_replay_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskCompletionAccepted)
                .count(),
            before_drive_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskCompletionAccepted)
                .count()
        );
        assert_eq!(
            after_replay_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            before_drive_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count()
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_drive_records_product_completion_decision_and_replays() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());

        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Runtime product decision","mode_id":"implementer"}}"#,
        );
        let task_id = start.result.expect("start result")["task_id"]
            .as_str()
            .expect("task id")
            .to_string();
        let progress = parse_line(r#"{"jsonrpc":"2.0","id":2,"method":"task.list"}"#)
            .result
            .expect("progress result")["progress_overview"]
            .clone();
        let seed = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":3,"method":"headless.run.advance","params":{{"authorize":true,"session_id":"m51.product","advance_id":"m51.product.seed","expected_session_sequence":1,"expected_progress_fingerprint":"{}","expected_aggregate_sequence":{},"max_steps":1}}}}"#,
            progress["source_fingerprint"]
                .as_str()
                .expect("fingerprint"),
            progress["aggregate_sequence"].as_u64().expect("sequence"),
        ));
        assert!(seed.error.is_none());
        let seed_result = seed.result.expect("seed result");
        let run_id = seed_result["steps"][0]["selected_run_id"]
            .as_str()
            .expect("selected run id")
            .to_string();
        let terminal_fingerprint = seed_result["terminal_completion_evidence"]
            ["completion_result_fingerprint"]
            .as_str()
            .expect("terminal fingerprint")
            .to_string();
        let store = BrownieStore::new(temp.path());

        let accepted = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 4,
                "method": "task.run",
                "params": {
                    "task_id": task_id,
                    "completion_acceptance": {
                        "authorize_completion_acceptance": true,
                        "source_run_id": run_id,
                        "acceptance_id": "m51-product-accepted",
                        "expected_completion_result_fingerprint": terminal_fingerprint,
                    }
                }
            })
            .to_string(),
        );
        assert!(accepted.error.is_none());
        let acceptance_fingerprint = accepted.result.expect("accepted result")
            ["completion_acceptance"]["acceptance_fingerprint"]
            .as_str()
            .expect("acceptance fingerprint")
            .to_string();

        let drive_request = r#"{"jsonrpc":"2.0","id":5,"method":"headless.run.drive","params":{"authorize":true,"session_id":"m51.product","drive_id":"m51.product.route","expected_start_session_sequence":1,"max_advances":2,"max_steps_per_advance":1}}"#;
        let drive = parse_line(drive_request);
        assert!(drive.error.is_none());
        let drive_result = drive.result.expect("drive result");
        let closure_fingerprint = drive_result["completion_closure"]["closure_fingerprint"]
            .as_str()
            .expect("closure fingerprint")
            .to_string();
        assert!(drive_result.get("product_completion_decision").is_none());

        let mut product_decision = HeadlessRunProductCompletionDecisionRequest {
            authorize_product_completion_decision: true,
            decision_id: "m51-product-decision".to_string(),
            expected_accepted_completion_fingerprint: acceptance_fingerprint.clone(),
            expected_terminal_completion_fingerprint: terminal_fingerprint.clone(),
            expected_completion_closure_fingerprint: closure_fingerprint.clone(),
            expected_product_evidence_fingerprint: format!("sha256:{}", "0".repeat(64)),
            evidence_status: "continue_development".to_string(),
            target_capability: "headless_autonomous_development".to_string(),
            concrete_capability_transition: "runtime_owned_product_completion_stop_decision"
                .to_string(),
            validated_gate_categories: vec![
                "strategic_capability_mapping".to_string(),
                "concrete_capability_transition".to_string(),
                "behavior_evidence".to_string(),
                "safety_boundary".to_string(),
                "non_goals".to_string(),
                "rejected_alternatives".to_string(),
                "technical_debt".to_string(),
                "next_capability_or_milestone_exit".to_string(),
            ],
            derived_product_evidence_matrix_fingerprint: None,
            behavior_evidence_count: 3,
            rejected_alternatives_count: 2,
            safety_boundary_reviewed: true,
            non_goals_reviewed: true,
            technical_debt_reviewed: true,
            remaining_capability: Some("milestone_closeout".to_string()),
            milestone_exit_rationale: None,
            technical_debt_carry_forward: Some(vec![TechnicalDebtCarryForwardItem {
                debt_id: "m54-debt-1".to_string(),
                summary: "carry forward bounded runtime debt".to_string(),
                source_milestone: "M53 Product Continuation".to_string(),
                source_phase: "M53.2".to_string(),
                source_pr: Some("PR248".to_string()),
                target_capability: "headless_autonomous_development".to_string(),
                classification: "post_v0".to_string(),
                status: "open".to_string(),
                next_action: "admit_next_phase_with_debt_context".to_string(),
                closure_evidence_fingerprint: None,
            }]),
            technical_debt_transitions: None,
        };
        let product_evidence_fingerprint =
            headless_product_completion_evidence_fingerprint(&product_decision);
        product_decision.expected_product_evidence_fingerprint =
            product_evidence_fingerprint.clone();
        let decision_request = json!({
            "jsonrpc": "2.0",
            "id": 6,
            "method": "headless.run.drive",
            "params": {
                "authorize": true,
                "session_id": "m51.product",
                "drive_id": "m51.product.route",
                "expected_start_session_sequence": 1,
                "max_advances": 2,
                "max_steps_per_advance": 1,
                "expected_completion_closure_fingerprint": closure_fingerprint,
                "product_completion_decision": product_decision
            }
        });
        let mut stale_product_evidence_request = decision_request.clone();
        stale_product_evidence_request["params"]["product_completion_decision"]
            ["expected_product_evidence_fingerprint"] = json!(format!("sha256:{}", "f".repeat(64)));
        let stale_product_evidence = parse_line(&stale_product_evidence_request.to_string());
        assert!(stale_product_evidence.result.is_none());
        assert!(stale_product_evidence
            .error
            .expect("stale product evidence error")
            .message
            .contains("product-evidence fingerprint mismatch"));

        let decided = parse_line(&decision_request.to_string());
        assert!(decided.error.is_none(), "{:?}", decided.error);
        let decided_result = decided.result.expect("decided result");
        let decision = decided_result["product_completion_decision"]
            .as_object()
            .expect("product decision");
        assert_eq!(decision["status"], "continue_development");
        assert_eq!(decision["next_action"], "plan_next_phase");
        assert_eq!(
            decision["accepted_completion_fingerprint"],
            acceptance_fingerprint
        );
        assert_eq!(
            decision["terminal_completion_fingerprint"],
            terminal_fingerprint
        );
        assert_eq!(
            decision["completion_closure_fingerprint"],
            closure_fingerprint
        );
        assert_eq!(
            decision["product_evidence_fingerprint"],
            product_evidence_fingerprint
        );
        assert_eq!(
            decision["technical_debt_carry_forward"]["items"][0]["debt_id"],
            "m54-debt-1"
        );
        assert!(decision["technical_debt_carry_forward"]["fingerprint"]
            .as_str()
            .expect("carry-forward fingerprint")
            .starts_with("sha256:"));
        assert_eq!(decision["replayed"], false);
        let serialized = serde_json::to_string(&decided_result).expect("serialize decision");
        for forbidden in [
            "raw_prompt",
            "provider_response",
            "final_response",
            "file_content",
            "stdout",
            "stderr",
            "command",
            "environment",
            "raw_request",
            "raw_ledger_payload",
            "absolute_path",
            "canonical_path",
            "diagnostics",
        ] {
            assert!(!serialized.contains(&format!(r#"\"{forbidden}\""#)));
        }

        let replay = parse_line(&decision_request.to_string());
        assert!(replay.error.is_none());
        let replay_result = replay.result.expect("replay result");
        assert_eq!(
            replay_result["product_completion_decision"]["replayed"],
            true
        );
        assert_eq!(
            replay_result["product_completion_decision"]["decision_fingerprint"],
            decided_result["product_completion_decision"]["decision_fingerprint"]
        );
        let mut conflicting_debt_request = decision_request.clone();
        conflicting_debt_request["params"]["product_completion_decision"]
            ["technical_debt_carry_forward"][0]["next_action"] =
            json!("admit_next_phase_with_different_debt_context");
        let conflicting_debt = parse_line(&conflicting_debt_request.to_string());
        assert!(conflicting_debt.result.is_none());
        assert!(conflicting_debt.error.is_some());
        let events = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events after decision replay");
        assert_eq!(
            events
                .iter()
                .filter(|event| {
                    event.kind == LedgerEventKind::HeadlessRunProductCompletionDecisionRecorded
                })
                .count(),
            1
        );

        let mut conflicting_product_decision = HeadlessRunProductCompletionDecisionRequest {
            authorize_product_completion_decision: true,
            decision_id: "m51-product-decision-conflict".to_string(),
            expected_accepted_completion_fingerprint: acceptance_fingerprint.clone(),
            expected_terminal_completion_fingerprint: terminal_fingerprint.clone(),
            expected_completion_closure_fingerprint: closure_fingerprint.clone(),
            expected_product_evidence_fingerprint: format!("sha256:{}", "0".repeat(64)),
            evidence_status: "product_complete".to_string(),
            target_capability: "headless_autonomous_development".to_string(),
            concrete_capability_transition: "runtime_owned_product_completion_stop_decision"
                .to_string(),
            validated_gate_categories: vec![
                "strategic_capability_mapping".to_string(),
                "concrete_capability_transition".to_string(),
                "behavior_evidence".to_string(),
                "safety_boundary".to_string(),
                "non_goals".to_string(),
                "rejected_alternatives".to_string(),
                "technical_debt".to_string(),
                "next_capability_or_milestone_exit".to_string(),
            ],
            derived_product_evidence_matrix_fingerprint: None,
            behavior_evidence_count: 4,
            rejected_alternatives_count: 3,
            safety_boundary_reviewed: true,
            non_goals_reviewed: true,
            technical_debt_reviewed: true,
            remaining_capability: None,
            milestone_exit_rationale: Some("m51_complete".to_string()),
            technical_debt_carry_forward: Some(vec![TechnicalDebtCarryForwardItem {
                debt_id: "m54-post-v0-debt".to_string(),
                summary: "post v0 debt remains visible after completion".to_string(),
                source_milestone: "M54 Runtime Debt".to_string(),
                source_phase: "M54.2".to_string(),
                source_pr: None,
                target_capability: "headless_autonomous_development".to_string(),
                classification: "post_v0".to_string(),
                status: "open".to_string(),
                next_action: "track_after_v0".to_string(),
                closure_evidence_fingerprint: None,
            }]),
            technical_debt_transitions: None,
        };
        conflicting_product_decision.expected_product_evidence_fingerprint =
            headless_product_completion_evidence_fingerprint(&conflicting_product_decision);
        let conflicting_decision_request = json!({
            "jsonrpc": "2.0",
            "id": 7,
            "method": "headless.run.drive",
            "params": {
                "authorize": true,
                "session_id": "m51.product",
                "drive_id": "m51.product.route",
                "expected_start_session_sequence": 1,
                "max_advances": 2,
                "max_steps_per_advance": 1,
                "expected_completion_closure_fingerprint": closure_fingerprint,
                "product_completion_decision": conflicting_product_decision
            }
        });
        let conflicting_decision = parse_line(&conflicting_decision_request.to_string());
        assert!(conflicting_decision.result.is_none());
        assert!(conflicting_decision
            .error
            .expect("conflicting product decision error")
            .message
            .contains("conflicts with persisted accepted-completion boundary decision"));
        let events_after_conflict = store
            .tasks()
            .read_ledger_events(&run_id)
            .expect("events after conflicting decision");
        assert_eq!(
            events_after_conflict
                .iter()
                .filter(|event| {
                    event.kind == LedgerEventKind::HeadlessRunProductCompletionDecisionRecorded
                })
                .count(),
            1
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

