    #[test]
    fn task_start_admits_product_continuation_and_replays_without_running() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        let store = BrownieStore::new(temp.path());

        fn fp(hex: char) -> String {
            format!("sha256:{}", hex.to_string().repeat(64))
        }

        fn create_source_decision(
            store: &BrownieStore,
            goal: &str,
            decision_id: &str,
            status: &str,
            next_action: &str,
            decision_fingerprint: String,
            product_evidence_fingerprint: String,
        ) -> (TaskRecord, HeadlessRunProductCompletionDecision) {
            let start = parse_line(
                &json!({
                    "jsonrpc": "2.0",
                    "id": 1,
                    "method": "task.start",
                    "params": {
                        "goal": goal,
                        "mode_id": "implementer",
                    }
                })
                .to_string(),
            );
            assert!(start.error.is_none(), "{:?}", start.error);
            let source_task_id = start.result.expect("start result")["task_id"]
                .as_str()
                .expect("source task id")
                .to_string();
            let completed = store
                .tasks()
                .update_task_status(
                    &source_task_id,
                    TaskStatus::Completed,
                    LedgerEventKind::TaskCompleted,
                )
                .expect("complete source");
            let carry_forward =
                technical_debt_carry_forward_from_items(&[TechnicalDebtCarryForwardItem {
                    debt_id: "source-debt-1".to_string(),
                    summary: "preserve product continuation debt".to_string(),
                    source_milestone: "M53 Product Continuation".to_string(),
                    source_phase: "M53.2".to_string(),
                    source_pr: Some("PR248".to_string()),
                    target_capability: "headless_autonomous_development".to_string(),
                    classification: "required_before_release".to_string(),
                    status: "open".to_string(),
                    next_action: "bind_debt_to_continuation_task".to_string(),
                    closure_evidence_fingerprint: None,
                }])
                .expect("carry-forward");
            let decision = HeadlessRunProductCompletionDecision {
                decision_id: decision_id.to_string(),
                task_id: completed.task_id.clone(),
                run_id: completed.run_id.clone(),
                acceptance_id: "acceptance_1".to_string(),
                status: status.to_string(),
                next_action: next_action.to_string(),
                target_capability: "headless_autonomous_development".to_string(),
                concrete_capability_transition: "runtime_owned_product_continuation_task_admission"
                    .to_string(),
                accepted_completion_fingerprint: fp('a'),
                terminal_completion_fingerprint: fp('b'),
                completion_closure_fingerprint: fp('c'),
                product_evidence_fingerprint,
                decision_fingerprint,
                validated_gate_categories: PRODUCT_COMPLETION_DECISION_REQUIRED_CATEGORIES
                    .iter()
                    .map(|category| category.to_string())
                    .collect(),
                derived_product_evidence_matrix_fingerprint: None,
                behavior_evidence_count: 3,
                rejected_alternatives_count: 2,
                safety_boundary_reviewed: true,
                non_goals_reviewed: true,
                technical_debt_reviewed: true,
                remaining_capability: Some("plan_next_phase".to_string()),
                selected_remaining_gap: None,
                milestone_exit_rationale: None,
                technical_debt_carry_forward: Some(carry_forward),
                replayed: false,
            };
            store
                .tasks()
                .append_task_event_with_payload(
                    &completed,
                    LedgerEventKind::HeadlessRunProductCompletionDecisionRecorded,
                    Some(headless_product_completion_decision_payload(&decision)),
                )
                .expect("append product decision");
            (completed, decision)
        }

        fn product_continuation_source(
            decision: &HeadlessRunProductCompletionDecision,
            authorize: bool,
        ) -> serde_json::Value {
            json!({
                "source_task_id": decision.task_id,
                "source_run_id": decision.run_id,
                "source_decision_id": decision.decision_id,
                "expected_decision_fingerprint": decision.decision_fingerprint,
                "expected_accepted_completion_fingerprint": decision.accepted_completion_fingerprint,
                "expected_terminal_completion_fingerprint": decision.terminal_completion_fingerprint,
                "expected_completion_closure_fingerprint": decision.completion_closure_fingerprint,
                "expected_product_evidence_fingerprint": decision.product_evidence_fingerprint,
                "authorize_product_continuation": authorize,
            })
        }

        let (source, decision) = create_source_decision(
            &store,
            "M53 source continue decision",
            "product_decision_continue",
            "continue_development",
            "plan_next_phase",
            fp('d'),
            fp('e'),
        );
        let request = json!({
            "jsonrpc": "2.0",
            "id": 10,
            "method": "task.start",
            "params": {
                "goal": "Plan the next Brownie phase from product evidence",
                "mode_id": "implementer",
                "product_continuation_source": product_continuation_source(&decision, true),
            }
        });
        let admitted = parse_line(&request.to_string());
        assert!(admitted.error.is_none(), "{:?}", admitted.error);
        let admitted_result = admitted.result.expect("admitted result");
        let admission = &admitted_result["product_continuation_admission"];
        assert_eq!(admission["source_task_id"], decision.task_id);
        assert_eq!(admission["source_run_id"], decision.run_id);
        assert_eq!(admission["source_decision_id"], decision.decision_id);
        assert_eq!(
            admission["decision_fingerprint"],
            decision.decision_fingerprint
        );
        assert_eq!(
            admission["product_evidence_fingerprint"],
            decision.product_evidence_fingerprint
        );
        assert_eq!(admission["continuation_running_enabled"], false);
        assert_eq!(
            admission["next_action"],
            "run_product_continuation_task_explicitly"
        );
        assert_eq!(admission["replayed"], false);

        let continuation_task_id = admission["continuation_task_id"]
            .as_str()
            .expect("continuation task id")
            .to_string();
        let continuation_run_id = admission["continuation_run_id"]
            .as_str()
            .expect("continuation run id")
            .to_string();
        let continuation_task = store
            .tasks()
            .get_task(&continuation_task_id)
            .expect("read continuation task")
            .expect("continuation task exists");
        assert_eq!(continuation_task.status, TaskStatus::Created);
        let product_continuation_provenance = continuation_task
            .product_continuation_provenance
            .as_ref()
            .expect("product continuation provenance");
        assert_eq!(
            product_continuation_provenance
                .remaining_capability
                .as_deref(),
            Some("plan_next_phase")
        );
        assert_eq!(
            product_continuation_provenance
                .technical_debt_carry_forward
                .as_ref()
                .expect("carry-forward")
                .items[0]
                .debt_id,
            "source-debt-1"
        );
        assert_eq!(
            product_continuation_provenance.technical_debt_carry_forward,
            decision.technical_debt_carry_forward
        );
        let synthetic_drive_result = HeadlessRunDriveResult {
            status: HeadlessContinueOnceStatus::TaskExecuted,
            session_id: "m54.debt.transition".to_string(),
            drive_id: "m54.debt.transition.route".to_string(),
            start_session_sequence: 1,
            end_session_sequence: 2,
            replayed: false,
            max_advances: 1,
            max_steps_per_advance: 1,
            advance_count: 1,
            executed_count: 1,
            replayed_count: 0,
            stop_reason: "synthetic product decision boundary".to_string(),
            drive_fingerprint: fp('6'),
            terminal_completion_evidence: None,
            completion_closure: HeadlessRunCompletionClosure {
                status: HeadlessRunCompletionClosureStatus::Complete,
                stop_reason: "complete".to_string(),
                terminal_task_count: 1,
                total_task_count: 1,
                runnable_task_count: 0,
                blocked_task_count: 0,
                route_candidate_count: 0,
                progress_fingerprint: fp('7'),
                aggregate_sequence: 2,
                route_kind: None,
                route_task_id: None,
                route_run_id: None,
                terminal_completion_fingerprint: Some(fp('8')),
                next_action: "record_product_completion_decision_with_runtime_evidence".to_string(),
                closure_fingerprint: fp('9'),
            },
            completion_finalization: None,
            accepted_completion: Some(HeadlessRunAcceptedCompletion {
                task_id: continuation_task_id.clone(),
                run_id: continuation_run_id.clone(),
                acceptance_id: "m54-transition-acceptance".to_string(),
                status: "accepted".to_string(),
                terminal_completion_fingerprint: fp('8'),
                acceptance_fingerprint: fp('a'),
                verifier_gate_status: "not_required".to_string(),
                replayed: false,
                next_action: "drive_product_completion".to_string(),
            }),
            product_evidence_matrix: None,
            selected_product_gap_closure: None,
            product_completion_decision: None,
            start_progress: HeadlessRunProgressCheckpoint {
                progress_fingerprint: fp('b'),
                aggregate_sequence: 1,
            },
            post_progress: Some(HeadlessRunProgressCheckpoint {
                progress_fingerprint: fp('c'),
                aggregate_sequence: 2,
            }),
            next_route: None,
            objective_proposal_candidate: None,
            advances: vec![],
            journey_route_resume: None,
            journey_closure: None,
            journey: None,
            journey_execution: None,
            next_action: "record_product_completion_decision_with_runtime_evidence".to_string(),
        };
        let base_transition_decision = HeadlessRunProductCompletionDecisionRequest {
            authorize_product_completion_decision: true,
            decision_id: "m54-transition-decision".to_string(),
            expected_accepted_completion_fingerprint: fp('a'),
            expected_terminal_completion_fingerprint: fp('8'),
            expected_completion_closure_fingerprint: fp('9'),
            expected_product_evidence_fingerprint: fp('d'),
            evidence_status: "product_complete".to_string(),
            target_capability: "headless_autonomous_development".to_string(),
            concrete_capability_transition: "runtime_derived_technical_debt_state_transitions"
                .to_string(),
            validated_gate_categories: PRODUCT_COMPLETION_DECISION_REQUIRED_CATEGORIES
                .iter()
                .map(|category| category.to_string())
                .collect(),
            derived_product_evidence_matrix_fingerprint: None,
            behavior_evidence_count: 4,
            rejected_alternatives_count: 3,
            safety_boundary_reviewed: true,
            non_goals_reviewed: true,
            technical_debt_reviewed: true,
            remaining_capability: None,
            milestone_exit_rationale: Some("m54_transition_complete".to_string()),
            technical_debt_carry_forward: None,
            technical_debt_transitions: None,
        };
        let omitted_transition = technical_debt_carry_forward_for_decision(
            &store,
            &synthetic_drive_result,
            &base_transition_decision,
        )
        .expect("omitted prior debt derives state")
        .expect("prior debt remains active");
        assert_eq!(omitted_transition.items[0].debt_id, "source-debt-1");
        assert_eq!(
            omitted_transition.items[0].classification,
            "required_before_release"
        );
        let mut resolved_transition = base_transition_decision.clone();
        resolved_transition.technical_debt_transitions = Some(vec![TechnicalDebtTransition {
            debt_id: "source-debt-1".to_string(),
            status: "resolved".to_string(),
            next_action: "close_with_evidence".to_string(),
            closure_evidence_fingerprint: Some(fp('e')),
        }]);
        assert!(technical_debt_carry_forward_for_decision(
            &store,
            &synthetic_drive_result,
            &resolved_transition,
        )
        .expect("resolved transition derives empty state")
        .is_none());
        let mut missing_evidence = resolved_transition.clone();
        missing_evidence
            .technical_debt_transitions
            .as_mut()
            .expect("transition")[0]
            .closure_evidence_fingerprint = None;
        assert!(technical_debt_carry_forward_for_decision(
            &store,
            &synthetic_drive_result,
            &missing_evidence,
        )
        .expect_err("closing transition without evidence")
        .contains("closing transitions require closure_evidence_fingerprint"));
        assert!(continuation_task.verification_recovery_provenance.is_none());
        assert!(continuation_task
            .llm_provider_failure_retry_provenance
            .is_none());
        let continuation_events = store
            .tasks()
            .read_ledger_events(&continuation_run_id)
            .expect("continuation events");
        assert_eq!(
            continuation_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskStarted)
                .count(),
            1
        );
        assert!(!continuation_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::TaskRunning));
        assert!(continuation_events.iter().all(|event| {
            event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("execution_enabled"))
                .and_then(Value::as_bool)
                != Some(true)
        }));

        let serialized = serde_json::to_string(&admitted_result).expect("serialize admission");
        let task_started_payload = serde_json::to_string(
            &continuation_events
                .iter()
                .find(|event| event.kind == LedgerEventKind::TaskStarted)
                .expect("task started")
                .payload,
        )
        .expect("serialize task started");
        for forbidden in [
            "raw_prompt",
            "provider_response",
            "final_response",
            "file_content",
            "diff",
            "stdout",
            "stderr",
            "command",
            "environment",
            "raw_ledger_payload",
            "absolute_path",
            "canonical_path",
            "secret",
        ] {
            assert!(!serialized.contains(&format!(r#"\"{forbidden}\""#)));
            assert!(!task_started_payload.contains(&format!(r#"\"{forbidden}\""#)));
        }

        let replay = parse_line(&request.to_string());
        assert!(replay.error.is_none(), "{:?}", replay.error);
        let replay_result = replay.result.expect("replay result");
        assert_eq!(
            replay_result["product_continuation_admission"]["continuation_task_id"],
            continuation_task_id
        );
        assert_eq!(
            replay_result["product_continuation_admission"]["continuation_run_id"],
            continuation_run_id
        );
        assert_eq!(
            replay_result["product_continuation_admission"]["replayed"],
            true
        );
        let replay_events = store
            .tasks()
            .read_ledger_events(&continuation_run_id)
            .expect("replay continuation events");
        assert_eq!(
            replay_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskStarted)
                .count(),
            1
        );

        let task_count_before_request_conflicts =
            store.tasks().list_tasks().expect("list tasks").len();
        let different_goal_conflict = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 101,
                "method": "task.start",
                "params": {
                    "goal": "Plan a different product continuation goal",
                    "mode_id": "implementer",
                    "product_continuation_source": product_continuation_source(&decision, true),
                }
            })
            .to_string(),
        );
        assert!(different_goal_conflict.result.is_none());
        assert!(different_goal_conflict
            .error
            .expect("different goal conflict error")
            .message
            .contains("conflicting product continuation admission"));
        let different_mode_conflict = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 102,
                "method": "task.start",
                "params": {
                    "goal": "Plan the next Brownie phase from product evidence",
                    "mode_id": "orchestrator",
                    "product_continuation_source": product_continuation_source(&decision, true),
                }
            })
            .to_string(),
        );
        assert!(different_mode_conflict.result.is_none());
        assert!(different_mode_conflict
            .error
            .expect("different mode conflict error")
            .message
            .contains("conflicting product continuation admission"));
        assert_eq!(
            store
                .tasks()
                .list_tasks()
                .expect("list after request conflicts")
                .len(),
            task_count_before_request_conflicts
        );

        let task_count_before_conflict = store.tasks().list_tasks().expect("list tasks").len();
        let mut conflicting_decision = decision.clone();
        conflicting_decision.decision_id = "product_decision_continue_conflict".to_string();
        store
            .tasks()
            .append_task_event_with_payload(
                &source,
                LedgerEventKind::HeadlessRunProductCompletionDecisionRecorded,
                Some(headless_product_completion_decision_payload(
                    &conflicting_decision,
                )),
            )
            .expect("append conflicting product decision");
        let conflict = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 11,
                "method": "task.start",
                "params": {
                    "goal": "conflicting product continuation",
                    "mode_id": "implementer",
                    "product_continuation_source": product_continuation_source(&conflicting_decision, true),
                }
            })
            .to_string(),
        );
        assert!(conflict.result.is_none());
        assert!(conflict
            .error
            .expect("conflict error")
            .message
            .contains("conflicting product continuation admission"));
        assert_eq!(
            store
                .tasks()
                .list_tasks()
                .expect("list after conflict")
                .len(),
            task_count_before_conflict
        );

        let task_count_before_denials = store.tasks().list_tasks().expect("list tasks").len();
        let mut stale_source = product_continuation_source(&conflicting_decision, true);
        stale_source["expected_product_evidence_fingerprint"] = json!(fp('f'));
        let stale = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 12,
                "method": "task.start",
                "params": {
                    "goal": "stale product evidence",
                    "mode_id": "implementer",
                    "product_continuation_source": stale_source,
                }
            })
            .to_string(),
        );
        assert!(stale.result.is_none());
        assert!(stale
            .error
            .expect("stale error")
            .message
            .contains("expected_product_evidence_fingerprint is stale"));
        let unauthorized = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 13,
                "method": "task.start",
                "params": {
                    "goal": "missing authorization",
                    "mode_id": "implementer",
                    "product_continuation_source": product_continuation_source(&decision, false),
                }
            })
            .to_string(),
        );
        assert!(unauthorized.result.is_none());
        assert!(unauthorized
            .error
            .expect("unauthorized error")
            .message
            .contains("authorize_product_continuation must be true"));

        let (_complete_source, complete_decision) = create_source_decision(
            &store,
            "M53 product complete source",
            "product_decision_complete",
            "product_complete",
            "stop_autonomous_development",
            fp('1'),
            fp('2'),
        );
        let complete = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 14,
                "method": "task.start",
                "params": {
                    "goal": "should not continue complete product",
                    "mode_id": "implementer",
                    "product_continuation_source": product_continuation_source(&complete_decision, true),
                }
            })
            .to_string(),
        );
        assert!(complete.result.is_none());
        assert!(complete
            .error
            .expect("complete error")
            .message
            .contains("product_complete"));

        let (_blocked_source, blocked_decision) = create_source_decision(
            &store,
            "M53 blocked evidence source",
            "product_decision_blocked",
            "blocked_by_product_evidence",
            "repair_product_completion_evidence",
            fp('3'),
            fp('4'),
        );
        let blocked = parse_line(
            &json!({
                "jsonrpc": "2.0",
                "id": 15,
                "method": "task.start",
                "params": {
                    "goal": "should not continue blocked product evidence",
                    "mode_id": "implementer",
                    "product_continuation_source": product_continuation_source(&blocked_decision, true),
                }
            })
            .to_string(),
        );
        assert!(blocked.result.is_none());
        assert!(blocked
            .error
            .expect("blocked error")
            .message
            .contains("blocked_by_product_evidence"));

        assert_eq!(
            store
                .tasks()
                .list_tasks()
                .expect("list after denials")
                .len(),
            task_count_before_denials + 2
        );

        let (_headless_source, headless_decision) = create_source_decision(
            &store,
            "M57 headless product continuation source",
            "product_decision_headless_continue",
            "continue_development",
            "plan_next_phase",
            fp('5'),
            fp('6'),
        );
        let progress_tasks = store.tasks().list_tasks().expect("list tasks for progress");
        let progress =
            task_list_progress_overview(&store, &progress_tasks).expect("progress overview");
        let headless_request = json!({
            "jsonrpc": "2.0",
            "id": 160,
            "method": "headless.continue_once",
            "params": {
                "authorize": true,
                "continuation_id": "m57.product.continuation.admission",
                "expected_progress_fingerprint": progress.source_fingerprint,
                "expected_aggregate_sequence": progress.aggregate_sequence,
                "product_continuation_admission_target": {
                    "authorize_product_continuation_admission": true,
                    "product_continuation_source": product_continuation_source(&headless_decision, true),
                    "continuation_goal": "Plan the next Brownie phase through headless continuation",
                    "continuation_mode_id": "implementer"
                }
            }
        });
        let headless = parse_line(&headless_request.to_string());
        assert!(headless.error.is_none(), "{:?}", headless.error);
        let headless_result = headless.result.expect("headless admission result");
        assert_eq!(
            headless_result["product_continuation_admission"]["source_decision_id"],
            json!(headless_decision.decision_id)
        );
        assert_eq!(
            headless_result["product_continuation_admission"]["next_action"],
            "run_product_continuation_task_explicitly"
        );
        assert_eq!(
            headless_result["product_continuation_admission"]["continuation_running_enabled"],
            false
        );
        assert!(headless_result["task_run_result"].is_null());
        assert_eq!(
            headless_result["next_route"]["kind"],
            "run_product_continuation_task_explicitly"
        );
        let headless_task_id = headless_result["product_continuation_admission"]
            ["continuation_task_id"]
            .as_str()
            .expect("headless continuation task")
            .to_string();
        let headless_run_id = headless_result["product_continuation_admission"]
            ["continuation_run_id"]
            .as_str()
            .expect("headless continuation run")
            .to_string();
        let headless_task = store
            .tasks()
            .get_task(&headless_task_id)
            .expect("read headless continuation task")
            .expect("headless continuation task exists");
        assert_eq!(headless_task.status, TaskStatus::Created);
        let headless_events = store
            .tasks()
            .read_ledger_events(&headless_run_id)
            .expect("headless events");
        assert!(headless_events
            .iter()
            .any(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded));
        assert!(headless_events
            .iter()
            .all(|event| event.kind != LedgerEventKind::TaskRunning));

        let headless_replay = parse_line(&headless_request.to_string());
        assert!(
            headless_replay.error.is_none(),
            "{:?}",
            headless_replay.error
        );
        let headless_replay_result = headless_replay.result.expect("headless replay result");
        assert_eq!(headless_replay_result["replayed"], true);
        assert_eq!(
            headless_replay_result["product_continuation_admission"]["continuation_task_id"],
            headless_task_id
        );
        let headless_replay_events = store
            .tasks()
            .read_ledger_events(&headless_run_id)
            .expect("headless replay events");
        assert_eq!(
            headless_replay_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
                .count(),
            1
        );

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_continue_runs_product_continuation_admission_and_replays() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        let store = BrownieStore::new(temp.path());

        fn fp(hex: char) -> String {
            format!("sha256:{}", hex.to_string().repeat(64))
        }

        let source_start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"M57.2 source task","mode_id":"implementer"}}"#,
        );
        assert!(source_start.error.is_none(), "{:?}", source_start.error);
        let source_task_id = source_start.result.expect("source start result")["task_id"]
            .as_str()
            .expect("source task id")
            .to_string();
        let source = store
            .tasks()
            .update_task_status(
                &source_task_id,
                TaskStatus::Completed,
                LedgerEventKind::TaskCompleted,
            )
            .expect("complete source");
        let decision = HeadlessRunProductCompletionDecision {
            decision_id: "m57-2-product-decision".to_string(),
            task_id: source.task_id.clone(),
            run_id: source.run_id.clone(),
            acceptance_id: "m57-2-acceptance".to_string(),
            status: "continue_development".to_string(),
            next_action: "plan_next_phase".to_string(),
            target_capability: "headless_autonomous_development".to_string(),
            concrete_capability_transition:
                "headless_continue_once_product_continuation_explicit_run_route".to_string(),
            accepted_completion_fingerprint: fp('a'),
            terminal_completion_fingerprint: fp('b'),
            completion_closure_fingerprint: fp('c'),
            product_evidence_fingerprint: fp('d'),
            decision_fingerprint: fp('e'),
            validated_gate_categories: PRODUCT_COMPLETION_DECISION_REQUIRED_CATEGORIES
                .iter()
                .map(|category| category.to_string())
                .collect(),
            derived_product_evidence_matrix_fingerprint: None,
            behavior_evidence_count: 3,
            rejected_alternatives_count: 2,
            safety_boundary_reviewed: true,
            non_goals_reviewed: true,
            technical_debt_reviewed: true,
            remaining_capability: Some("run_next_phase".to_string()),
            selected_remaining_gap: None,
            milestone_exit_rationale: None,
            technical_debt_carry_forward: None,
            replayed: false,
        };
        store
            .tasks()
            .append_task_event_with_payload(
                &source,
                LedgerEventKind::HeadlessRunProductCompletionDecisionRecorded,
                Some(headless_product_completion_decision_payload(&decision)),
            )
            .expect("append decision");

        let progress = parse_line(r#"{"jsonrpc":"2.0","id":2,"method":"task.list"}"#)
            .result
            .expect("progress result")["progress_overview"]
            .clone();
        let admission_request = json!({
            "jsonrpc": "2.0",
            "id": 3,
            "method": "headless.continue_once",
            "params": {
                "authorize": true,
                "continuation_id": "m57.2.product.admit",
                "expected_progress_fingerprint": progress["source_fingerprint"],
                "expected_aggregate_sequence": progress["aggregate_sequence"],
                "product_continuation_admission_target": {
                    "authorize_product_continuation_admission": true,
                    "continuation_goal": "Run the next product continuation task",
                    "continuation_mode_id": "implementer",
                    "product_continuation_source": {
                        "source_task_id": decision.task_id,
                        "source_run_id": decision.run_id,
                        "source_decision_id": decision.decision_id,
                        "expected_decision_fingerprint": decision.decision_fingerprint,
                        "expected_accepted_completion_fingerprint": decision.accepted_completion_fingerprint,
                        "expected_terminal_completion_fingerprint": decision.terminal_completion_fingerprint,
                        "expected_completion_closure_fingerprint": decision.completion_closure_fingerprint,
                        "expected_product_evidence_fingerprint": decision.product_evidence_fingerprint,
                        "authorize_product_continuation": true,
                    }
                }
            }
        });
        let admitted = parse_line(&admission_request.to_string());
        assert!(admitted.error.is_none(), "{:?}", admitted.error);
        let admitted_result = admitted.result.expect("admitted result");
        let admission = &admitted_result["product_continuation_admission"];
        let continuation_task_id = admission["continuation_task_id"]
            .as_str()
            .expect("continuation task id")
            .to_string();
        let continuation_run_id = admission["continuation_run_id"]
            .as_str()
            .expect("continuation run id")
            .to_string();
        assert_eq!(
            admitted_result["next_route"]["kind"],
            "run_product_continuation_task_explicitly"
        );

        let post_admission_progress =
            parse_line(r#"{"jsonrpc":"2.0","id":4,"method":"task.list"}"#)
                .result
                .expect("post admission progress result")["progress_overview"]
                .clone();
        let run_request = json!({
            "jsonrpc": "2.0",
            "id": 5,
            "method": "headless.continue_once",
            "params": {
                "authorize": true,
                "continuation_id": "m57.2.product.run",
                "expected_progress_fingerprint": post_admission_progress["source_fingerprint"],
                "expected_aggregate_sequence": post_admission_progress["aggregate_sequence"],
                "product_continuation_run_target": {
                    "authorize_product_continuation_run": true,
                    "continuation_task_id": continuation_task_id,
                    "continuation_run_id": continuation_run_id,
                    "source_task_id": admission["source_task_id"],
                    "source_run_id": admission["source_run_id"],
                    "source_decision_id": admission["source_decision_id"],
                    "expected_decision_fingerprint": admission["decision_fingerprint"],
                    "expected_product_evidence_fingerprint": admission["product_evidence_fingerprint"],
                    "expected_admission_route_kind": "run_product_continuation_task_explicitly"
                }
            }
        });
        let run = parse_line(&run_request.to_string());
        assert!(run.error.is_none(), "{:?}", run.error);
        let run_result = run.result.expect("run result");
        assert_eq!(run_result["status"], "task_executed");
        assert_eq!(run_result["replayed"], false);
        assert_eq!(run_result["selected_task_id"], continuation_task_id);
        assert_eq!(run_result["selected_run_id"], continuation_run_id);
        assert_eq!(
            run_result["task_run_result"]["task_id"],
            continuation_task_id
        );
        assert_eq!(run_result["task_run_result"]["run_id"], continuation_run_id);
        assert!(run_result["task_run_result"]["agent_loop"]["final_state"].is_string());

        let events_after_run = store
            .tasks()
            .read_ledger_events(&continuation_run_id)
            .expect("events after run");
        assert_eq!(
            events_after_run
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            1
        );
        assert_eq!(
            events_after_run
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
                .count(),
            2
        );

        let replay = parse_line(&run_request.to_string());
        assert!(replay.error.is_none(), "{:?}", replay.error);
        let replay_result = replay.result.expect("replay result");
        assert_eq!(replay_result["replayed"], true);
        assert_eq!(
            replay_result["task_run_result"]["task_id"],
            continuation_task_id
        );
        let events_after_replay = store
            .tasks()
            .read_ledger_events(&continuation_run_id)
            .expect("events after replay");
        assert_eq!(
            events_after_replay
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            1
        );
        assert_eq!(
            events_after_replay
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
                .count(),
            2
        );

        let mut stale_request = run_request.clone();
        stale_request["id"] = json!(6);
        stale_request["params"]["continuation_id"] = json!("m57.2.product.run.stale");
        stale_request["params"]["expected_progress_fingerprint"] = json!(fp('f'));
        let stale = parse_line(&stale_request.to_string());
        assert!(stale.error.is_none(), "{:?}", stale.error);
        let stale_result = stale.result.expect("stale result");
        assert_eq!(stale_result["status"], "stale_progress");
        let events_after_stale = store
            .tasks()
            .read_ledger_events(&continuation_run_id)
            .expect("events after stale");
        assert_eq!(
            events_after_stale
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            1
        );

        let serialized = serde_json::to_string(&run_result).expect("serialize run result");
        for forbidden in [
            "raw_prompt",
            "provider_response",
            "final_response",
            "file_content",
            "diff",
            "stdout",
            "stderr",
            "command",
            "environment",
            "raw_request",
            "raw_ledger_payload",
            "absolute_path",
            "canonical_path",
            "secret",
        ] {
            assert!(!serialized.contains(&format!(r#"\"{forbidden}\""#)));
        }

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn headless_run_drive_advances_product_continuation_routes_and_replays() {
        let _guard = ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("tempdir");
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        let store = BrownieStore::new(temp.path());

        fn fp(hex: char) -> String {
            format!("sha256:{}", hex.to_string().repeat(64))
        }

        let source_start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"M58.1 source task","mode_id":"implementer"}}"#,
        );
        assert!(source_start.error.is_none(), "{:?}", source_start.error);
        let source_task_id = source_start.result.expect("source start result")["task_id"]
            .as_str()
            .expect("source task id")
            .to_string();
        let source = store
            .tasks()
            .update_task_status(
                &source_task_id,
                TaskStatus::Completed,
                LedgerEventKind::TaskCompleted,
            )
            .expect("complete source");
        let decision = HeadlessRunProductCompletionDecision {
            decision_id: "m58-1-product-decision".to_string(),
            task_id: source.task_id.clone(),
            run_id: source.run_id.clone(),
            acceptance_id: "m58-1-acceptance".to_string(),
            status: "continue_development".to_string(),
            next_action: "plan_next_phase".to_string(),
            target_capability: "headless_autonomous_development".to_string(),
            concrete_capability_transition: "headless_run_drive_product_continuation_route_step"
                .to_string(),
            accepted_completion_fingerprint: fp('a'),
            terminal_completion_fingerprint: fp('b'),
            completion_closure_fingerprint: fp('c'),
            product_evidence_fingerprint: fp('d'),
            decision_fingerprint: fp('e'),
            validated_gate_categories: PRODUCT_COMPLETION_DECISION_REQUIRED_CATEGORIES
                .iter()
                .map(|category| category.to_string())
                .collect(),
            derived_product_evidence_matrix_fingerprint: None,
            behavior_evidence_count: 3,
            rejected_alternatives_count: 2,
            safety_boundary_reviewed: true,
            non_goals_reviewed: true,
            technical_debt_reviewed: true,
            remaining_capability: Some("run_next_phase".to_string()),
            selected_remaining_gap: None,
            milestone_exit_rationale: None,
            technical_debt_carry_forward: None,
            replayed: false,
        };
        store
            .tasks()
            .append_task_event_with_payload(
                &source,
                LedgerEventKind::HeadlessRunProductCompletionDecisionRecorded,
                Some(headless_product_completion_decision_payload(&decision)),
            )
            .expect("append decision");

        let progress = parse_line(r#"{"jsonrpc":"2.0","id":2,"method":"task.list"}"#)
            .result
            .expect("progress result")["progress_overview"]
            .clone();
        let progress_fingerprint = progress["source_fingerprint"]
            .as_str()
            .expect("progress fingerprint")
            .to_string();
        let aggregate_sequence = progress["aggregate_sequence"]
            .as_u64()
            .expect("aggregate sequence");
        let seed_checkpoint = HeadlessRunSessionCheckpoint {
            session_id: "m58.product.drive".to_string(),
            advance_id: "m58.product.drive.seed".to_string(),
            session_sequence: 1,
            result: HeadlessRunAdvanceResult {
                status: HeadlessContinueOnceStatus::NoEligibleTask,
                session_id: "m58.product.drive".to_string(),
                advance_id: "m58.product.drive.seed".to_string(),
                session_sequence: 1,
                replayed: false,
                start_progress: HeadlessRunProgressCheckpoint {
                    progress_fingerprint: progress_fingerprint.clone(),
                    aggregate_sequence,
                },
                post_progress: Some(HeadlessRunProgressCheckpoint {
                    progress_fingerprint: progress_fingerprint.clone(),
                    aggregate_sequence,
                }),
                max_steps: 1,
                step_count: 0,
                executed_count: 0,
                replayed_count: 0,
                stop_reason: "seeded_product_continuation_boundary".to_string(),
                checkpoint_fingerprint: fp('f'),
                terminal_completion_evidence: None,
                next_route: Some(HeadlessContinueRoute {
                    kind: HeadlessContinueRouteKind::AdmitProductContinuationTaskExplicitly,
                    reason: "Seeded product-continuation boundary".to_string(),
                    task_id: Some(decision.task_id.clone()),
                    run_id: Some(decision.run_id.clone()),
                    proposal_id: None,
                    apply_id: None,
                    failure_fingerprint: None,
                    apply_fingerprint: None,
                    progress_fingerprint: Some(progress_fingerprint.clone()),
                    aggregate_sequence: Some(aggregate_sequence),
                    next_action: "admit_product_continuation_task_explicitly".to_string(),
                }),
                steps: Vec::new(),
                next_action: "admit_product_continuation_task_explicitly".to_string(),
            },
        };
        store
            .tasks()
            .write_headless_run_session_checkpoint(&seed_checkpoint)
            .expect("write seed checkpoint");

        let sequence_drive_request = json!({
            "jsonrpc": "2.0",
            "id": 3,
            "method": "headless.run.drive",
            "params": {
                "authorize": true,
                "session_id": "m58.product.drive",
                "drive_id": "m58.product.drive.sequence",
                "expected_start_session_sequence": 1,
                "max_advances": 2,
                "max_steps_per_advance": 1,
                "product_continuation_derived_target": {
                    "authorize_product_continuation_target_derivation": true,
                    "continuation_mode_id": "implementer"
                }
            }
        });
        let sequence_drive = parse_line(&sequence_drive_request.to_string());
        assert!(sequence_drive.error.is_none(), "{:?}", sequence_drive.error);
        let sequence_drive_result = sequence_drive.result.expect("sequence drive result");
        assert_eq!(sequence_drive_result["advance_count"], 2);
        assert_eq!(sequence_drive_result["advances"][0]["session_sequence"], 2);
        assert_eq!(sequence_drive_result["advances"][1]["session_sequence"], 3);
        assert_eq!(
            sequence_drive_result["advances"][0]["steps"][0]["next_action"],
            "run_product_continuation_task_explicitly"
        );
        let admission = &sequence_drive_result["advances"][0]["steps"][0];
        let continuation_task_id = admission["selected_task_id"]
            .as_str()
            .expect("continuation task")
            .to_string();
        let continuation_run_id = admission["selected_run_id"]
            .as_str()
            .expect("continuation run")
            .to_string();
        let continuation_record = store
            .tasks()
            .get_task(&continuation_task_id)
            .expect("read runtime-derived continuation")
            .expect("runtime-derived continuation exists");
        assert_eq!(
            continuation_record.goal,
            "Continue development for remaining capability: run_next_phase"
        );
        assert!(!continuation_record.goal.contains("Brownie"));
        assert!(!continuation_record
            .goal
            .contains("headless_run_drive_product_continuation_route_step"));
        let objective_provenance = continuation_record
            .product_objective_continuation_provenance
            .as_ref()
            .expect("runtime-derived objective provenance");
        assert_eq!(
            objective_provenance.source_decision_id,
            decision.decision_id
        );
        assert_eq!(
            objective_provenance.decision_fingerprint,
            decision.decision_fingerprint
        );
        assert_eq!(
            objective_provenance.target_capability,
            "headless_autonomous_development"
        );
        assert_eq!(
            objective_provenance.concrete_capability_transition,
            "headless_run_drive_product_continuation_route_step"
        );
        assert_eq!(objective_provenance.remaining_capability, "run_next_phase");
        assert_eq!(
            objective_provenance.remaining_capability_fingerprint,
            format!("sha256:{}", hex_sha256("run_next_phase".as_bytes()))
        );
        assert!(is_sha256_fingerprint(
            &objective_provenance.derived_objective_fingerprint
        ));
        assert!(is_sha256_fingerprint(
            &objective_provenance.derived_goal_fingerprint
        ));
        assert_eq!(
            sequence_drive_result["advances"][1]["status"],
            "task_executed"
        );
        assert_eq!(
            sequence_drive_result["advances"][1]["steps"][0]["selected_task_id"],
            continuation_task_id
        );
        assert_eq!(sequence_drive_result["stop_reason"], "budget_exhausted");
        let admitted_events = store
            .tasks()
            .read_ledger_events(&continuation_run_id)
            .expect("admitted events");
        assert_eq!(
            admitted_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::HeadlessContinuationDecisionRecorded)
                .count(),
            2
        );
        assert_eq!(
            admitted_events
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            1
        );
        let task_started_payload = admitted_events
            .iter()
            .find(|event| event.kind == LedgerEventKind::TaskStarted)
            .and_then(|event| event.payload.as_ref())
            .expect("task started payload");
        assert_eq!(
            task_started_payload["product_objective_continuation_provenance"]["source_decision_id"],
            decision.decision_id
        );
        assert_eq!(
            task_started_payload["derived_objective_fingerprint"],
            objective_provenance.derived_objective_fingerprint
        );

        let sequence_replay = parse_line(&sequence_drive_request.to_string());
        assert!(
            sequence_replay.error.is_none(),
            "{:?}",
            sequence_replay.error
        );
        assert_eq!(
            sequence_replay.result.expect("sequence replay")["replayed"],
            true
        );
        let events_after_replay = store
            .tasks()
            .read_ledger_events(&continuation_run_id)
            .expect("events after replay");
        assert_eq!(
            events_after_replay
                .iter()
                .filter(|event| event.kind == LedgerEventKind::TaskRunning)
                .count(),
            1
        );

        let mut mismatched_replay = sequence_drive_request.clone();
        mismatched_replay["id"] = json!(5);
        mismatched_replay["params"]["product_continuation_derived_target"]["continuation_goal"] =
            json!("conflicting drive replay goal");
        let mismatch = parse_line(&mismatched_replay.to_string());
        assert!(mismatch.result.is_none());
        assert!(mismatch
            .error
            .expect("mismatched replay error")
            .message
            .contains("request identity mismatch"));

        std::env::remove_var("BROWNIE_WORKSPACE_ROOT");
    }

    #[test]
    fn product_objective_continuation_derives_generic_goal_from_remaining_capability() {
        fn fp(hex: char) -> String {
            format!("sha256:{}", hex.to_string().repeat(64))
        }

        let mut provenance = ProductContinuationProvenance {
            source_task_id: "task.remaining.a".to_string(),
            source_run_id: "run.remaining.a".to_string(),
            source_decision_id: "decision.remaining.a".to_string(),
            decision_fingerprint: fp('a'),
            accepted_completion_fingerprint: fp('b'),
            terminal_completion_fingerprint: fp('c'),
            completion_closure_fingerprint: fp('d'),
            product_evidence_fingerprint: fp('e'),
            target_capability: "headless_autonomous_development".to_string(),
            concrete_capability_transition: "completed_transition_label".to_string(),
            decision_status: "continue_development".to_string(),
            decision_next_action: "plan_next_phase".to_string(),
            remaining_capability: Some("first_remaining_capability".to_string()),
            selected_remaining_gap: None,
            technical_debt_carry_forward: None,
        };

        let first_goal = runtime_derived_product_objective_goal(&provenance).expect("first goal");
        assert_eq!(
            first_goal,
            "Continue development for remaining capability: first_remaining_capability"
        );
        assert!(!first_goal.contains("Brownie"));
        assert!(!first_goal.contains("completed_transition_label"));
        let first_provenance =
            product_objective_continuation_provenance_for(&provenance, &first_goal)
                .expect("first objective provenance");
        assert_eq!(
            first_provenance.remaining_capability,
            "first_remaining_capability"
        );
        assert_eq!(
            first_provenance.remaining_capability_fingerprint,
            format!(
                "sha256:{}",
                hex_sha256("first_remaining_capability".as_bytes())
            )
        );

        provenance.remaining_capability = Some("second_remaining_capability".to_string());
        let second_goal = runtime_derived_product_objective_goal(&provenance).expect("second goal");
        let second_provenance =
            product_objective_continuation_provenance_for(&provenance, &second_goal)
                .expect("second objective provenance");
        assert_ne!(first_goal, second_goal);
        assert_ne!(
            first_provenance.derived_objective_fingerprint,
            second_provenance.derived_objective_fingerprint
        );
        assert_ne!(
            first_provenance.derived_goal_fingerprint,
            second_provenance.derived_goal_fingerprint
        );
    }

    #[test]
    fn product_objective_continuation_rejects_missing_remaining_capability() {
        fn fp(hex: char) -> String {
            format!("sha256:{}", hex.to_string().repeat(64))
        }

        let provenance = ProductContinuationProvenance {
            source_task_id: "task.remaining.missing".to_string(),
            source_run_id: "run.remaining.missing".to_string(),
            source_decision_id: "decision.remaining.missing".to_string(),
            decision_fingerprint: fp('a'),
            accepted_completion_fingerprint: fp('b'),
            terminal_completion_fingerprint: fp('c'),
            completion_closure_fingerprint: fp('d'),
            product_evidence_fingerprint: fp('e'),
            target_capability: "headless_autonomous_development".to_string(),
            concrete_capability_transition: "completed_transition_label".to_string(),
            decision_status: "continue_development".to_string(),
            decision_next_action: "plan_next_phase".to_string(),
            remaining_capability: None,
            selected_remaining_gap: None,
            technical_debt_carry_forward: None,
        };

        let error = runtime_derived_product_objective_goal(&provenance)
            .expect_err("missing remaining capability must fail");
        assert!(matches!(
            error,
            VerificationRecoveryAdmissionError::InvalidParams(_)
        ));
    }

