    #[test]
    fn tool_intent_parse_uses_task_pinned_mcp_dynamic_catalog() {
        let _lock = super::tests::ENV_LOCK.lock().expect("env lock");
        let temp = tempfile::tempdir().expect("temp dir");
        let fake_server = write_fake_mcp_server(temp.path(), "ok");
        write_mcp_modepack(
            temp.path(),
            fake_server.to_str().unwrap(),
            "search_code",
            true,
        );
        commit_trusted_mcp_active_snapshot(temp.path());
        let _cwd = super::tests::CwdGuard::enter(temp.path());
        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Use MCP through tool intent","mode_id":"reviewer"}}"#,
        )
        .result
        .expect("task start");
        let task_id = start["task_id"].as_str().expect("task id");
        let allowed = handle_tool_intent_parse(
            json!(2),
            Some(json!({
                "task_id": task_id,
                "mode_id": "reviewer",
                "assistant_content": "```brownie-tool-intent\n{\"tool_requests\":[{\"tool_id\":\"mcp.github.search_code\",\"reason\":\"Use task-pinned MCP catalog.\",\"input\":{\"query\":\"bounded\"}}]}\n```"
            })),
        )
        .result
        .expect("allowed mcp intent");

        assert_eq!(
            allowed["items"][0]["tool_id"],
            json!("mcp.github.search_code")
        );
        assert_eq!(allowed["items"][0]["required_action"], json!("UseMcpTool"));
        assert_eq!(allowed["items"][0]["allowed"], json!(true));
        assert!(allowed["items"][0].get("input").is_none());

        let rejected = handle_tool_intent_parse(
            json!(3),
            Some(json!({
                "task_id": task_id,
                "mode_id": "reviewer",
                "assistant_content": "```brownie-tool-intent\n{\"tool_requests\":[{\"tool_id\":\"mcp.github.get_file\",\"reason\":\"Outside allow list.\",\"input\":{}}]}\n```"
            })),
        )
        .result
        .expect("rejected mcp intent");

        assert!(rejected["items"].as_array().expect("items").is_empty());
        assert_eq!(rejected["rejected"][0]["code"], json!("unknown_tool"));
    }

    #[test]
    fn task_run_agent_loop_executes_approved_mcp_tool_and_continues() {
        let _lock = super::tests::ENV_LOCK.lock().expect("env lock");
        let _guard = EnvGuard::clear();
        let temp = tempfile::tempdir().expect("temp dir");
        let fake_server = write_fake_mcp_server(temp.path(), "counting");
        write_mcp_modepack(
            temp.path(),
            fake_server.to_str().unwrap(),
            "search_code",
            true,
        );
        commit_trusted_mcp_active_snapshot(temp.path());
        let _cwd = super::tests::CwdGuard::enter(temp.path());
        std::env::set_var("BROWNIE_WORKSPACE_ROOT", temp.path());
        std::env::set_var("BROWNIE_LLM_PROVIDER", "fake");

        let start = parse_line(
            r#"{"jsonrpc":"2.0","id":1,"method":"task.start","params":{"goal":"Use MCP search_code through the normal agent loop","mode_id":"reviewer"}}"#,
        )
        .result
        .expect("task start");
        let task_id = start["task_id"].as_str().expect("task id");
        let run_id = start["run_id"].as_str().expect("run id");
        let run = parse_line(&format!(
            r#"{{"jsonrpc":"2.0","id":2,"method":"task.run","params":{{"task_id":"{task_id}"}}}}"#
        ));
        if run.error.is_some() {
            panic!("run error: {:?}", run.error);
        }
        assert_eq!(run.result.unwrap()["status"], json!("Completed"));

        let mcp_log = std::fs::read_to_string(temp.path().join("mcp-count.log")).expect("mcp log");
        assert!(mcp_log.lines().filter(|line| *line == "tools/list").count() >= 2);
        assert_eq!(
            mcp_log
                .lines()
                .filter(|line| *line == "tools/call:search_code")
                .count(),
            1
        );

        let events = BrownieStore::new(temp.path())
            .tasks()
            .read_ledger_events(run_id)
            .expect("events");
        assert!(events.iter().any(|event| {
            event.kind == LedgerEventKind::ToolIntentApproved
                && event
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("tool_id"))
                    == Some(&json!("mcp.github.search_code"))
        }));
        let completed = events
            .iter()
            .find(|event| {
                event.kind == LedgerEventKind::ToolExecutionCompleted
                    && event
                        .payload
                        .as_ref()
                        .and_then(|payload| payload.get("tool_id"))
                        == Some(&json!("mcp.github.search_code"))
            })
            .expect("mcp execution completed");
        let completed_payload = completed.payload.as_ref().expect("completed payload");
        assert_eq!(completed_payload["status"], json!("Completed"));
        assert_eq!(
            completed_payload["catalog_provenance"]["server_id"],
            json!("github")
        );
        assert!(completed_payload["mcp"]["result_fingerprint"]
            .as_str()
            .unwrap()
            .starts_with("sha256:"));
        assert!(events
            .iter()
            .any(|event| event.kind == LedgerEventKind::SecondPassPromptBuilt));
        assert!(events.iter().any(|event| {
            event.kind == LedgerEventKind::SecondPassLlmResponseReceived
                && serde_json::to_string(event.payload.as_ref().expect("payload"))
                    .expect("payload json")
                    .contains("MCP_RESULT_7f91c2")
        }));
        let second_pass_prompt = events
            .iter()
            .find(|event| event.kind == LedgerEventKind::SecondPassPromptBuilt)
            .and_then(|event| event.payload.as_ref())
            .expect("second-pass prompt payload");
        assert!(serde_json::to_string(second_pass_prompt)
            .expect("second-pass prompt json")
            .contains("MCP_RESULT_7f91c2"));
        let ledger_json = serde_json::to_string(&events).expect("ledger json");
        assert!(!ledger_json.contains(r#""jsonrpc":"2.0""#));
        assert!(!ledger_json.contains(r#""method":"tools/call""#));
    }

